  const $ = (selector) => document.querySelector(selector);
  const $$ = (selector) => Array.from(document.querySelectorAll(selector));

  // Pages contributed by market plugin packages (marketplace/packages/*/
  // content/web). Each plugin fragment registers its own state slice and boot
  // initializer here; core dashboard code never references a specific plugin.
  const pluginPages = {};
  const MAX_REPO_FILE_FINDER_RESULTS = 500;
  const MAX_REPO_FILE_FINDER_SECONDS = 6;
  const REPO_COLLECTION_PAGE_SIZE = 25;
  const DASHBOARD_THEME_KEY = "forkmesh.dashboard.theme";
  const AGENT_RECENT_REPOSITORIES_STORAGE_PREFIX =
    "forkmesh.agent.recentRepositories.v1:";
  const AGENT_RECENT_REPOSITORIES_LIMIT = 20;
  function installIncrementalIcons() {
    const lucide = window.lucide;
    if (!lucide?.createIcons || !lucide.icons || !lucide.createElement || lucide.createIcons.incremental) return;
    const svgNs = "http://www.w3.org/2000/svg";
    const iconKey = (name) => name.replace(/(\w)(\w*)(_|-|\s*)/g,
      (_, first, rest) => first.toUpperCase() + rest.toLowerCase());
    const renderIcon = (element) => {
      const name = element.getAttribute("data-lucide");
      const icon = name && lucide.icons[iconKey(name)];
      if (!icon || !element.parentNode) return;
      const [tag, defaults, children] = icon;
      const own = {};
      for (const attribute of Array.from(element.attributes)) own[attribute.name] = attribute.value;
      const classes = ["lucide", `lucide-${name}`, ...String(own.class || "").split(" ")]
        .map((value) => value.trim()).filter(Boolean);
      const attrs = { ...defaults, "data-lucide": name, ...own, class: [...new Set(classes)].join(" ") };
      element.parentNode.replaceChild(lucide.createElement([tag, attrs, children]), element);
    };
    const createIcons = (options) => {
      if (options && Object.keys(options).length) return lucide.createIcons.full(options);
      for (const element of Array.from(document.querySelectorAll("[data-lucide]"))) {
        if (element.namespaceURI === svgNs
          && element.classList.contains(`lucide-${element.getAttribute("data-lucide")}`)) continue;
        renderIcon(element);
      }
    };
    createIcons.full = lucide.createIcons;
    createIcons.incremental = true;
    lucide.createIcons = createIcons;
  }
  installIncrementalIcons();

  function readSession() {
    try {
      return JSON.parse(localStorage.getItem("forkmesh.session") || "null");
    } catch (_) {
      return null;
    }
  }

  // app/www/world are access layers in front of one public site. Anything a
  // user reads, copies, or shares — a profile, a clone address, a referral
  // link, a fediverse handle, an MCP endpoint — is spelled on the apex
  // forkmesh.com; only routing (repoApiBase, the API origin) names a service
  // subdomain. A self-hosted or local deployment keeps its own origin.
  const OFFICIAL_SERVICE_HOSTS = new Set([
    "app.forkmesh.com",
    "forkmesh.com",
    "world.forkmesh.com",
  ]);

  function publicSiteOrigin() {
    return OFFICIAL_SERVICE_HOSTS.has(location.hostname.toLowerCase())
      ? "https://forkmesh.com"
      : location.origin;
  }

  function signedOutHomeUrl() {
    return `${publicSiteOrigin()}/`;
  }

  const USER_NAME_RE = /^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$/;
  const USER_NAME_BATCH = 50;

  function userNameKey(name) {
    const key = String(name || "").trim().replace(/^@/, "").toLowerCase();
    return USER_NAME_RE.test(key) ? key : "";
  }

  function rememberUserNameCase(name, nameCase) {
    const key = userNameKey(name);
    const text = String(nameCase || "").trim();
    if (!key || text.toLowerCase() !== key) return false;
    if (!state.userNameCases) state.userNameCases = new Map();
    const changed = state.userNameCases.get(key) !== text;
    state.userNameCases.set(key, text);
    return changed;
  }

  function userDisplayName(name) {
    const text = String(name || "").trim();
    const key = userNameKey(text);
    if (!key) return text;
    const known = state.userNameCases?.get(key);
    if (known) return text.startsWith("@") ? `@${known}` : known;
    return text;
  }

  function userNameHtml(name) {
    const text = String(name || "").trim();
    const key = userNameKey(text);
    if (!key) return escapeHtml(text);
    return `<span data-user-name="${escapeHtml(key)}">${escapeHtml(userDisplayName(text))}</span>`;
  }

  async function loadUserNameCases(names) {
    if (!state.userNameCasesAsked) state.userNameCasesAsked = new Set();
    const wanted = [...new Set((names || []).map(userNameKey).filter(Boolean))]
      .filter((key) => !state.userNameCasesAsked.has(key) && !state.userNameCases?.has(key));
    let changed = false;
    for (let start = 0; start < wanted.length; start += USER_NAME_BATCH) {
      const batch = wanted.slice(start, start + USER_NAME_BATCH);
      batch.forEach((key) => state.userNameCasesAsked.add(key));
      try {
        const response = await fetch(`/api/accounts/name-case?names=${encodeURIComponent(batch.join(","))}`, {
          credentials: "omit",
          headers: { accept: "application/json" },
        });
        const data = response.ok ? await response.json() : null;
        for (const [key, value] of Object.entries(data?.names || {})) {
          if (rememberUserNameCase(key, value)) changed = true;
        }
      } catch (_) {}
    }
    return changed;
  }

  function applyUserNameCases(root) {
    const scope = root || document;
    const nodes = scope.querySelectorAll ? [...scope.querySelectorAll("[data-user-name]")] : [];
    for (const node of nodes) {
      const key = node.getAttribute("data-user-name");
      const known = state.userNameCases?.get(key);
      if (!known) continue;
      const text = String(node.textContent || "");
      const at = text.startsWith("@") ? "@" : "";
      if (text.slice(at.length).toLowerCase() === key && text !== `${at}${known}`) {
        node.textContent = `${at}${known}`;
      }
    }
    return nodes;
  }

  async function hydrateUserNames(root) {
    const nodes = applyUserNameCases(root);
    const keys = nodes.map((node) => node.getAttribute("data-user-name"));
    if (await loadUserNameCases(keys)) applyUserNameCases(root);
  }

  function watchUserNames() {
    if (state.userNameWatch || typeof MutationObserver === "undefined" || !document.body) return;
    let timer = 0;
    state.userNameWatch = new MutationObserver(() => {
      if (timer) return;
      timer = setTimeout(() => {
        timer = 0;
        void hydrateUserNames(document);
      }, 50);
    });
    state.userNameWatch.observe(document.body, { childList: true, subtree: true });
    void hydrateUserNames(document);
  }

  function publicProfileUrl(name, suffix = "") {
    const handle = String(name || "").trim().toLowerCase();
    return handle
      ? `${publicSiteOrigin()}/@${encodeURIComponent(handle)}${suffix}`
      : `${publicSiteOrigin()}/@username${suffix}`;
  }

  // Issue #592: an account whose address nobody has confirmed is held out of
  // the product, so every dashboard document bounces it to the pending screen.
  // Deliberately `=== false` rather than falsy: a stored session written before
  // the flag existed carries no opinion, and hydrateCanonicalProfile settles it
  // from the server a moment later rather than guessing "unverified" here.
  const VERIFY_PENDING_PATH = "/verify-pending";

  function verificationPending(session) {
    return Boolean(session?.email) && session?.emailVerified === false;
  }

  function bounceToVerification(session) {
    if (!verificationPending(session)) return false;
    location.replace(VERIFY_PENDING_PATH);
    return true;
  }

  function normalizeDashboardTheme(theme) {
    return theme === "light" ? "light" : "dark";
  }

  function readDashboardTheme() {
    try {
      const cookieTheme = document.cookie
        .split(";")
        .map((part) => part.trim())
        .find((part) => part.startsWith("forkmesh_theme="))
        ?.slice("forkmesh_theme=".length);
      return normalizeDashboardTheme(
        localStorage.getItem(DASHBOARD_THEME_KEY) ||
        localStorage.getItem("forkmesh.theme") ||
        cookieTheme
      );
    } catch (_) {
      return "dark";
    }
  }

  function renderAppearanceTheme(theme = readDashboardTheme()) {
    const current = normalizeDashboardTheme(theme);
    $$("[data-appearance-theme]").forEach((button) => {
      const active = button.dataset.appearanceTheme === current;
      button.setAttribute("aria-checked", active ? "true" : "false");
      button.classList.toggle("border-border", active);
      button.classList.toggle("bg-secondary", active);
      button.classList.toggle("shadow-sm", active);
      button.querySelector("[data-appearance-check]")?.classList.toggle("hidden", !active);
    });
    const status = $("[data-appearance-theme-status]");
    if (status) {
      status.textContent = current === "light"
        ? "Light mode is active for the dashboard."
        : "Dark mode is active for the dashboard.";
    }
  }

  function applyDashboardTheme(theme) {
    const nextTheme = normalizeDashboardTheme(theme);
    document.documentElement.dataset.dashboardTheme = nextTheme;
    document.documentElement.style.colorScheme = nextTheme;
    document.querySelector('meta[name="theme-color"]')?.setAttribute(
      "content",
      nextTheme === "light" ? "#f6f8fb" : "#090909",
    );
    renderAppearanceTheme(nextTheme);
    return nextTheme;
  }

  function saveDashboardTheme(theme) {
    const nextTheme = normalizeDashboardTheme(theme);
    try {
      localStorage.setItem(DASHBOARD_THEME_KEY, nextTheme);
      localStorage.setItem("forkmesh.theme", nextTheme);
      const sharedDomain = location.hostname === "forkmesh.com" ||
        location.hostname.endsWith(".forkmesh.com")
        ? "; Domain=.forkmesh.com" : "";
      document.cookie = `forkmesh_theme=${nextTheme}; Path=/; Max-Age=31536000; SameSite=Lax${sharedDomain}`
        + (location.protocol === "https:" ? "; Secure" : "");
    } catch (_) {}
    applyDashboardTheme(nextTheme);
  }

  function renderGenieSetting() {
    const toggle = $("[data-genie-visible]");
    if (!toggle) return;
    const genie = window.ForkMeshGenie;
    const ready = typeof genie?.isOff === "function";
    toggle.setAttribute("aria-checked", ready && genie.isOff() ? "false" : "true");
    toggle.disabled = !ready;
  }

  function saveGenieSetting(shown) {
    const genie = window.ForkMeshGenie;
    if (shown) genie?.show?.();
    else genie?.hide?.();
    renderGenieSetting();
  }

  function watchGenieSetting() {
    window.addEventListener("forkmesh:genie", renderGenieSetting);
    if (document.readyState !== "complete") {
      document.addEventListener("DOMContentLoaded", renderGenieSetting, { once: true });
    }
    renderGenieSetting();
  }

  const HOME_REDIRECT_COOKIE = "forkmesh_home";

  function homeRedirectEnabled() {
    let cookie = "";
    try {
      cookie = document.cookie;
    } catch (_) {}
    const entry = String(cookie || "").split(";").map((part) => part.trim())
      .find((part) => part.startsWith(HOME_REDIRECT_COOKIE + "="));
    return !entry || entry.slice(HOME_REDIRECT_COOKIE.length + 1) !== "stay";
  }

  function renderHomeRedirectSetting() {
    const toggle = $("[data-home-redirect]");
    if (!toggle) return;
    toggle.setAttribute("aria-checked", homeRedirectEnabled() ? "true" : "false");
  }

  function saveHomeRedirectSetting(enabled) {
    const sharedDomain = location.hostname === "forkmesh.com" ||
      location.hostname.endsWith(".forkmesh.com")
      ? "; Domain=.forkmesh.com" : "";
    try {
      document.cookie = `${HOME_REDIRECT_COOKIE}=${enabled ? "dashboard" : "stay"}; Path=/; Max-Age=31536000; SameSite=Lax${sharedDomain}`
        + (location.protocol === "https:" ? "; Secure" : "");
    } catch (_) {}
    renderHomeRedirectSetting();
  }

  function watchHomeRedirectSetting() {
    if (document.readyState !== "complete") {
      document.addEventListener("DOMContentLoaded", renderHomeRedirectSetting, { once: true });
    }
    renderHomeRedirectSetting();
  }

  function writeSession(nextSession) {
    const storedSession = nextSession && typeof nextSession === "object"
      ? {
          ...nextSession,
          sessionToken: (
            location.protocol === "https:" &&
            nextSession.sessionToken &&
            window.ForkMeshAPI?.isSameSite !== false
              ? "cookie"
              : nextSession.sessionToken || ""
          ),
        }
      : nextSession;
    state.session = storedSession;
    if (storedSession?.nodeName || storedSession?.email) document.documentElement?.removeAttribute?.("data-guest");
    try {
      localStorage.setItem("forkmesh.session", JSON.stringify(storedSession));
      document.cookie = "forkmesh_session=1; Path=/; Max-Age=2592000; SameSite=Lax"
        + (location.protocol === "https:" ? "; Secure" : "");
    } catch (_) {}
  }

  // Existing browser sessions can predate the portable mirror cookie. Login
  // responses mint it now, but a person who stayed signed in across that
  // rollout would otherwise look logged out on their first direct mirror
  // visit until the next focus revalidation. Refresh the signed, domain-wide
  // grant in the background at most once every four hours (its lifetime is
  // twelve), without holding up App paint or introducing a poll.
  const PORTABLE_SESSION_REFRESH_KEY = "forkmesh.portableSessionRefresh.v2";
  const PORTABLE_SESSION_REFRESH_MS = 4 * 60 * 60 * 1000;
  const PORTABLE_SESSION_RETRY_MS = 5 * 60 * 1000;

  async function ensurePortableControllerSession(force = false) {
    const hostname = String(location.hostname || "").toLowerCase();
    if (hostname !== "forkmesh.com" && !OFFICIAL_SERVICE_HOSTS.has(hostname)) {
      return null;
    }
    const session = readSession();
    const nodeName = String(session?.nodeName || "").trim().toLowerCase();
    if (!nodeName || !session?.sessionToken) return null;

    const now = Date.now();
    let marker = {};
    try {
      marker = JSON.parse(
        localStorage.getItem(PORTABLE_SESSION_REFRESH_KEY) || "{}",
      ) || {};
    } catch (_) {}
    if (
      !force
      && String(marker.nodeName || "").toLowerCase() === nodeName
      && (
        now - Number(marker.refreshedAt || 0) < PORTABLE_SESSION_REFRESH_MS
        || now - Number(marker.attemptedAt || 0) < PORTABLE_SESSION_RETRY_MS
      )
    ) {
      return null;
    }
    const pendingMarker = {
      nodeName,
      refreshedAt: Number(marker.refreshedAt || 0),
      attemptedAt: now,
    };
    try {
      localStorage.setItem(
        PORTABLE_SESSION_REFRESH_KEY, JSON.stringify(pendingMarker),
      );
    } catch (_) {}
    try {
      const token = String(session.sessionToken || "");
      const response = await fetch("/api/accounts/sessions", {
        method: "GET",
        credentials: "same-origin",
        cache: "no-store",
        headers: {
          accept: "application/json",
          ...(token && token !== "cookie"
            ? { authorization: `Bearer ${token}` }
            : {}),
        },
      });
      if (!response.ok) return null;
      // "current" is the relay declining to re-sign a grant this browser was
      // handed within the refresh window; the cookie it holds is still good.
      const portable = response.headers.get("x-forkmesh-portable-session");
      if (portable !== "issued" && portable !== "current") return null;
      const refreshed = { ...pendingMarker, refreshedAt: Date.now() };
      try {
        localStorage.setItem(
          PORTABLE_SESSION_REFRESH_KEY, JSON.stringify(refreshed),
        );
      } catch (_) {}
      return refreshed;
    } catch (_) {
      return null;
    }
  }

  // A portable login is carried between forkmesh.com hosts by the signed,
  // domain-scoped HttpOnly cookie. localStorage cannot cross origins, though,
  // so a mirror opened for the first time would otherwise render as signed
  // out even while its own API already recognizes the user. Hydrate only from
  // the mirror's local session endpoint; the controller hosts already manage
  // their richer account session and must not gain another background request.
  async function hydratePortableMirrorSession() {
    const hostname = String(location.hostname || "").toLowerCase();
    if (hostname === "forkmesh.com" || OFFICIAL_SERVICE_HOSTS.has(hostname)) {
      return null;
    }

    const controller = typeof AbortController === "function"
      ? new AbortController() : null;
    const timeout = window.setTimeout(() => controller?.abort(), 2000);
    try {
      // The page's head script asked already (dashboard/shell.html).
      const check = window.__forkmeshSessionCheck;
      const early = check?.kind === "mirror" ? check.pending : null;
      if (early) window.__forkmeshSessionCheck = null;
      const response = early
        ? await Promise.race([early, new Promise((_, reject) => {
          controller?.signal.addEventListener("abort", () => reject(new Error("timeout")));
        })]).then((result) => {
          if (!result) throw new Error("session_check_failed");
          return { ok: result.ok, status: result.status, json: async () => result.payload };
        })
        : await fetch("/api/accounts/sessions", {
          method: "GET",
          credentials: "same-origin",
          cache: "no-store",
          headers: { Accept: "application/json" },
          signal: controller?.signal,
        });
      if (!response.ok) {
        // localStorage belongs to a previous mirror visit and cannot prove a
        // current login. Remove it when this node rejects the shared cookie so
        // switching accounts on App is reflected on the next direct visit.
        if (response.status === 401 || response.status === 403) {
          state.session = null;
          try { localStorage.removeItem("forkmesh.session"); } catch (_) {}
        }
        return null;
      }
      const payload = await response.json();
      const account = payload?.account;
      const nodeName = String(account?.nodeName || "").trim();
      if (!payload?.portable || !nodeName) return null;

      const hydrated = {
        ...account,
        nodeName,
        sessionToken: "cookie",
        portable: true,
        controllerIndependent: payload.controllerIndependent === true,
      };
      writeSession(hydrated);
      return hydrated;
    } catch (_) {
      return null;
    } finally {
      window.clearTimeout?.(timeout);
    }
  }

  // On App itself the HttpOnly account cookie is the login and this origin's
  // localStorage marker only a copy. The copy can go missing while the cookie
  // is live, and the dashboard then rendered a signed-in browser as a guest
  // (and bounced Settings to /login) even though the homepage, World and the
  // API all still knew the account. Rebuild the copy from the cookie before
  // the chrome decides who is signed in, as WWW and World already do. A guest
  // has no cookie, so the check is a D1-free 401. An answer slower than the
  // budget still lands: the page reloads once into the signed-in view.
  const CONTROLLER_SESSION_RESTORE_BUDGET_MS = 1500;

  async function restoreControllerSession() {
    const hostname = String(location.hostname || "").toLowerCase();
    if (hostname !== "forkmesh.com" && !OFFICIAL_SERVICE_HOSTS.has(hostname)) {
      return null;
    }
    if (readSession()?.nodeName) return null;
    const restore = window.ForkMeshAPI?.restoreSession;
    if (typeof restore !== "function") return null;
    // The page's head script asked already (dashboard/shell.html).
    const check = window.__forkmeshSessionCheck;
    const early = check?.kind === "controller" ? check.pending : null;
    if (early) window.__forkmeshSessionCheck = null;
    const pending = (early || Promise.resolve().then(restore)).catch(() => null);
    let timer = 0;
    const late = Symbol("late");
    const restored = await Promise.race([
      pending,
      new Promise((resolve) => {
        timer = window.setTimeout(() => resolve(late), CONTROLLER_SESSION_RESTORE_BUDGET_MS);
      }),
    ]);
    window.clearTimeout(timer);
    if (restored === late) {
      pending.then((session) => {
        if (session?.nodeName) location.reload();
      });
      return null;
    }
    return restored || null;
  }

  function clearForkMeshBrowserState() {
    const preserved = new Set([
      "forkmesh.analyticsConsent.v1",
      "forkmesh.apiOrigin",
      "forkmesh.dashboard.theme",
      "forkmesh.genie.off",
      "forkmesh.theme",
    ]);
    try {
      for (let index = localStorage.length - 1; index >= 0; index -= 1) {
        const key = localStorage.key(index);
        if (key?.startsWith("forkmesh.") && !preserved.has(key)) {
          localStorage.removeItem(key);
        }
      }
      for (let index = sessionStorage.length - 1; index >= 0; index -= 1) {
        const key = sessionStorage.key(index);
        if (key?.startsWith("forkmesh.")) sessionStorage.removeItem(key);
      }
      state.fetchJsonCache = {};
      state.fetchJsonInflight = {};
      document.cookie = "forkmesh_session=; Path=/; Max-Age=0; SameSite=Lax";
      document.cookie = "forkmesh_account=; Path=/; Max-Age=0; SameSite=Strict";
      document.cookie = "forkmesh_admin=; Path=/; Max-Age=0; SameSite=Lax";
      try {
        new BroadcastChannel("forkmesh.session").postMessage({
          type: "signed-out",
        });
      } catch (_) {}
    } catch (_) {}
    if (!("caches" in window)) return Promise.resolve();
    return caches.keys()
      .then((names) => Promise.all(names.map((name) => caches.delete(name))))
      .catch(() => {});
  }

  function logout() {
    let serverLogout = Promise.resolve();
    try {
      // The Worker owns session invalidation: this clears the HttpOnly
      // forkmesh_admin cookie so the admin page is unreachable after logout.
      // site-header.js (marketing pages) calls the same endpoint.
      serverLogout = fetch("/api/accounts/logout", { method: "POST",
        keepalive: true,
        credentials: "same-origin",
        cache: "no-store",
      }).catch(() => {});
    } catch (_) {}
    const cleanup = clearForkMeshBrowserState();
    let redirected = false;
    const finish = () => {
      if (redirected) return;
      redirected = true;
      location.replace(signedOutHomeUrl());
    };
    Promise.allSettled([serverLogout, cleanup]).then(finish);
    window.setTimeout(finish, 1200);
  }

  // Revalidation floor for the event-driven session check below. A user who
  // alt-tabs repeatedly fires `focus`/`visibilitychange` in bursts, and without
  // a floor that burst is just the 20s poll back under another name.
  const SESSION_REVALIDATE_MIN_MS = 5 * 60 * 1000;

  // Session revocation used to cost a `GET /api/accounts/sessions` every 20
  // seconds per open tab — 180 requests an hour to learn "still signed in",
  // with the whole body thrown away (only the 401 mattered). It was the single
  // most-requested endpoint on the relay.
  //
  // The timer is gone. Liveness now rides the same per-account WebSocket the
  // desktop node and /world already hold (public/account-events.js): every
  // (re)connect trades the stored session for a fresh event ticket, so a
  // revoked session surfaces as an authoritative 401/403 on that handshake for
  // no extra request. Sign-in state is the socket's job, exactly like unread
  // counts (docs/operations/polling-elimination.md).
  //
  // What survives is not a poll: a floor-limited revalidation on focus and
  // visibilitychange, which covers the tab that was hidden while the socket was
  // down, and the cross-tab BroadcastChannel that makes one logout clear the
  // rest immediately.
  function startAccountSessionWatch() {
    let checking = false;
    let lastValidatedMs = Date.now();
    const validate = async (force) => {
      if (checking || !readSession()) return;
      // A hidden tab has nothing to revalidate for, and a check inside the
      // floor is the poll again. Neither applies to `force`: that is the event
      // channel reporting the relay refused this session, which has to boot the
      // tab whether or not anyone is looking at it.
      if (!force &&
          (document.hidden ||
           Date.now() - lastValidatedMs < SESSION_REVALIDATE_MIN_MS)) {
        return;
      }
      checking = true;
      try {
        const session = readSession();
        const token = String(session?.sessionToken || "");
        const response = await fetch("/api/accounts/sessions", {
          headers: {
            accept: "application/json",
            ...(token && token !== "cookie"
              ? { authorization: `Bearer ${token}` }
              : {}),
          },
          credentials: "same-origin",
          cache: "no-store",
        });
        if (response.status === 401) logout();
        // Only an answered request refreshes the floor. A network failure must
        // stay eligible, or an offline stretch would suppress the next real
        // check for five minutes after the connection came back.
        else lastValidatedMs = Date.now();
      } catch (_) {
        // Losing the network is not a logout signal. The next check retries;
        // only an authoritative 401 boots the browser.
      } finally {
        checking = false;
      }
    };
    window.addEventListener("focus", () => void validate(false));
    document.addEventListener("visibilitychange", () => {
      if (!document.hidden) void validate(false);
    });
    startAccountEventChannel(() => void validate(true));
    try {
      const channel = new BroadcastChannel("forkmesh.session");
      channel.addEventListener("message", (event) => {
        if (event.data?.type === "signed-out" && readSession()) {
          clearForkMeshBrowserState().finally(() => location.replace(signedOutHomeUrl()));
        }
      });
    } catch (_) {}
  }

  // Join the per-account push channel. The dashboard was the last signed-in
  // surface still asking the relay questions on a timer; chat.js and world.js
  // have held this socket since the unread counts moved to pushes.
  //
  // `onSignedOut` fires when the relay refuses to issue an event ticket for the
  // stored session — the authoritative revocation the 20s poll existed to
  // catch. `revalidate` is the belt-and-braces confirmation: the ticket
  // endpoint and the session endpoint are different routes, so one real
  // signed read decides whether to actually boot the browser.
  //
  // Dynamic import because the bundle is a classic script, not a module. A
  // browser that cannot load it keeps the focus/visibilitychange checks, which
  // is the same coverage the page had before the socket existed.
  function startAccountEventChannel(revalidate) {
    if (state.accountEvents || !readSession()) return;
    let connectedOnce = false;
    import("/account-events.js")
      .then(({ createAccountEventChannel }) => {
        if (state.accountEvents) return;
        state.accountEvents = createAccountEventChannel({
          sessionToken: () => String(readSession()?.sessionToken || ""),
          onSignedOut: revalidate,
          onConnected: () => {
            if (connectedOnce) {
              window.dispatchEvent(new CustomEvent(
                "forkmesh:mirror-signal", { detail: { catchUp: true } },
              ));
              window.dispatchEvent(new CustomEvent("forkmesh:cloud-agents"));
              void checkForDashboardUpdate(true);
            }
            connectedOnce = true;
          },
          onTopic: (topic, frame) => {
            // One read of the surface the topic names, and only when the page
            // actually shows it. No topic here is a "did anything change?"
            // question — the relay only sends one because something did.
            if (topic === "pings" || topic === "issues") {
              if (typeof loadNotifications === "function") {
                void loadNotifications();
              }
            }
            if (topic === "cloud-agents" || topic === "cloud-agents-live") {
              window.dispatchEvent(new CustomEvent("forkmesh:cloud-agents"));
            }
            if (topic === "agents") {
              window.dispatchEvent(new CustomEvent("forkmesh:desktop-agents"));
            }
            if (topic === "catalog") {
              window.dispatchEvent(new CustomEvent(
                "forkmesh:mirror-signal",
                { detail: { repo: String(frame?.repo || "") } },
              ));
            }
            if (topic === "direct-messages") {
              window.dispatchEvent(new CustomEvent("forkmesh:direct-messages"));
            }
          },
        });
        state.accountEvents.start();
      })
      .catch(() => {});
  }

  function escapeHtml(value) {
    return String(value ?? "").replace(/[&<>"']/g, (char) => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#039;",
    })[char]);
  }

  // Loading placeholder: spinner (see .fm-spinner in the shell <style>)
  // followed by the label. `label` is inserted as HTML so call sites can keep
  // their pre-escaped fragments.
  function loadingHtml(label) {
    return `<span class="fm-spinner" aria-hidden="true"></span>${label}`;
  }

  // In-flight state for a form's submit button (issue #687): disabled, with a
  // spinner in place of its icon and a progress label, restored verbatim when
  // the request settles. `label` is plain text.
  function setSubmitBusy(button, busy, label) {
    if (!button) return;
    if (busy) {
      if (button._idleHtml === undefined) button._idleHtml = button.innerHTML;
      button.disabled = true;
      button.setAttribute("aria-busy", "true");
      button.innerHTML = loadingHtml(escapeHtml(label));
      return;
    }
    if (button._idleHtml !== undefined) button.innerHTML = button._idleHtml;
    button._idleHtml = undefined;
    button.disabled = false;
    button.removeAttribute("aria-busy");
  }

  // One formatter for the page: building an Intl.NumberFormat per call cost
  // ~12 ms of the repository page's first render (hundreds of counts).
  let countFormatter = null;
  function formatCount(value) {
    const number = Number(value) || 0;
    countFormatter ||= new Intl.NumberFormat();
    return countFormatter.format(number);
  }

  // Compose-identity chip: avatar + username shown next to any box where the
  // session user is about to send content (issues, replies, reviews). Built as
  // an HTML string so it can be dropped straight into the template-literal forms
  // in 06/07; mirrors the initial/avatarPng logic in applyAvatar().
  function composeIdentityHtml(session, verb) {
    const name = String(session?.nodeName || session?.email || "you");
    const initial = escapeHtml((name[0] || "F").toUpperCase());
    const avatarPng = String(session?.avatarPng || "");
    const inner = avatarPng
      ? `<img class="h-full w-full object-cover" src="data:image/png;base64,${avatarPng}" alt="${escapeHtml(name)} avatar" />`
      : `<span class="text-[10px] font-semibold text-muted-foreground">${initial}</span>`;
    const label = verb
      ? `<span class="text-muted-foreground">${escapeHtml(verb)} as</span> <span class="font-semibold text-foreground">${escapeHtml(name)}</span>`
      : `<span class="font-semibold text-foreground">${escapeHtml(name)}</span>`;
    return `<span class="inline-flex min-w-0 items-center gap-2 text-xs">
        <span class="flex h-6 w-6 shrink-0 items-center justify-center overflow-hidden rounded-full border border-border bg-secondary">${inner}</span>
        <span class="min-w-0 truncate">${label}</span>
      </span>`;
  }

  const ISSUE_PERSON_HANDLE_RE = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?$/;

  function issuePersonHandle(name) {
    const text = String(name || "").trim().replace(/^@/, "");
    return ISSUE_PERSON_HANDLE_RE.test(text) && !text.includes("--") ? text.toLowerCase() : "";
  }

  function issueActorIsBot(name) {
    const text = String(name || "").trim();
    if (!text) return false;
    if (/\[bot\]$/i.test(text)) return true;
    return typeof repoContributorIsBot === "function" && repoContributorIsBot({ name: text });
  }

  function issueActorPixels(size) {
    const match = /\bh-(\d+(?:\.5)?)\b/.exec(String(size || ""));
    return match ? Math.round(Number(match[1]) * 4) : 28;
  }

  function issuePersonProfileHref(handle) {
    return handle && validNodeName(handle) ? publicProfileUrl(handle) : "";
  }

  function issueActorAvatarHtml(name, author = "", size = "h-7 w-7", agent = false, link = true) {
    const label = String(name || author || (agent ? "Agent" : "unknown"));
    const bot = agent || issueActorIsBot(label);
    const sessionName = String(state.session?.nodeName || state.session?.email || "");
    const ownAvatar = !bot && label.toLowerCase() === sessionName.toLowerCase()
      ? String(state.session?.avatarPng || "") : "";
    const handle = bot ? "" : issuePersonHandle(label);
    const pixels = issueActorPixels(size);
    const inner = bot
      ? `<i data-lucide="bot" class="${pixels <= 24 ? "h-3.5 w-3.5" : pixels <= 32 ? "h-4 w-4" : "h-5 w-5"} text-muted-foreground"></i>`
      : ownAvatar
        ? `<img class="h-full w-full object-cover" src="data:image/png;base64,${escapeHtml(ownAvatar)}" alt="" width="${pixels}" height="${pixels}" decoding="async" />`
        : `<span class="text-[9px] font-bold text-muted-foreground">${escapeHtml((label[0] || "?").toUpperCase())}</span>`;
    const hydrate = handle && !ownAvatar ? ` data-issue-actor-avatar="${escapeHtml(handle)}"` : "";
    if (hydrate) watchIssueActorAvatars();
    const classes = `relative flex ${size} shrink-0 items-center justify-center overflow-hidden rounded-full border border-border bg-secondary`;
    const title = bot ? `${label} (bot)` : label;
    if (handle && link) {
      const href = issuePersonProfileHref(handle);
      return `<a${href ? ` href="${escapeHtml(href)}"` : ""} data-issue-person="${escapeHtml(handle)}" title="${escapeHtml(title)}" aria-label="${escapeHtml(`${label}'s profile`)}"${hydrate} class="${classes} hover:ring-2 hover:ring-[var(--dashboard-link)]">${inner}</a>`;
    }
    return `<span title="${escapeHtml(title)}"${bot ? ' data-issue-actor-bot=""' : ""}${hydrate} class="${classes}">${inner}</span>`;
  }

  function issuePersonNameHtml(name, classes = "font-semibold text-foreground") {
    const label = String(name || "").trim() || "unknown";
    if (issueActorIsBot(label)) return `<span class="${classes}">${escapeHtml(label)}</span>`;
    const handle = issuePersonHandle(label);
    if (!handle) return `<span class="${classes}">${userNameHtml(label)}</span>`;
    watchIssueActorAvatars();
    const href = issuePersonProfileHref(handle);
    return `<a${href ? ` href="${escapeHtml(href)}"` : ""} data-issue-person="${escapeHtml(handle)}" class="${classes} hover:text-[var(--dashboard-link)] hover:underline">${userNameHtml(label)}</a>`;
  }

  const issueActorAccounts = new Map();
  const issueActorAccountsSettled = new Map();
  let issueActorAvatarObserver = null;
  let issueActorAvatarFrame = 0;

  function issueActorPortraitPng(value) {
    const png = String(value || "").trim();
    return png.length <= 400_000 && /^[A-Za-z0-9+/]+={0,2}$/.test(png) ? png : "";
  }

  function issueActorAccount(name) {
    const key = String(name || "").trim().toLowerCase();
    if (!key || !validNodeName(key)) return Promise.resolve({ exists: false, png: "" });
    if (!issueActorAccounts.has(key)) {
      issueActorAccounts.set(key, fetch(`/api/accounts/${encodeURIComponent(key)}`, { headers: { accept: "application/json" } })
        .then((response) => (response.ok ? response.json() : null))
        .then((profile) => ({
          exists: profile?.exists === true,
          png: profile?.exists === true && profile?.profilePrivate !== true
            ? issueActorPortraitPng(profile.avatarPng) : "",
        }))
        .catch(() => ({ exists: false, png: "" }))
        .then((account) => {
          issueActorAccountsSettled.set(key, account);
          return account;
        }));
    }
    return issueActorAccounts.get(key);
  }

  function issueActorPortrait(name) {
    return issueActorAccount(name).then((account) => account.png);
  }

  function issuePersonRoster(handle) {
    if (typeof repoPeopleRosterMatch !== "function") return Promise.resolve(null);
    return repoPeopleRosterMatch(state.selectedRepo, handle).catch(() => null);
  }

  function issuePersonResolve(handle) {
    return Promise.all([issueActorAccount(handle), issuePersonRoster(handle)])
      .then(([account, roster]) => ({ account, roster }));
  }

  function issueActorAvatarImage(avatar, src) {
    const pixels = Math.max(16, Math.round(avatar.getBoundingClientRect?.().width || 0) || 28);
    const image = document.createElement("img");
    image.src = src;
    image.alt = "";
    image.width = pixels;
    image.height = pixels;
    image.loading = "lazy";
    image.decoding = "async";
    image.referrerPolicy = "no-referrer";
    image.className = "absolute inset-0 h-full w-full object-cover";
    image.addEventListener("error", () => image.remove(), { once: true });
    avatar.appendChild(image);
  }

  function hydrateIssuePersonLink(link, found) {
    if (found.account.exists) {
      const href = issuePersonProfileHref(link.dataset.issuePerson);
      if (href) link.setAttribute("href", href);
      return;
    }
    const profile = found.roster?.profile || "";
    if (profile) {
      link.setAttribute("href", profile);
      link.setAttribute("target", "_blank");
      link.setAttribute("rel", "noopener noreferrer nofollow ugc");
      return;
    }
    if (link.hasAttribute("data-issue-mention")) {
      link.replaceWith(document.createTextNode(link.textContent || ""));
      return;
    }
    link.removeAttribute("href");
  }

  function hydrateIssueActorAvatars(root = document) {
    const avatars = [];
    if (root.matches?.("[data-issue-actor-avatar]")) avatars.push(root);
    root.querySelectorAll?.("[data-issue-actor-avatar]").forEach((avatar) => avatars.push(avatar));
    for (const avatar of avatars) {
      if (avatar.dataset.issueActorState) continue;
      avatar.dataset.issueActorState = "loading";
      void issuePersonResolve(avatar.dataset.issueActorAvatar).then((found) => {
        const png = found.account.png;
        const picture = png ? `data:image/png;base64,${png}` : found.roster?.avatarUrl || "";
        avatar.dataset.issueActorState = png ? "image" : picture ? "roster" : "initial";
        if (!picture || !avatar.isConnected) return;
        issueActorAvatarImage(avatar, picture);
      });
    }
    const links = [];
    if (root.matches?.("[data-issue-person]")) links.push(root);
    root.querySelectorAll?.("[data-issue-person]").forEach((link) => links.push(link));
    for (const link of links) {
      if (link.dataset.issuePersonState) continue;
      link.dataset.issuePersonState = "loading";
      void issuePersonResolve(link.dataset.issuePerson).then((found) => {
        link.dataset.issuePersonState = "done";
        if (link.isConnected) hydrateIssuePersonLink(link, found);
      });
    }
  }

  function watchIssueActorAvatars() {
    if (issueActorAvatarObserver || typeof MutationObserver !== "function" || !document.body) return;
    const pending = new Set();
    issueActorAvatarObserver = new MutationObserver((records) => {
      for (const record of records) {
        record.addedNodes.forEach((node) => { if (node.nodeType === 1) pending.add(node); });
      }
      if (!pending.size || issueActorAvatarFrame) return;
      issueActorAvatarFrame = requestAnimationFrame(() => {
        issueActorAvatarFrame = 0;
        const roots = Array.from(pending);
        pending.clear();
        roots.forEach((node) => { if (node.isConnected) hydrateIssueActorAvatars(node); });
      });
    });
    issueActorAvatarObserver.observe(document.body, { childList: true, subtree: true });
    requestAnimationFrame(() => hydrateIssueActorAvatars(document));
  }

  function parseFlexibleDate(value) {
    if (value === undefined || value === null || value === "") return null;
    const numeric = Number(value);
    const date = Number.isFinite(numeric) && numeric > 0
      ? new Date(numeric < 1000000000000 ? numeric * 1000 : numeric)
      : new Date(value);
    return Number.isNaN(date.getTime()) ? null : date;
  }

  function formatDate(value) {
    const date = parseFlexibleDate(value);
    if (!date) return "unknown";
    return date.toLocaleDateString(undefined, {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  }

  // GitHub-style relative timestamp ("3 days ago") for the repo detail page's
  // commit/file dates - absolute dates there made every mirrored commit look
  // identically stale ("Jul 10, 2026") instead of showing recency at a glance.
  function formatTimeAgo(value) {
    const date = parseFlexibleDate(value);
    if (!date) return "unknown";
    const seconds = Math.max(0, Math.round((Date.now() - date.getTime()) / 1000));
    if (seconds < 45) return "just now";
    const units = [
      ["year", 31536000],
      ["month", 2592000],
      ["week", 604800],
      ["day", 86400],
      ["hour", 3600],
      ["minute", 60],
    ];
    for (const [name, secs] of units) {
      const count = Math.floor(seconds / secs);
      if (count >= 1) return `${count} ${name}${count === 1 ? "" : "s"} ago`;
    }
    return "just now";
  }

  // Keep the web tree quiet and scannable: one monochrome folder glyph and one
  // monochrome file glyph, inheriting the page foreground (black in light
  // mode). The desktop browser can retain its richer per-filetype icon set.
  function fileIconHtml(entry, cls = "h-4 w-4 shrink-0") {
    const isTree = entry?.type === "tree";
    return `<i data-lucide="${isTree ? "folder" : "file"}" aria-hidden="true" class="${cls} text-foreground"></i>`;
  }

  function formatSize(bytes) {
    let value = Number(bytes) || 0;
    const units = ["B", "KB", "MB", "GB", "TB"];
    let unit = 0;
    while (value >= 1024 && unit < units.length - 1) {
      value /= 1024;
      unit += 1;
    }
    return `${unit === 0 ? value : value.toFixed(1)} ${units[unit]}`;
  }

  function formatServeSpeed(ms) {
    const value = Number(ms);
    if (!Number.isFinite(value) || value < 0) return "";
    return value < 1000 ? `${Math.round(value)} ms` : `${(value / 1000).toFixed(1)} s`;
  }

  function formatUsd(value) {
    const number = Number(value);
    return `$${(Number.isFinite(number) ? number : 0).toFixed(2)}`;
  }

  function normalizedCount(value) {
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : null;
  }

  function tabCountLabel(value) {
    const number = normalizedCount(value);
    return number === null ? "..." : formatCount(number);
  }

  // The advertised clone/clean URL is the repository's public address, not the
  // machine currently serving the bytes: cloning forkmesh/forkmesh must keep
  // working after the mirror that answered today goes away.
  function cloneUrl(repo) {
    const link = repoLinkUrl(repo);
    return `${publicSiteOrigin()}${link}${link.split("/").length === 2 ? ".git" : ""}`;
  }

  function repoKey(repo) {
    return `${repo.owner || ""}/${repo.name || ""}`;
  }

  // repoKey substitutes for the halves it is missing, so a repository that is
  // not there still yields the truthy "/" — a key that addresses nothing. Code
  // that routes on a key has to ask this instead of testing the key for
  // emptiness: "/" becomes the hostless URL "//", which the browser rejects as
  // invalid rather than navigating (adhoc #104).
  function isRepoKey(value) {
    const [owner, name] = String(value || "").split("/");
    return Boolean(owner && name);
  }

  // Repository bytes are published by nodes, but the catalog resolves every
  // physical route to the user/organization that actually owns the work
  // (ownerKind / logicalOwner / logicalOwners). Lists must show that identity —
  // "forkmesh/forkmesh", never the serving machine's "mirror8/forkmesh".
  // Routing keys stay physical: repoKey/repoPathUrl/data-dashboard-open-repo
  // must keep matching the catalog rows.
  function repoLogicalOwners(repo) {
    const values = Array.isArray(repo?.logicalOwners) ? repo.logicalOwners : [];
    const owners = values.map((value) => ({
      kind: String(value?.kind || "").trim().toLowerCase(),
      owner: String(value?.owner || "").trim(),
    }));
    if (!owners.length) {
      owners.push({
        kind: String(repo?.ownerKind || "").trim().toLowerCase(),
        owner: String(repo?.logicalOwner || "").trim(),
      });
    }
    return owners.filter((value) =>
      value.owner && (value.kind === "user" || value.kind === "organization"));
  }

  // The public address of a repository, resolved without consulting the
  // account that happens to own the serving node. In order: an organization
  // alias on this row, an organization alias registered on any row of the same
  // mirror group, the identity this row explicitly resolved to, and finally
  // the upstream ForkMesh route the row is a copy of. Every one of these is a
  // routable address, so links may use them; a bare user identity is not (no
  // worker rewrite backs /<user>/<repo>) and is therefore label-only.
  function repoPublicOwner(repo) {
    const organization = repoLogicalOwners(repo)
      .find((value) => value.kind === "organization");
    if (organization) return organization.owner;
    const alias = repoAliasOrganization(repo);
    if (alias) return alias;
    // Only the owner segment moves: a route whose repository name differs from
    // this row's would address a different repository, not a rename of it.
    const name = String(repo?.name || "").trim().toLowerCase();
    const sameName = (value) => String(value || "").trim().toLowerCase() === name;
    const resolved = String(repo?.canonicalOwner || "").trim();
    if (resolved && sameName(repo?.canonicalName)) return resolved;
    const canonical = repoCanonicalIdentity(repo);
    return canonical.owner
      && sameName(canonical.name)
      && canonical.owner !== String(repo?.owner || "").trim()
      ? canonical.owner
      : "";
  }

  // Organization aliases are registered on a single catalog row but they name
  // the whole mirror group, so a row that only carries the publishing node's
  // account still resolves to the organization. Indexed once per catalog
  // snapshot: display and link helpers run inside list render loops.
  let repoAliasIndex = { repositories: null, byKey: new Map() };
  let repoAliasIndexBuilding = false;
  function repoAliasOrganizationIndex() {
    const repositories = Array.isArray(state.repositories) ? state.repositories : [];
    if (repoAliasIndex.repositories === repositories) return repoAliasIndex.byKey;
    if (repoAliasIndexBuilding) return new Map();
    repoAliasIndexBuilding = true;
    const byKey = new Map();
    try {
      for (const group of groupRepositories(repositories)) {
        const organization = groupOrganizationAlias(group);
        if (!organization) continue;
        for (const member of [sourceOfTruth(group), ...(group.members || [])]) {
          for (const key of [repoKey(member), repoCanonicalKey(member)]) {
            const text = String(key || "").trim().toLowerCase();
            if (text.length > 1 && text.includes("/")) byKey.set(text, organization);
          }
        }
      }
    } finally {
      repoAliasIndexBuilding = false;
    }
    repoAliasIndex = { repositories, byKey };
    return byKey;
  }

  function repoAliasOrganization(repo) {
    if (!repo?.name) return "";
    const index = repoAliasOrganizationIndex();
    return index.get(repoKey(repo).toLowerCase())
      || index.get(repoCanonicalKey(repo).toLowerCase())
      || "";
  }

  function repoDisplayOwner(repo) {
    const owners = repoLogicalOwners(repo);
    return repoPublicOwner(repo)
      || owners[0]?.owner
      || String(repo?.owner || "").trim();
  }

  function repoDisplayKey(repo) {
    return `${repoDisplayOwner(repo) || ""}/${repo?.name || ""}`;
  }

  // Mirrors of one logical repository are grouped by root commit, so an
  // organization alias registered on any member names the whole group.
  function groupOrganizationAlias(group) {
    const origin = sourceOfTruth(group);
    const name = String(origin?.name || "").trim().toLowerCase();
    for (const member of [origin, ...(group?.members || [])]) {
      if (String(member?.name || "").trim().toLowerCase() !== name) continue;
      const organization = repoLogicalOwners(member)
        .find((value) => value.kind === "organization");
      if (organization) return organization.owner;
    }
    return "";
  }

  function groupDisplayOwner(group) {
    return groupOrganizationAlias(group) || repoDisplayOwner(sourceOfTruth(group));
  }

  function normalizeRepoSegment(value) {
    const text = String(value || "").trim();
    return /^[A-Za-z0-9._:-]+$/.test(text) ? text : "";
  }

  function safeDecodeURIComponent(value) {
    try {
      return decodeURIComponent(value);
    } catch (_) {
      return String(value || "");
    }
  }

  function parseCloneUrlIdentity(value) {
    const raw = String(value || "").trim();
    if (!raw) return null;
    let path = raw;
    try {
      if (/^[a-z][a-z0-9+.-]*:\/\//i.test(path)) {
        path = new URL(path).pathname;
      } else if (path.startsWith("/") && typeof location !== "undefined") {
        path = new URL(path, location.origin).pathname;
      } else if (path.startsWith("git@") && path.includes(":")) {
        path = path.slice(path.indexOf(":") + 1);
      }
    } catch (_) {}
    path = path.split("?")[0].split("#")[0].replace(/^\/+|\/+$/g, "");
    const parts = path.split("/").filter(Boolean);
    const addresses = parts.length === 1 && isThisSiteUrl(raw) ? repoAddresses() : null;
    if (addresses) parts.unshift(addresses.owner);
    if (parts.length < 2) return null;
    const owner = normalizeRepoSegment(safeDecodeURIComponent(parts[parts.length - 2] || ""));
    let name = normalizeRepoSegment(safeDecodeURIComponent(parts[parts.length - 1] || ""));
    if (name.toLowerCase().endsWith(".git")) {
      name = normalizeRepoSegment(name.slice(0, -4));
    }
    return owner && name ? { owner, name } : null;
  }

  // forkmesh.com and app.forkmesh.com are the same deployment, so a clone URL
  // on either host names a route of this site. Comparing bare origins missed
  // the sibling host, which is how a copy advertising
  // https://forkmesh.com/forkmesh/forkmesh still read as its own repository.
  function isThisSiteUrl(value) {
    const bare = (host) => String(host || "").toLowerCase().replace(/^(?:www|app)\./, "");
    const raw = String(value || "").trim();
    if (!raw) return false;
    try {
      const url = new URL(raw, location.origin);
      return url.origin === location.origin
        || (Boolean(url.hostname) && bare(url.hostname) === bare(location.hostname));
    } catch (_) {
      return false;
    }
  }

  function repoCanonicalIdentity(repo) {
    // A fork deliberately retains its parent's clone URL as its upstream.
    // That transport address must never become an identity alias: otherwise a
    // lookup for alice/project could resolve bob's fork solely because bob's
    // catalog row says it was cloned from alice/project.
    if (repoForkParent(repo)) {
      return {
        owner: String(repo?.owner || "").trim(),
        name: String(repo?.name || "").trim(),
      };
    }
    const source = String(repo?.source || "").trim();
    const parsed = parseCloneUrlIdentity(repo?.cloneUrl);
    // A locally served copy can still be a clone of another ForkMesh route.
    // Keep the upstream's canonical name in that case; otherwise a serving
    // node such as jett would relabel forkmesh/forkmesh as jett/forkmesh.
    const isThisForkMeshOrigin = isThisSiteUrl(repo?.cloneUrl);
    if (parsed && (
      source === "remote-clone"
      || (source === "local-node" && isThisForkMeshOrigin)
    )) {
      return parsed;
    }
    return {
      owner: String(repo?.owner || "").trim(),
      name: String(repo?.name || "").trim(),
    };
  }

  function repoCanonicalKey(repo) {
    const id = repoCanonicalIdentity(repo);
    return `${id.owner || ""}/${id.name || ""}`;
  }

  function repoAliasKeys(members, canonical) {
    const aliases = new Set();
    const add = (key) => {
      const text = String(key || "").trim().toLowerCase();
      if (text && text.includes("/")) aliases.add(text);
    };
    add(repoKey(canonical));
    add(repoCanonicalKey(canonical));
    (members || []).forEach((member) => {
      add(repoKey(member));
      add(repoCanonicalKey(member));
    });
    return [...aliases];
  }

  function canonicalRepoFromGroup(primary, members) {
    const all = Array.isArray(members) ? members : [];
    const local = all.find((m) => (m.source || "").trim() === "local-node");
    if (local) {
      return { ...local, _repoAliases: repoAliasKeys(all, local) };
    }
    const mirror = all.find((m) =>
      (m.source || "").trim() === "remote-clone" && parseCloneUrlIdentity(m.cloneUrl));
    const base = mirror || primary || all[0] || {};
    // A fork intentionally keeps its source URL pointed at the parent for
    // upstream pulls. That URL is not the fork's identity; treating it as one
    // redirected /bob/project straight back to /alice/project and erased the
    // provenance the PR composer needs.
    const id = repoForkParent(base)
      ? { owner: base.owner || "", name: base.name || "" }
      : repoCanonicalIdentity(base);
    const canonical = {
      ...base,
      owner: id.owner || base.owner || "",
      name: id.name || base.name || "",
      canonicalOwner: id.owner || "",
      canonicalName: id.name || "",
      servingOwner: base.owner || "",
      servingName: base.name || "",
    };
    if ((base.owner || "") !== canonical.owner || (base.name || "") !== canonical.name) {
      canonical.liveHost = false;
      canonical.cloneOnline = Boolean(base.cloneOnline ?? base.liveHost);
    }
    canonical._repoAliases = repoAliasKeys(all, canonical);
    return canonical;
  }

  function repoMatchesKey(repo, key) {
    const wanted = String(key || "").trim().toLowerCase();
    if (!wanted) return false;
    if (repoKey(repo).toLowerCase() === wanted || repoCanonicalKey(repo).toLowerCase() === wanted) {
      return true;
    }
    return Array.isArray(repo?._repoAliases) && repo._repoAliases.includes(wanted);
  }

  // A fork publishes the public identity of its parent in its signed catalog
  // row. Keep parsing in one place: this value controls both where a pull
  // request is delivered and which repository the composer names as its base.
  function repoForkParent(repo) {
    const value = String(repo?.forkedFrom || "").trim().toLowerCase();
    if (!value || value.length > 161 || value.indexOf("/") !== value.lastIndexOf("/")) {
      return null;
    }
    const [rawOwner, rawName] = value.split("/");
    const owner = normalizeRepoSegment(rawOwner);
    const name = normalizeRepoSegment(rawName);
    if (!owner || !name || owner.length > 80 || name.length > 80) return null;
    // Do not call repoPublicOwner here: alias resolution itself groups repos
    // and would recurse back through repoGroupKey.
    const currentOwner = String(repo?.canonicalOwner || repo?.owner || "").trim().toLowerCase();
    const currentName = String(repo?.name || "").trim().toLowerCase();
    if (owner === currentOwner && name === currentName) return null;
    return { owner, name, key: `${owner}/${name}` };
  }

  function repoMirrorOf(repo) {
    const value = String(repo?.mirrorOf || "").trim();
    return /^https?:\/\/[^\s"'<>]+$/i.test(value) ? value : "";
  }

  function repoReadOnlyMirror(repo) {
    return Boolean(repoMirrorOf(repo)) || repo?.readOnly === true;
  }

  function repoMirrorUpstreamPath(url) {
    try {
      const parsed = new URL(url);
      const parts = parsed.pathname.split("/").filter(Boolean);
      return parts.length >= 2 ? `${parsed.host.replace(/^app\./i, "")}/${parts[0]}/${parts[1].replace(/\.git$/i, "")}` : "";
    } catch (_) {
      return "";
    }
  }

  function repoDescriptionText(...repos) {
    for (const repo of repos) {
      const text = String(repo?.description || "").trim();
      if (text) return text;
    }
    for (const repo of repos) {
      const mirrorOf = repoMirrorOf(repo);
      if (mirrorOf) return `Read-only mirror of ${repoMirrorUpstreamPath(mirrorOf) || mirrorOf}`;
    }
    return "";
  }

  function repoMirrorSyncedAt(repo) {
    const value = Number(repo?.lastSyncedAt || 0);
    return Number.isFinite(value) && value > 0 ? value : 0;
  }

  const REPO_READ_ONLY_MIRROR_HINT = "This repository is a read-only mirror. Fork it to make changes.";

  function rememberRepoMirrorAbout(repo, body) {
    if (!repo || !body || typeof body !== "object") return false;
    const before = `${repoMirrorOf(repo)}|${repoReadOnlyMirror(repo)}|${repoMirrorSyncedAt(repo)}|${repo.upstreamCommit || ""}`;
    if ("mirrorOf" in body) repo.mirrorOf = String(body.mirrorOf || "");
    if ("readOnly" in body) repo.readOnly = body.readOnly === true;
    if (Number(body.lastSyncedAt) > 0) repo.lastSyncedAt = Number(body.lastSyncedAt);
    if (body.upstreamCommit) repo.upstreamCommit = String(body.upstreamCommit);
    return before !== `${repoMirrorOf(repo)}|${repoReadOnlyMirror(repo)}|${repoMirrorSyncedAt(repo)}|${repo.upstreamCommit || ""}`;
  }

  function repoProvenanceHtml(repo) {
    const mirrorOf = repoMirrorOf(repo);
    const parent = mirrorOf ? null : repoForkParent(repo);
    if (!mirrorOf && !parent) return "";
    const linkClass = "dashboard-accent-link min-w-0 truncate font-medium hover:underline";
    if (!mirrorOf) {
      const contribute = `<button type="button" data-repo-contribute title="Open a pull request from this fork to ${escapeHtml(repoDisplayName(parent.key))}" class="fm-btn fm-btn-sm shrink-0"><i data-lucide="git-pull-request"></i>Contribute: Open pull request</button>`;
      return `<span data-repo-provenance-line="fork" class="inline-flex min-w-0 items-center gap-1.5"><i data-lucide="git-fork" aria-hidden="true" class="h-3.5 w-3.5 shrink-0 text-muted-foreground"></i><span class="shrink-0">forked from</span><a data-repo-provenance-link href="${escapeHtml(repoLinkUrl({ owner: parent.owner, name: parent.name }))}" class="${linkClass}">${escapeHtml(repoDisplayName(parent.key))}</a></span>${contribute}`;
    }
    const syncedAt = repoMirrorSyncedAt(repo);
    const commit = String(repo?.upstreamCommit || "").trim();
    const syncedTitle = [
      syncedAt ? new Date(syncedAt).toLocaleString() : "",
      commit ? `serving ${commit.slice(0, 12)}` : "",
    ].filter(Boolean).join(" · ");
    const synced = syncedAt
      ? `<span data-repo-mirror-synced${syncedTitle ? ` title="${escapeHtml(syncedTitle)}"` : ""} class="shrink-0 text-muted-foreground">· synced ${escapeHtml(formatTimeAgo(syncedAt))}</span>`
      : "";
    const notice = `<span data-repo-mirror-notice class="min-w-0 text-[11px] text-muted-foreground">Read-only. Send changes <a href="${escapeHtml(mirrorOf)}" target="_blank" rel="noopener" class="dashboard-accent-link hover:underline">upstream</a> or into a fork.</span>`;
    const fork = `<button type="button" data-repo-mirror-fork title="${escapeHtml(REPO_READ_ONLY_MIRROR_HINT)}" class="fm-btn fm-btn-sm shrink-0"><i data-lucide="git-fork"></i>Fork</button>`;
    const line = `<span data-repo-provenance-line="mirror" class="inline-flex min-w-0 items-center gap-1.5"><i data-lucide="refresh-cw" aria-hidden="true" class="h-3.5 w-3.5 shrink-0 text-muted-foreground"></i><span class="shrink-0">Mirror of</span><a data-repo-provenance-link href="${escapeHtml(mirrorOf)}" target="_blank" rel="noopener" class="${linkClass}">${escapeHtml(repoMirrorUpstreamPath(mirrorOf) || mirrorOf)}</a>${synced}</span>`;
    return `${line}${notice}${fork}`;
  }

  function repoGroupKey(repo) {
    // A fork can have the same root commit as its parent for its entire useful
    // lifetime. Folding solely by rootCommit therefore made a freshly-created
    // fork disappear into the parent repository. Its signed provenance is an
    // explicit boundary; mirrors without that extension keep the legacy
    // content-addressed grouping behavior.
    const parent = repoForkParent(repo);
    if (parent) {
      // Different serving nodes publish the same fork under their physical
      // node names. Group those rows by the owner identity the relay attached
      // to them, while keeping unrelated forks with the same root separate.
      const logicalOwners = repoLogicalOwners(repo);
      const logicalOwner = logicalOwners.find((value) => value.kind === "organization")?.owner
        || logicalOwners[0]?.owner
        || repo?.owner
        || "";
      const owner = normalizeRepoSegment(logicalOwner).toLowerCase();
      const name = normalizeRepoSegment(repo?.name || "").toLowerCase();
      return `fork:${owner}/${name}:from:${parent.key}`;
    }
    const root = (repo?.rootCommit || "").trim();
    return root ? "root:" + root : "name:" + (repo?.name || "").trim().toLowerCase();
  }

  function groupRepositories(repos) {
    const groups = new Map();
    for (const repo of repos) {
      const key = repoGroupKey(repo);
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(repo);
    }
    // Fold empty-root name-keyed mirrors into rooted groups (same logic as worker).
    const rootedByName = new Map();
    for (const [key, members] of groups) {
      if (!key.startsWith("root:")) continue;
      for (const m of members) {
        const n = (m.name || "").trim().toLowerCase();
        if (n && !rootedByName.has(n)) rootedByName.set(n, key);
      }
    }
    for (const [key, members] of [...groups]) {
      if (!key.startsWith("name:")) continue;
      const target = rootedByName.get(key.slice("name:".length));
      if (target && groups.has(target)) {
        groups.get(target).push(...members);
        groups.delete(key);
      }
    }
    return [...groups.values()].map((members) => {
      const sorted = [...members].sort((a, b) => {
        if (!!b.liveHost !== !!a.liveHost) return (b.liveHost ? 1 : 0) - (a.liveHost ? 1 : 0);
        return (b.lastSync || 0) > (a.lastSync || 0) ? 1 : -1;
      });
      const group = { primary: sorted[0], members: sorted };
      group.source = canonicalRepoFromGroup(group.primary, group.members);
      return group;
    });
  }

  function sourceOfTruth(group) {
    const canonical = group.source || canonicalRepoFromGroup(group.primary, group.members);
    return (canonical.owner || canonical.name)
      ? canonical
      : group.members.find((m) => (m.source || "").trim() === "local-node") || group.primary;
  }

  // A page that reads "forkmesh/forkmesh" must also FETCH it there, by the
  // same rule that already governs its links (repoLinkUrl, adhoc #132): no
  // request the site makes should ever name a mirror. `repo.owner` is
  // whichever node published the catalog row we happened to resolve, and
  // sourceOfTruth prefers a source-of-truth row over a live one — so for the
  // flagship it picks a long-retired node whose row still says
  // source:"local-node" while its cloneUrl points at forkmesh/forkmesh. Only
  // that one node ever served /api/repo/<node>/<repo> (a mirror gateway
  // serves exactly its configured owner/name pairs), so every read answered
  // 503 "mirror_unavailable" while healthy mirrors served the identical bytes
  // under the public address. Which mirror actually answers is decided behind
  // that address by the Worker, which rewrites /api/repo/<org>/<repo>/... onto
  // a serving node; a clone URL a node publishes is likewise a real address.
  function repoApiBase(repo) {
    const owner = repoPublicOwner(repo) || repo.owner || "";
    return `/api/repo/${encodeURIComponent(owner)}/${encodeURIComponent(repo.name || "")}`;
  }

  function repositoryViewKey(repo) {
    const owner = repoPublicOwner(repo) || repo?.owner || "";
    return `${owner}/${repo?.name || ""}`.trim().toLowerCase();
  }

  const DIRECT_MIRROR_READ_OPERATIONS = new Set([
    "tree", "blobs", "blob", "raw", "history", "commit", "compare",
    "branches", "search", "stats", "sizes", "release-blob", "merge-preview",
    "about", "mirrors",
  ]);

  // Return direct HTTPS origins for the healthy copies of this repository.
  // The visible route remains /<public-owner>/<repo>; only data requests move
  // off the canonical Worker. A mirror URL contributes its ORIGIN only: the
  // public owner below remains the address the direct gateway is configured to
  // serve (for example forkmesh/forkmesh, never mirror37/forkmesh).
  function directMirrorOriginsForRepo(repo) {
    if (!repo || repo.isPrivate) return [];
    let members = [repo];
    const wanted = new Set([
      repoKey(repo).toLowerCase(),
      repoCanonicalKey(repo).toLowerCase(),
      ...(Array.isArray(repo._repoAliases) ? repo._repoAliases : []),
    ]);
    for (const group of groupRepositories(state.repositories || [])) {
      const candidates = [sourceOfTruth(group), ...(group.members || [])];
      if (candidates.some((item) =>
        wanted.has(repoKey(item).toLowerCase())
        || wanted.has(repoCanonicalKey(item).toLowerCase())
        || (Array.isArray(item?._repoAliases)
          && item._repoAliases.some((key) => wanted.has(String(key).toLowerCase()))))) {
        members = candidates;
        break;
      }
    }
    const origins = [];
    [...members].sort((a, b) =>
      Number(b?.lastSync || b?.updatedAt || 0)
      - Number(a?.lastSync || a?.updatedAt || 0)).forEach((member) => {
      if (member?.cloneOnline === false || member?.liveHost === false) return;
      const address = String(
        member?.mirrorUrl || member?.directUrl || member?.dashboardUrl || "",
      ).trim();
      try {
        const parsed = new URL(address);
        if (parsed.protocol !== "https:" || parsed.username || parsed.password) return;
        if (!origins.includes(parsed.origin)) origins.push(parsed.origin);
      } catch (_) { /* malformed catalog rows are not routing candidates */ }
    });
    return origins;
  }

  function dashboardOnInstance() {
    return Boolean(document?.querySelector?.("script[data-instance-brand]"));
  }

  function platformName() {
    const brand = document?.querySelector?.("script[data-instance-brand]");
    return String(brand?.dataset?.instanceName || "").trim() || "ForkMesh";
  }

  function desktopBrand() {
    return dashboardOnInstance() ? "" : "ForkMesh ";
  }

  function applyPlatformName(root = document) {
    const name = platformName();
    root?.querySelectorAll?.("[data-platform-name]").forEach((element) => {
      if (element.textContent !== name) element.textContent = name;
    });
    const desktop = desktopBrand();
    root?.querySelectorAll?.("[data-desktop-brand]").forEach((element) => {
      if (element.textContent !== desktop) element.textContent = desktop;
    });
  }

  let instanceInfoRequest = null;
  let instanceGitNode = "";

  function instanceInfo() {
    if (!dashboardOnInstance()) return Promise.resolve(null);
    if (!instanceInfoRequest) {
      instanceInfoRequest = fetch("/api/instance", { credentials: "omit", headers: { accept: "application/json" } })
        .then((response) => (response.ok ? response.json() : null))
        .then((info) => {
          instanceGitNode = String(info?.gitNode || "").toLowerCase();
          return info;
        })
        .catch(() => null);
    }
    return instanceInfoRequest;
  }

  function platformAccount(name) {
    const value = String(name || "").trim().toLowerCase();
    return Boolean(value) && dashboardOnInstance() && value === instanceGitNode;
  }

  function shownAccountName(name) {
    return platformAccount(name) ? platformName() : String(name || "");
  }

  async function instancePluginEnabled(id) {
    if (!dashboardOnInstance()) return true;
    const info = await instanceInfo();
    const plugins = Array.isArray(info?.plugins) ? info.plugins : [];
    return plugins.some((plugin) => plugin?.id === id && plugin.enabled);
  }

  const DIRECT_MIRROR_ORIGINS_KEY = "forkmesh.directMirrorOrigins.v1";

  function preconnectDirectMirrorOrigins(origins) {
    if (typeof document?.createElement !== "function") return;
    [...new Set(origins || [])].slice(0, 3).forEach((origin) => {
      let parsed;
      try { parsed = new URL(origin); } catch (_) { return; }
      if (parsed.protocol !== "https:" || parsed.origin === location.origin) return;
      if (document.querySelector(`link[data-forkmesh-mirror-origin="${parsed.origin}"]`)) return;
      const link = document.createElement("link");
      link.rel = "preconnect";
      link.href = parsed.origin;
      link.crossOrigin = "anonymous";
      link.dataset.forkmeshMirrorOrigin = parsed.origin;
      document.head?.appendChild(link);
    });
  }

  function rememberAndPreconnectDirectMirrors(repositories) {
    const origins = [];
    [...(repositories || [])]
      .filter((repo) => repo?.liveHost !== false && repo?.cloneOnline !== false)
      .sort((left, right) =>
        Number(right?.lastSync || right?.updatedAt || 0)
        - Number(left?.lastSync || left?.updatedAt || 0))
      .forEach((repo) => {
        const address = String(
          repo?.mirrorUrl || repo?.directUrl || repo?.dashboardUrl || "",
        ).trim();
        try {
          const parsed = new URL(address);
          if (parsed.protocol === "https:" && !origins.includes(parsed.origin)) {
            origins.push(parsed.origin);
          }
        } catch (_) {}
      });
    const selected = origins.slice(0, 3);
    try {
      localStorage.setItem(DIRECT_MIRROR_ORIGINS_KEY, JSON.stringify(selected));
    } catch (_) {}
    preconnectDirectMirrorOrigins(selected);
  }

  function preconnectRememberedDirectMirrors() {
    try {
      const origins = JSON.parse(
        localStorage.getItem(DIRECT_MIRROR_ORIGINS_KEY) || "[]",
      );
      if (Array.isArray(origins)) preconnectDirectMirrorOrigins(origins);
    } catch (_) {}
  }

  function directRepoRequestCandidates(path, { mutation = false } = {}) {
    let request;
    try { request = new URL(path, location.origin); } catch (_) { return []; }
    if (request.origin !== location.origin) return [];
    const match = /^\/api\/repo\/([^/]+)\/([^/]+)\/([^/]+)$/.exec(request.pathname);
    if (!match) return [];
    const operation = decodeURIComponent(match[3]);
    if (!mutation && !DIRECT_MIRROR_READ_OPERATIONS.has(operation)) return [];
    if (mutation && !["issues", "pulls", "discussions"].includes(operation)) return [];
    let owner;
    let name;
    try {
      owner = decodeURIComponent(match[1]);
      name = decodeURIComponent(match[2]);
    } catch (_) { return []; }
    const repo = findRepository(`${owner}/${name}`) || state.selectedRepo;
    if (!repo || repo.isPrivate) return [];
    // This origin reads the repository from its own node (ForkMesh Next's
    // core nodes hold every public repository locally), so a mirror origin
    // is only an extra connection: stay same-origin for reads.
    if (!mutation && (state.localRepoReads || globalThis.__forkmeshEarly?.local)) return [];
    // Routing-only fields belong to the canonical Worker. Direct gateways
    // accept only the operation's own Git query and ignore account/view hints.
    ["fmv", "viewer", "ts", "sig", "_"].forEach((key) =>
      request.searchParams.delete(key));
    return directMirrorOriginsForRepo(repo)
      // A page already opened on a mirror should stay on that independent
      // node first. The App origin is never a mirror candidate, so its visible
      // URL still fans directly to the freshest HTTPS node.
      .sort((left, right) =>
        Number(right === location.origin) - Number(left === location.origin))
      .map((origin) => `${origin}${request.pathname}${request.search}`);
  }

  function repoDataVersion(repo) {
    return String(
      repo?.updatedAt || repo?.lastSync || repo?.commit || repo?.stateHash || "",
    ).trim();
  }

  const REPO_ADDRESSES_STORE = "forkmesh.repoAddresses";
  const REPO_CORE_HOSTS = ["app.forkmesh.com", "forkmesh.com", "world.forkmesh.com"];
  const REPO_SHORT_NAME_RE = /^[A-Za-z0-9_-][A-Za-z0-9._-]{0,63}$/;
  const REPO_SHORT_FILE_RE = /\.(?:php\d?|txt|xml|json|ico|png|jpe?g|gif|svg|js|mjs|css|map|env|html?|aspx?|jsp|cgi|zip|gz|tgz|tar|sql|bak|ya?ml|ini|log|webmanifest|woff2?|ttf|pdf)$/i;

  function normalizeRepoAddresses(value) {
    const owner = String(value?.owner || "").trim().toLowerCase();
    if (!value || value.canonical !== true || !owner) return null;
    const names = (list) => new Set((Array.isArray(list) ? list : []).map((name) => String(name || "").toLowerCase()));
    const aliases = new Map(Object.entries(value.aliases && typeof value.aliases === "object" ? value.aliases : {})
      .map(([name, creator]) => [String(name).toLowerCase(), String(creator || "").toLowerCase()]));
    return { owner, keep: names(value.keep), reserved: names(value.reserved), aliases };
  }

  const REPO_ADDRESSES_SAVED_STORE = "forkmesh.repoAddressesSavedAt";
  const REPO_ADDRESSES_TTL_MS = 10 * 60 * 1000;

  function repoAddressesSignature(addresses) {
    if (!addresses) return "";
    return JSON.stringify([
      addresses.owner,
      [...addresses.keep].sort(),
      [...addresses.reserved].sort(),
      [...addresses.aliases.entries()].sort(),
    ]);
  }

  function repoAddresses() {
    if (state.repoAddresses !== undefined) return state.repoAddresses;
    let stored = null;
    try {
      stored = JSON.parse(localStorage.getItem(REPO_ADDRESSES_STORE) || "null");
    } catch (_) {}
    let addresses = normalizeRepoAddresses(stored);
    const pageOwner = String(document.querySelector('meta[name="forkmesh-repo-canonical"]')?.content || "").toLowerCase();
    if (pageOwner && addresses?.owner !== pageOwner) {
      addresses = normalizeRepoAddresses({ owner: pageOwner, canonical: true });
    }
    state.repoAddresses = addresses;
    return addresses;
  }

  function applyRepoAddresses(value) {
    const used = state.repoAddresses !== undefined;
    const before = used ? repoAddressesSignature(state.repoAddresses) : "";
    state.repoAddresses = normalizeRepoAddresses(value);
    try {
      localStorage.setItem(REPO_ADDRESSES_STORE, JSON.stringify(value || null));
      localStorage.setItem(REPO_ADDRESSES_SAVED_STORE, String(Date.now()));
    } catch (_) {}
    if (used && before !== repoAddressesSignature(state.repoAddresses)) {
      state.repoAddressesChanged = true;
      try {
        window.dispatchEvent(new CustomEvent("forkmesh:repo-addresses"));
      } catch (_) {}
    }
    return state.repoAddresses;
  }

  async function loadRepoAddresses() {
    if (REPO_CORE_HOSTS.includes(location.hostname.toLowerCase())) return null;
    try {
      const response = await fetch("/api/instance", { credentials: "omit", headers: { accept: "application/json" } });
      const data = response.ok ? await response.json() : null;
      if (data && typeof data === "object" && data.ok !== false) return applyRepoAddresses(data.repoAddresses || null);
    } catch (_) {}
    return repoAddresses();
  }

  function repoAddressesKnown() {
    try {
      if (localStorage.getItem(REPO_ADDRESSES_STORE) === null) return false;
      const savedAt = Number(localStorage.getItem(REPO_ADDRESSES_SAVED_STORE)) || 0;
      const age = Date.now() - savedAt;
      return age >= 0 && age < REPO_ADDRESSES_TTL_MS;
    } catch (_) {
      return false;
    }
  }

  function repoShortName(owner, name) {
    const addresses = repoAddresses();
    const value = String(name || "");
    const lowered = value.toLowerCase();
    const lowerOwner = String(owner || "").toLowerCase();
    if (!addresses || !value || !lowerOwner) return false;
    if (lowerOwner !== addresses.owner && addresses.aliases.get(lowered) !== lowerOwner) return false;
    if (lowered === addresses.owner || addresses.keep.has(lowered) || addresses.reserved.has(lowered)) return false;
    return REPO_SHORT_NAME_RE.test(value) && !lowered.endsWith(".git") && !REPO_SHORT_FILE_RE.test(value);
  }

  function repoPathUrl(repo, kind = "tree", path = "") {
    const owner = encodeURIComponent(repo.owner || "");
    const name = encodeURIComponent(repo.name || "");
    const suffix = path ? `/${kind}/${path.split("/").map(encodeURIComponent).join("/")}` : "";
    let publicOwner = "";
    try {
      publicOwner = repoPublicOwner(repo);
    } catch (_) {}
    if (repoShortName(repo.owner, repo.name) || (publicOwner && repoShortName(publicOwner, repo.name))) {
      if (!state.repoShortNames) state.repoShortNames = new Map();
      state.repoShortNames.set(String(repo.name).toLowerCase(), { name: String(repo.name), owner: repoAddresses().owner });
      return `/${name}${suffix}`;
    }
    return `/${owner}/${name}${suffix}`;
  }

  // A list that reads "forkmesh/forkmesh" must also link there, not to the
  // machine that happens to publish the bytes (adhoc #132). Organization
  // aliases are real addresses: the Worker rewrites /<org>/<repo> and every
  // /api/repo/<org>/<repo>/... path onto the serving node before routing, and
  // a direct visit resolves the alias again on the repo page. A clone URL a
  // node publishes is likewise a real address. Which mirror actually answers
  // is decided behind that address, so no link on the site should ever name a
  // mirror. User identities have no such rewrite, so a repo whose logical
  // owner is only a user keeps the physical /<node>/<repo> route.
  function repoLinkUrl(repo, kind = "tree", path = "") {
    const owner = repoPublicOwner(repo);
    return repoPathUrl(owner ? { ...repo, owner } : repo, kind, path);
  }

  function groupLinkUrl(group, kind = "tree", path = "") {
    const origin = sourceOfTruth(group);
    const organization = groupOrganizationAlias(group);
    return organization
      ? repoPathUrl({ ...origin, owner: organization }, kind, path)
      : repoLinkUrl(origin, kind, path);
  }

  // Feature-tab route segments (mirrors 404.html's `featureTabs` list) - tells
  // a tab route (e.g. /owner/repo/issues) apart from a tree/blob code deep link.
  const REPO_TAB_ROUTES = ["branches", "commits", "insights", "sizemap", "releases", "issues", "projects", "pulls", "discussions", "mirrors", "actions", "security"];

  // Owner/admin Agents and owner-only Settings are only recognized for an
  // account that can actually see them. A non-owner deep link falls through
  // to the harmless tree/blob path, so neither private control surface is
  // addressable merely by guessing its URL.
  function repoTabRoutesFor(repo) {
    const routes = REPO_TAB_ROUTES.slice();
    if (repo && sessionCanAssignAgent(repo)) routes.push("agents");
    if (repo && sessionAdministersRepo(repo)) routes.push("settings");
    return routes;
  }

  // Splits the current path into segments, stripping a leading /dashboard
  // route prefix (e.g. /dashboard/owner/repo/issues -> ["owner","repo","issues"])
  // so repo-route parsing sees the same clean owner/repo/tab shape regardless
  // of whether the browser landed here directly or via the 404.html bounce.
  function repoPublicHref(href) {
    const value = String(href || "");
    if (!value.startsWith("/") || value.startsWith("//")) return value;
    const [path, ...tail] = value.split(/(?=[?#])/);
    const parts = path.split("/").filter(Boolean);
    if (parts.length < 2) return value;
    const owner = safeDecodeURIComponent(parts[0]);
    const name = safeDecodeURIComponent(parts[1]);
    const rest = parts.slice(2);
    if (rest.length && ![...REPO_TAB_ROUTES, "agents", "settings", "tree", "blob", "compare"].includes(rest[0])) return value;
    if (!repoShortName(owner, name)) return value;
    return [repoPathUrl({ owner, name }), ...rest].join("/") + tail.join("");
  }

  function repoPublicKey(key) {
    const [owner, name, ...extra] = String(key || "").split("/");
    return owner && name && !extra.length && repoShortName(owner, name) ? name : String(key || "");
  }

  function repoHasShortAddress(repo) {
    const name = String(repo?.name || "");
    if (!name || !repoAddresses()) return false;
    const owners = [repo.owner];
    try {
      owners.push(repoPublicOwner(repo), repoDisplayOwner(repo));
    } catch (_) {}
    return owners.some((owner) => owner && repoShortName(owner, name));
  }

  function repoDisplayName(repo, longLabel) {
    if (typeof repo === "string") return repoPublicKey(repo);
    if (!repo) return "";
    if (repoHasShortAddress(repo)) return String(repo.name);
    return longLabel === undefined ? repoDisplayKey(repo) : String(longLabel);
  }

  function repoPublicText(text) {
    const value = String(text || "");
    if (!value || !repoAddresses()) return value;
    return value.replace(/(^|[^A-Za-z0-9._\/@-])([A-Za-z0-9_-][A-Za-z0-9._-]*)\/([A-Za-z0-9_-][A-Za-z0-9._-]*)(?![A-Za-z0-9_\/-])/g,
      (match, lead, owner, name) => {
        const trimmed = name.replace(/\.+$/, "");
        const dots = name.slice(trimmed.length);
        return repoShortName(owner, trimmed) ? `${lead}${trimmed}${dots}` : match;
      });
  }

  function repoReferenceLabel(repo, number) {
    const label = repoDisplayName(repo);
    return Number(number) ? `${label}#${Number(number)}` : label;
  }

  function groupDisplayName(group) {
    const origin = sourceOfTruth(group);
    const name = String(origin?.name || "");
    const organization = groupOrganizationAlias(group);
    if (repoHasShortAddress(origin) || (organization && repoShortName(organization, name))) return name;
    return `${groupDisplayOwner(group) || origin?.owner || ""}/${name}`;
  }

  function repoLabelParts(label) {
    const text = String(label || "");
    const slash = text.indexOf("/");
    return slash < 0 ? { owner: "", name: text } : { owner: text.slice(0, slash), name: text.slice(slash + 1) };
  }

  function repoShortHrefTarget(href) {
    const value = String(href || "");
    if (!value.startsWith("/") || value.startsWith("//")) return value;
    const shortened = repoPublicHref(value);
    if (shortened !== value) return shortened;
    const [path, ...tail] = value.split(/(?=[?#])/);
    const parts = path.split("/").filter(Boolean);
    if (!parts.length) return value;
    const known = state.repoShortNames?.get(safeDecodeURIComponent(parts[0]).toLowerCase());
    if (!known || repoShortName(known.owner, known.name)) return value;
    const rest = parts.slice(1);
    return `${repoPathUrl({ owner: known.owner, name: known.name })}${rest.length ? `/${rest.join("/")}` : ""}${tail.join("")}`;
  }

  function refreshRepoLinks(root) {
    const scope = root || document;
    let changed = 0;
    for (const link of scope.querySelectorAll ? scope.querySelectorAll("a[href^='/']") : []) {
      const href = link.getAttribute("href");
      const target = repoShortHrefTarget(href);
      if (target !== href) {
        link.setAttribute("href", target);
        changed += 1;
      }
    }
    return changed;
  }

  function replaceLongRepoLocation() {
    const current = `${location.pathname}${location.search}${location.hash}`;
    const target = repoShortHrefTarget(current);
    if (target === current) return false;
    try {
      window.history.replaceState(window.history.state, "", target);
      return true;
    } catch (_) {
      return false;
    }
  }

  function repoShortRoute(first = "") {
    const name = document.querySelector('meta[name="forkmesh-repo-short"]')?.content || "";
    const owner = document.querySelector('meta[name="forkmesh-repo-owner"]')?.content || "";
    if (name && owner && (!first || first.toLowerCase() === name.toLowerCase())) return { name, owner };
    const known = first ? state.repoShortNames?.get(first.toLowerCase()) : null;
    if (known && repoShortName(known.owner, known.name)) return known;
    return name && owner ? { name, owner } : null;
  }

  function repoRouteParts() {
    let parts = location.pathname.split("/").filter(Boolean);
    const prefixed = parts[0] === "dashboard";
    if (prefixed) parts = parts.slice(1);
    const first = parts.length ? safeDecodeURIComponent(parts[0]) : "";
    const short = prefixed ? null : repoShortRoute(first);
    if (short && parts.length && first.toLowerCase() === short.name.toLowerCase()) {
      const rest = parts.slice(1);
      const routed = !rest.length || [...REPO_TAB_ROUTES, "agents", "settings", "tree", "blob", "compare"].includes(rest[0]);
      return [encodeURIComponent(short.owner), encodeURIComponent(short.name), ...(routed ? rest : ["tree", ...rest])];
    }
    return parts;
  }

  function requestedRepoKey() {
    const params = new URLSearchParams(location.search);
    const value = params.get("repo");
    if (value && value.includes("/")) return decodeURIComponent(value);
    const parts = repoRouteParts();
    if (parts.length >= 2 && !["api", "assets", "dashboard", "docs", "blogs", "blog", "login", "signup", "network", "desktop", "about", "careers", "changelog", "privacy", "terms"].includes(parts[0])) {
      return `${decodeURIComponent(parts[0])}/${decodeURIComponent(parts[1])}`;
    }
    return "";
  }

  // Pull-detail sections are addressable in their own right
  // (/owner/repo/pulls/93/files) so a link to the Files changed review opens
  // there for whoever it is sent to. Conversation is the default and stays on
  // the bare record URL.
  const REPO_RECORD_SECTIONS = [
    "conversation", "commits", "checks", "files", "badge",
  ];

  function normalizeRepoRecordSection(value) {
    const section = String(value || "").trim().toLowerCase();
    return REPO_RECORD_SECTIONS.includes(section) ? section : "conversation";
  }

  // repoLinkUrl, not repoPathUrl: a record link addresses the repository the
  // page names (an organization alias), never the mirror publishing the bytes.
  function repoCommitUrl(repo, hash) {
    return `${repoLinkUrl(repo)}/commits/${encodeURIComponent(String(hash || ""))}`;
  }

  function repoRecordUrl(repo, kind, number, section) {
    const url = `${repoLinkUrl(repo)}/${kind}/${number}`;
    // Only pulls have sections; an issue/discussion URL never grows a suffix.
    const suffix = kind === "pulls" ? normalizeRepoRecordSection(section) : "conversation";
    return suffix === "conversation" ? url : `${url}/${suffix}`;
  }

  // A branch comparison is addressable too (/owner/repo/compare/main...agent/x):
  // the Agents tab links an agent's branch here so its work can be read in the
  // web diff viewer before any pull request exists, and the address survives a
  // refresh or a paste. Branch names keep their slashes - git forbids ".." in a
  // ref name, so the first "..." is always the separator - and each segment is
  // percent-encoded so a name cannot smuggle a query or fragment.
  function repoCompareUrl(repo, base, head) {
    const encodeRef = (ref) => String(ref || "")
      .split("/").map(encodeURIComponent).join("/");
    return `${repoLinkUrl(repo)}/compare/${encodeRef(base)}...${encodeRef(head)}`;
  }

  // The inverse of repoCompareUrl over the route's path segments: the segments
  // after "compare" are joined back with "/" and split on the first "...".
  function parseRepoCompareRoute(parts) {
    if (!Array.isArray(parts) || parts[2] !== "compare" || parts.length < 4) return null;
    const spec = parts.slice(3).map(safeDecodeURIComponent).join("/");
    const separator = spec.indexOf("...");
    if (separator <= 0) return null;
    const base = spec.slice(0, separator).trim();
    const head = spec.slice(separator + 3).trim();
    if (!base || !head || base.length > 250 || head.length > 250) return null;
    return { base, head };
  }

  // Pushes a new history entry for real in-app navigations (opening a repo,
  // browsing into a folder/file, leaving a repo for another section) so the
  // browser Back/Forward buttons step through them one at a time instead of
  // exiting the app entirely. No-ops when already on that URL (e.g. while
  // restoring state from a popstate event) to avoid piling up duplicate
  // entries that would otherwise make Back a no-op.
  function navigateHistory(url) {
    if (`${location.pathname}${location.search}` === url) return;
    window.history.pushState(null, "", url);
  }

  function cloneJson(value) {
    if (typeof structuredClone === "function") return structuredClone(value);
    return JSON.parse(JSON.stringify(value));
  }

  function fetchJsonCacheTtl(path) {
    if (path === "/api/repositories") return 15000;
    if (path === "/api/network/overview") return 20000;
    if (path === "/api/version") return 60000;
    return 0;
  }

  function cacheBustedPath(path) {
    const url = new URL(path, location.origin);
    url.searchParams.set("_", String(Date.now()));
    return `${url.pathname}${url.search}${url.hash}`;
  }

  // ForkMesh's own QR generator (no third-party library). It is staged onto
  // this origin from world/public/qr.js by tools/build_site_assets.py rather
  // than bundled here, so the pages that never draw a code - almost all of
  // them - never pay for it. One loader is shared by every caller, so the
  // script is fetched at most once no matter how many surfaces want a code.
  let qrGeneratorLoader = null;
  function loadQrGenerator() {
    if (window.ForkMeshQR) return Promise.resolve(true);
    if (qrGeneratorLoader) return qrGeneratorLoader;
    qrGeneratorLoader = new Promise((resolve) => {
      const script = document.createElement("script");
      script.src = "/qr.js";
      script.onload = () => resolve(Boolean(window.ForkMeshQR));
      script.onerror = () => resolve(false);
      document.head.append(script);
    });
    return qrGeneratorLoader;
  }

  // A wedged Worker isolate fails a request in a few milliseconds - a 500
  // from Pyodide's "NoGilError" or a "hung" cancel - before any route runs,
  // and the next request usually lands on a healthy isolate. fetchJson only
  // reads, so it retries those blips instead of surfacing them. 429 is left
  // alone: retrying a rate limit only deepens it.
  const FETCH_JSON_RETRY_DELAYS_MS = [400, 1500];

  function fetchJsonTransientStatus(status) {
    return status === 0 || status === 408 || status === 425 || status >= 500;
  }

  // One-shot: the catalog fetched early by the repository page, if any.
  async function takeEarlyPublicRead() {
    const early = globalThis.__forkmeshEarly;
    const pending = early?.catalog;
    if (!pending) return null;
    early.catalog = null;
    const data = await pending;
    return data && typeof data === "object" && data.ok !== false ? data : null;
  }

  async function fetchJson(path, options = {}) {
    const fresh = options.fresh === true;
    const cacheBust = options.cacheBust !== false;
    const baseTtl = fetchJsonCacheTtl(path);
    const ttl = fresh ? 0 : baseTtl;
    if (!state.fetchJsonInflight) state.fetchJsonInflight = {};
    if (!state.fetchJsonCache) state.fetchJsonCache = {};
    if (fresh) delete state.fetchJsonCache[path];
    const now = Date.now();
    const cached = ttl ? state.fetchJsonCache[path] : null;
    if (cached && cached.expiresAt > now) return cloneJson(cached.data);
    const requestPath = fresh && cacheBust ? cacheBustedPath(path) : path;
    const inflightKey = fresh ? `${requestPath}#fresh` : path;
    if (state.fetchJsonInflight[inflightKey]) {
      return cloneJson(await state.fetchJsonInflight[inflightKey]);
    }

    const pending = (async () => {
      // Only explicit fresh loads bypass HTTP caching; plain fetches send no
      // cache-buster and no cache-control override so the browser can reuse
      // responses within the server's max-age (request budget).
      const noStore = fresh;
      // Attach the account session as a bearer token when logged in. Endpoints
      // that expose per-account data (e.g. /api/notifications) require it;
      // public endpoints simply ignore it. Same-origin only.
      const token = state.session?.sessionToken || "";
      // The public catalog has a prebuilt privacy-validated snapshot. Sending
      // cookies or the local "cookie" token marker makes the App ingress
      // deliberately bypass that fast path and rebuild the live catalog. Keep
      // this one public read anonymous; account/private APIs remain credentialed.
      const anonymousPublicRead = path === "/api/repositories";
      const headers = noStore
        ? { accept: "application/json", "cache-control": "no-cache" }
        : { accept: "application/json" };
      if (!anonymousPublicRead && token && token !== "cookie") {
        headers.authorization = "Bearer " + token;
      }
      // The repository page starts the catalog read before this script runs
      // (partials/views/repo.html); take that answer over instead of asking
      // again.
      let data = anonymousPublicRead && !noStore ? await takeEarlyPublicRead() : null;
      if (!data) for (let attempt = 0; ; attempt += 1) {
        const last = attempt >= FETCH_JSON_RETRY_DELAYS_MS.length;
        let response;
        try {
          response = await fetch(requestPath, {
            cache: noStore ? "no-store" : "default",
            credentials: anonymousPublicRead ? "omit" : "same-origin",
            headers,
          });
        } catch (cause) {
          if (last) throw cause;
        }
        if (response) {
          data = await response.json().catch(() => ({}));
          if (response.ok && data.ok !== false) break;
          if (last || !fetchJsonTransientStatus(response.status)) {
            const error = new Error(data.error || `HTTP ${response.status}`);
            error.status = response.status;
            throw error;
          }
        }
        await new Promise((resolve) => setTimeout(resolve, FETCH_JSON_RETRY_DELAYS_MS[attempt]));
      }
      if (ttl || (fresh && baseTtl)) {
        state.fetchJsonCache[path] = {
          data: cloneJson(data),
          expiresAt: Date.now() + (ttl || baseTtl),
        };
      }
      return data;
    })();
    state.fetchJsonInflight[inflightKey] = pending;
    try {
      return cloneJson(await pending);
    } finally {
      if (state.fetchJsonInflight[inflightKey] === pending) delete state.fetchJsonInflight[inflightKey];
    }
  }

  // ---- Web issue authoring (signed inbox submissions) ------------------------
  // A logged-in web user files an issue the same way a mirror node does: a signed
  // "open" event POSTed to the repo's inbox for the maintainer to drain. The
  // browser holds no desktop key, so it keeps a persistent Ed25519 identity of
  // its own; the logged-in node name rides along as authorName for display.
  const ISSUE_TEXT_ENCODER = new TextEncoder();
  const WEB_ISSUE_KEY_STORAGE = "forkmesh.issueKey";
  // Attached images are embedded as base64 data: URLs inside the issue body
  // text itself (no separate upload channel), so they share the body's 64 KB
  // server-side cap (MAX_ISSUE_BYTES in the worker). Kept well under that so a
  // couple of small screenshots plus title/description text still fit.
  const ISSUE_IMAGE_MAX_COUNT = 4;
  const ISSUE_IMAGE_MAX_BYTES = 40 * 1024;
  const ISSUE_IMAGE_MAX_TOTAL_BYTES = 45 * 1024;
  const ISSUE_IMAGE_FIT_OPTIONS = { maxDimension: 1024 };
  // Raw files can be much bigger than the final embedded size - anything under
  // this is accepted into the crop/compress modal rather than rejected outright.
  const ISSUE_IMAGE_RAW_MAX_BYTES = 20 * 1024 * 1024;
  const PROFILE_AVATAR_MAX_BYTES = 256 * 1024;
  const PROFILE_AVATAR_RAW_MAX_BYTES = 20 * 1024 * 1024;
  // Screenshots pasted/attached onto a "start agent" prompt (adhoc #78). More
  // generous than issue images so a screenshot stays legible for the agent, but
  // still bounded to keep the queued-prompt row (and /api/sync payload) modest;
  // mirrors the worker's MAX_AGENT_PROMPT_IMAGE(S)* caps.
  const AGENT_IMAGE_MAX_COUNT = 3;
  const AGENT_IMAGE_MAX_BYTES = 1000 * 1024;
  const AGENT_IMAGE_MAX_TOTAL_BYTES = 1700 * 1024;

  function readAsDataUrl(fileOrBlob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result || ""));
      reader.onerror = () => reject(reader.error || new Error("read_failed"));
      reader.readAsDataURL(fileOrBlob);
    });
  }

  // Intermediary crop/compress step for images too large to embed directly.
  // The user drags a crop box, then the modal auto-retries JPEG re-encoding at
  // shrinking quality/scale ("multiple takes") until the result fits maxBytes,
  // or lets the user redraw a smaller crop and retry. Resolves to
  // { dataUrl, size } on confirm, or null if cancelled.

  const PULL_RULE_KINDS = [
    { kind: "tests", label: "Testing: tests accompany code changes" },
    { kind: "docs", label: "Documentation: docs accompany code changes" },
    { kind: "size", label: "Code quality: pull request size limit" },
    { kind: "commits", label: "Code quality: commit message format" },
    { kind: "secrets", label: "Security: no secrets in the change" },
    { kind: "paths", label: "Security: protected paths" },
    { kind: "model", label: `Required AI model (signed by a ${platformName()} runner)` },
  ];
  const PULL_RULE_MODELS = [
    "claude-opus-5-5", "claude-opus-5", "claude-sonnet-5", "claude-fable-5",
    "claude-haiku-4-5", "claude-sonnet-4-6", "claude-opus-4-8",
    "gpt-5.6-sol", "gpt-5.6-luna", "gpt-5.6-terra", "gpt-5.3-codex-spark",
  ];
  const PULL_RULE_INPUT = "h-8 w-full rounded-md border border-border bg-secondary px-2 text-xs text-foreground outline-none placeholder:text-muted-foreground focus:border-primary/70";
  const PULL_RULE_LABEL = "grid gap-1 text-[11px] font-medium text-foreground";

  function pullRuleList(value) {
    return Array.isArray(value) ? value.map((item) => String(item)).join(", ") : "";
  }

  function pullRuleSplit(value, separator = /,/) {
    return String(value || "").split(separator).map((item) => item.trim()).filter(Boolean);
  }

  function pullRuleRowHtml(rule, models, editable) {
    const kind = PULL_RULE_KINDS.some((item) => item.kind === rule.kind) ? rule.kind : "tests";
    const disabled = editable ? "" : " disabled";
    const field = (name, label, value, placeholder = "", type = "text") =>
      `<label class="${PULL_RULE_LABEL}">${escapeHtml(label)}<input data-pull-rule-field="${name}" type="${type}" value="${escapeHtml(value ?? "")}" placeholder="${escapeHtml(placeholder)}" class="${PULL_RULE_INPUT}"${type === "number" ? ' min="0"' : ""}${disabled} /></label>`;
    const group = (name, html) =>
      `<div data-pull-rule-kind-fields="${name}" class="${name === kind ? "" : "hidden "}grid gap-2 sm:grid-cols-2">${html}</div>`;
    const chosen = new Set(Array.isArray(rule.models) ? rule.models : []);
    const modelBoxes = [...new Set([...models, ...chosen])].map((model) =>
      `<label class="inline-flex items-center gap-1.5 rounded-md border border-border px-2 py-1 font-mono text-[11px] text-foreground"><input type="checkbox" data-pull-rule-model value="${escapeHtml(model)}"${chosen.has(model) ? " checked" : ""}${disabled} />${escapeHtml(model)}</label>`).join("");
    return `
      <fieldset data-pull-rule-row data-pull-rule-id="${escapeHtml(rule.id || "")}" class="grid gap-2 rounded-md border border-border p-3">
        <div class="grid gap-2 sm:grid-cols-[minmax(0,1fr)_auto_auto_auto]">
          <label class="${PULL_RULE_LABEL}">Rule
            <select data-pull-rule-kind class="${PULL_RULE_INPUT}"${disabled}>${PULL_RULE_KINDS.map((item) => `<option value="${item.kind}"${item.kind === kind ? " selected" : ""}>${escapeHtml(item.label)}</option>`).join("")}</select>
          </label>
          <label class="${PULL_RULE_LABEL}">When it fails
            <select data-pull-rule-field="enforcement" class="${PULL_RULE_INPUT}"${disabled}>
              <option value="block"${rule.enforcement !== "warn" ? " selected" : ""}>Block the merge</option>
              <option value="warn"${rule.enforcement === "warn" ? " selected" : ""}>Flag only</option>
            </select>
          </label>
          ${editable ? `<button type="button" data-pull-rule-remove class="fm-btn fm-btn-sm fm-btn-danger self-end"><i data-lucide="trash-2" aria-hidden="true"></i>Remove</button>` : ""}
        </div>
        <div class="grid gap-2 sm:grid-cols-2">
          ${field("title", "Title (optional)", rule.title, "Shown on the pull request")}
          ${field("branches", "Branches (empty = every branch)", pullRuleList(rule.branches), "main, release/*")}
        </div>
        ${group("tests", field("paths", "Code that needs tests", pullRuleList(rule.kind === "tests" ? rule.paths : []), "*.go, *.py, src/**") + field("testPaths", "Test files", pullRuleList(rule.testPaths), "**/tests/**, *_test.*"))}
        ${group("docs", field("paths", "Code that needs docs", pullRuleList(rule.kind === "docs" ? rule.paths : []), "src/**, api/**") + field("docsPaths", "Documentation files", pullRuleList(rule.docsPaths), "**/docs/**, *.md"))}
        ${group("size", field("maxFiles", "Most files changed", rule.maxFiles || "", "50", "number") + field("maxLines", "Most lines changed", rule.maxLines || "", "800", "number"))}
        ${group("commits", field("subjectPattern", "Subject must match (regular expression)", rule.subjectPattern, "^(feat|fix|docs|chore)(\\(.+\\))?: ") + field("maxSubjectLength", "Longest subject", rule.maxSubjectLength || "", "72", "number"))}
        ${group("secrets", `<label class="${PULL_RULE_LABEL} sm:col-span-2">Extra secret patterns, one regular expression per line (API keys, private keys and common tokens are always checked)<textarea data-pull-rule-field="patterns" rows="2" class="w-full rounded-md border border-border bg-secondary px-2 py-1 font-mono text-xs text-foreground outline-none"${disabled}>${escapeHtml((rule.patterns || []).join("\n"))}</textarea></label>` + field("paths", "Only scan these paths (empty = everything)", pullRuleList(rule.kind === "secrets" ? rule.paths : [])))}
        ${group("paths", field("paths", "Protected paths", pullRuleList(rule.kind === "paths" ? rule.paths : []), ".github/workflows/**, deploy/**"))}
        ${group("model", `<div class="grid gap-1 text-[11px] font-medium text-foreground sm:col-span-2">Allowed models<div class="flex flex-wrap gap-1.5">${modelBoxes}</div><span class="font-normal leading-4 text-muted-foreground">Every commit must carry a ForkMesh-Attestation that a ${escapeHtml(platformName())} runner signed under a router-issued grant naming one of these models. Commits written by hand, on a desktop or on a personal runner fail this rule; clean merges of the base branch pass.</span></div>`)}
        <label class="${PULL_RULE_LABEL}">How to fix it (optional, shown when the rule fails)
          <textarea data-pull-rule-field="suggestion" rows="2" class="w-full rounded-md border border-border bg-secondary px-2 py-1 text-xs text-foreground outline-none"${disabled}>${escapeHtml(rule.suggestion || "")}</textarea>
        </label>
      </fieldset>`;
  }

  function pullRulesEditorHtml(policy, options = {}) {
    const editable = options.editable !== false;
    const models = Array.isArray(options.models) && options.models.length ? options.models : PULL_RULE_MODELS;
    const rules = Array.isArray(policy?.rules) ? policy.rules : [];
    return `
      <form data-pull-rules-form class="grid gap-3">
        <div data-pull-rules-rows class="grid gap-3">${rules.map((rule) => pullRuleRowHtml(rule, models, editable)).join("") || `<div data-pull-rules-empty class="fm-blankslate"><i data-lucide="git-pull-request" aria-hidden="true"></i><p class="fm-blankslate-title">No rules yet</p><p class="fm-blankslate-desc">Add a rule to check each pull request.</p></div>`}</div>
        ${editable ? `
        <div class="flex flex-wrap items-center justify-between gap-2">
          <button type="button" data-pull-rule-add class="fm-btn fm-btn-sm"><i data-lucide="plus" aria-hidden="true"></i>Add rule</button>
          <div class="flex flex-wrap items-center gap-2">
            <span data-pull-rules-status class="text-xs text-muted-foreground"></span>
            <button type="submit" class="fm-btn fm-btn-sm fm-btn-cta">${escapeHtml(options.saveLabel || "Save rules")}</button>
          </div>
        </div>` : ""}
      </form>`;
  }

  function readPullRuleRow(row, kept, taken) {
    const kind = row.querySelector("[data-pull-rule-kind]")?.value || "tests";
    const fields = row.querySelector(`[data-pull-rule-kind-fields="${kind}"]`);
    const value = (scope, name) => String(scope?.querySelector(`[data-pull-rule-field="${name}"]`)?.value || "").trim();
    let id = kept;
    if (!id) {
      let suffix = 1;
      id = kind;
      while (taken.has(id)) id = `${kind}-${++suffix}`;
      taken.add(id);
    }
    const rule = { id, kind };
    const title = value(row, "title");
    if (title) rule.title = title;
    if (value(row, "enforcement") === "warn") rule.enforcement = "warn";
    const branches = pullRuleSplit(value(row, "branches"));
    if (branches.length) rule.branches = branches;
    const suggestion = value(row, "suggestion");
    if (suggestion) rule.suggestion = suggestion;
    ["paths", "testPaths", "docsPaths"].forEach((name) => {
      const items = pullRuleSplit(value(fields, name));
      if (items.length) rule[name] = items;
    });
    ["maxFiles", "maxLines", "maxSubjectLength"].forEach((name) => {
      const number = Number.parseInt(value(fields, name), 10);
      if (Number.isFinite(number) && number > 0) rule[name] = number;
    });
    const subject = value(fields, "subjectPattern");
    if (subject) rule.subjectPattern = subject;
    const patterns = pullRuleSplit(value(fields, "patterns"), /\n/);
    if (patterns.length) rule.patterns = patterns;
    if (kind === "model") {
      rule.models = [...row.querySelectorAll("[data-pull-rule-model]:checked")].map((input) => input.value);
    }
    return rule;
  }

  function readPullRulesEditor(root) {
    const taken = new Set();
    const rows = [...root.querySelectorAll("[data-pull-rule-row]")];
    const kept = rows.map((row) => {
      const id = String(row.dataset.pullRuleId || "").trim();
      if (!id || taken.has(id)) return "";
      taken.add(id);
      return id;
    });
    return {
      schema: "forkmesh-pull-rules-v1",
      rules: rows.map((row, index) => readPullRuleRow(row, kept[index], taken)),
    };
  }

  function pullRulesProblem(policy) {
    const branchPattern = /^[A-Za-z0-9*?][A-Za-z0-9._/*?-]{0,199}$/;
    const regexProblem = (value) => {
      if (/\(\?[=!<]|\(\?P=|\\[1-9]|\(\?>/.test(value)) return "uses lookaround or backreferences, which the rule checker does not support";
      try { new RegExp(value); } catch (_) { return "is not a valid regular expression"; }
      return "";
    };
    if ((policy.rules || []).length > 32) return "A rule set holds at most 32 rules.";
    for (const rule of policy.rules || []) {
      const name = rule.title || rule.id;
      if ((rule.title || "").length > 120) return `${name}: the title is longer than 120 characters.`;
      if ((rule.suggestion || "").length > 600) return `${name}: the fix text is longer than 600 characters.`;
      if ((rule.branches || []).some((branch) => !branchPattern.test(branch))) return `${name}: a branch pattern is invalid.`;
      if (rule.kind === "paths" && !(rule.paths || []).length) return `${name}: name at least one protected path.`;
      if (rule.kind === "size" && !rule.maxFiles && !rule.maxLines) return `${name}: set a file or line limit.`;
      if (rule.kind === "commits" && !rule.subjectPattern && !rule.maxSubjectLength) return `${name}: set a subject pattern or a length limit.`;
      if (rule.kind === "model" && !(rule.models || []).length) return `${name}: choose at least one allowed model.`;
      for (const pattern of [rule.subjectPattern, ...(rule.patterns || [])].filter(Boolean)) {
        const problem = regexProblem(pattern);
        if (problem) return `${name}: ${pattern} ${problem}.`;
      }
    }
    return "";
  }

  function bindPullRulesEditor(root, options = {}) {
    const form = root?.querySelector("[data-pull-rules-form]");
    if (!form) return;
    const models = Array.isArray(options.models) && options.models.length ? options.models : PULL_RULE_MODELS;
    const status = (text, tone = "") => {
      const node = form.querySelector("[data-pull-rules-status]");
      if (!node) return;
      node.textContent = text;
      node.className = `text-xs ${tone === "bad" ? "text-destructive" : tone === "good" ? "text-success" : "text-muted-foreground"}`;
    };
    form.addEventListener("change", (event) => {
      const select = event.target.closest("[data-pull-rule-kind]");
      if (!select) return;
      const row = select.closest("[data-pull-rule-row]");
      row?.querySelectorAll("[data-pull-rule-kind-fields]").forEach((group) => {
        group.classList.toggle("hidden", group.dataset.pullRuleKindFields !== select.value);
      });
    });
    form.addEventListener("click", (event) => {
      if (event.target.closest("[data-pull-rule-remove]")) {
        event.target.closest("[data-pull-rule-row]")?.remove();
        return;
      }
      if (event.target.closest("[data-pull-rule-add]")) {
        const rows = form.querySelector("[data-pull-rules-rows]");
        rows?.querySelector("[data-pull-rules-empty]")?.remove();
        rows?.insertAdjacentHTML("beforeend", pullRuleRowHtml({ kind: "tests" }, models, true));
        window.lucide?.createIcons();
      }
    });
    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      const policy = readPullRulesEditor(form);
      const problem = pullRulesProblem(policy);
      if (problem) {
        status(problem, "bad");
        return;
      }
      const button = form.querySelector('button[type="submit"]');
      if (button) button.disabled = true;
      status("Saving…");
      try {
        const message = await options.onSave?.(policy);
        status(message || "Saved.", "good");
      } catch (error) {
        status(error?.message || "Could not save the rules.", "bad");
      } finally {
        if (button) button.disabled = false;
      }
    });
  }
  function openImageResizeModal(file, maxBytes, options = {}) {
    return new Promise((resolve) => {
      const outputType = options.outputType || "image/jpeg";
      const aspectRatio = Number(options.aspectRatio) > 0 ? Number(options.aspectRatio) : 0;
      const confirmLabel = options.confirmLabel || "Add image";
      const objectUrl = URL.createObjectURL(file);
      let settled = false;
      const finish = (result) => {
        if (settled) return;
        settled = true;
        document.removeEventListener("keydown", onKeydown);
        URL.revokeObjectURL(objectUrl);
        overlay.remove();
        options.returnFocus?.focus();
        resolve(result);
      };
      const onKeydown = (event) => {
        if (event.key === "Escape") { event.preventDefault(); finish(null); }
      };

      const overlay = document.createElement("div");
      overlay.className = "fixed inset-0 z-50 flex items-start justify-center overflow-auto bg-background/70 p-4 pt-10";
      overlay.setAttribute("role", "dialog");
      overlay.setAttribute("aria-modal", "true");
      overlay.setAttribute("aria-label", options.dialogLabel || "Resize image");
      overlay.innerHTML = `
        <div class="fm-dialog w-full max-w-2xl">
          <div class="fm-dialog-header">
            <span class="fm-dialog-title truncate">${escapeHtml(options.title || `Resize "${file.name}"`)}</span>
          </div>
          <div class="fm-dialog-body grid gap-3">
            <p class="text-xs text-muted-foreground">${escapeHtml(options.description || "Drag on the image to crop it, then it's auto-compressed to fit. Attached images share the issue's size limit - redraw a smaller crop if it still doesn't fit.")}</p>
            <div data-resize-stage class="relative mx-auto inline-block max-h-[24rem] max-w-full touch-none select-none overflow-hidden rounded-md border border-border bg-secondary/30">
              <img data-resize-image src="${objectUrl}" class="block max-h-[24rem] max-w-full select-none" alt="" draggable="false" />
              <div data-resize-crop class="absolute hidden border-2 border-border bg-primary/10"></div>
            </div>
            <div class="flex flex-wrap items-center justify-between gap-2 text-xs">
              <span data-resize-status class="text-muted-foreground">Estimating size…</span>
              <button type="button" data-resize-reset class="fm-btn fm-btn-sm fm-btn-invisible">Reset crop</button>
            </div>
          </div>
          <div class="fm-dialog-footer">
            <button type="button" data-resize-cancel class="fm-btn fm-btn-sm">Cancel</button>
            <button type="button" data-resize-add disabled class="fm-btn fm-btn-sm fm-btn-cta"><i data-lucide="check"></i>${escapeHtml(confirmLabel)}</button>
          </div>
        </div>`;
      document.body.appendChild(overlay);
      window.lucide?.createIcons();
      document.addEventListener("keydown", onKeydown);

      const stage = overlay.querySelector("[data-resize-stage]");
      const modalImg = overlay.querySelector("[data-resize-image]");
      const cropDiv = overlay.querySelector("[data-resize-crop]");
      const status = overlay.querySelector("[data-resize-status]");
      const addButton = overlay.querySelector("[data-resize-add]");
      const resetButton = overlay.querySelector("[data-resize-reset]");
      const cancelButton = overlay.querySelector("[data-resize-cancel]");

      let cropRectCss = null;
      let dragStart = null;
      let pendingResult = null;
      let compressToken = 0;

      const clamp = (value, min, max) => Math.min(Math.max(value, min), max);

      const updateCropVisual = () => {
        if (!cropRectCss) {
          cropDiv.classList.add("hidden");
          return;
        }
        cropDiv.classList.remove("hidden");
        cropDiv.style.left = `${cropRectCss.left}px`;
        cropDiv.style.top = `${cropRectCss.top}px`;
        cropDiv.style.width = `${cropRectCss.width}px`;
        cropDiv.style.height = `${cropRectCss.height}px`;
      };

      const attemptCompress = async () => {
        if (!modalImg.naturalWidth) return;
        const attemptId = (compressToken += 1);
        pendingResult = null;
        addButton.disabled = true;
        status.className = "text-muted-foreground";
        status.textContent = "Compressing…";

        const scaleX = modalImg.naturalWidth / modalImg.clientWidth;
        const scaleY = modalImg.naturalHeight / modalImg.clientHeight;
        let region = { sx: 0, sy: 0, sw: modalImg.naturalWidth, sh: modalImg.naturalHeight };
        if (cropRectCss) {
          region = {
            sx: Math.round(cropRectCss.left * scaleX),
            sy: Math.round(cropRectCss.top * scaleY),
            sw: Math.max(1, Math.round(cropRectCss.width * scaleX)),
            sh: Math.max(1, Math.round(cropRectCss.height * scaleY)),
          };
        }

        const result = await encodeImageWithinBytes(modalImg, region, maxBytes, options,
          () => attemptId === compressToken);
        if (attemptId !== compressToken) return;
        if (result) {
          pendingResult = result;
          status.className = "text-muted-foreground";
          status.textContent = `Ready - ${formatSize(result.size)} (fits under ${formatSize(maxBytes)}).`;
          addButton.disabled = false;
          return;
        }
        status.className = "text-destructive";
        status.textContent = "Still too large after compressing - drag to crop a smaller area and it'll retry.";
      };

      stage.addEventListener("pointerdown", (event) => {
        const rect = stage.getBoundingClientRect();
        dragStart = {
          x: clamp(event.clientX - rect.left, 0, rect.width),
          y: clamp(event.clientY - rect.top, 0, rect.height),
        };
        stage.setPointerCapture(event.pointerId);
      });
      stage.addEventListener("pointermove", (event) => {
        if (!dragStart) return;
        const rect = stage.getBoundingClientRect();
        const x = clamp(event.clientX - rect.left, 0, rect.width);
        const y = clamp(event.clientY - rect.top, 0, rect.height);
        if (aspectRatio) {
          const directionX = x < dragStart.x ? -1 : 1;
          const directionY = y < dragStart.y ? -1 : 1;
          const availableWidth = directionX < 0 ? dragStart.x : rect.width - dragStart.x;
          const availableHeight = directionY < 0 ? dragStart.y : rect.height - dragStart.y;
          const width = Math.min(
            Math.max(Math.abs(x - dragStart.x), Math.abs(y - dragStart.y) * aspectRatio),
            availableWidth,
            availableHeight * aspectRatio,
          );
          const height = width / aspectRatio;
          cropRectCss = {
            left: directionX < 0 ? dragStart.x - width : dragStart.x,
            top: directionY < 0 ? dragStart.y - height : dragStart.y,
            width,
            height,
          };
        } else {
          cropRectCss = {
            left: Math.min(dragStart.x, x),
            top: Math.min(dragStart.y, y),
            width: Math.abs(x - dragStart.x),
            height: Math.abs(y - dragStart.y),
          };
        }
        updateCropVisual();
      });
      stage.addEventListener("pointerup", () => {
        if (!dragStart) return;
        dragStart = null;
        if (!cropRectCss || cropRectCss.width < 8 || cropRectCss.height < 8) cropRectCss = null;
        updateCropVisual();
        attemptCompress();
      });

      resetButton.addEventListener("click", () => {
        cropRectCss = null;
        updateCropVisual();
        attemptCompress();
      });
      cancelButton.addEventListener("click", () => finish(null));
      addButton.addEventListener("click", () => {
        if (pendingResult) finish(pendingResult);
      });

      let imageLoaded = false;
      const onImageLoad = () => {
        if (imageLoaded) return;
        imageLoaded = true;
        if (aspectRatio) {
          const width = Math.min(modalImg.clientWidth, modalImg.clientHeight * aspectRatio);
          const height = width / aspectRatio;
          cropRectCss = {
            left: (modalImg.clientWidth - width) / 2,
            top: (modalImg.clientHeight - height) / 2,
            width,
            height,
          };
          updateCropVisual();
        }
        attemptCompress();
      };
      modalImg.addEventListener("load", onImageLoad);
      modalImg.addEventListener("error", () => finish(null));
      if (modalImg.complete && modalImg.naturalWidth) onImageLoad();
      cancelButton.focus();
    });
  }

  function dataUrlByteLength(dataUrl) {
    const base64 = dataUrl.slice(dataUrl.indexOf(",") + 1);
    return Math.floor(base64.length * 3 / 4) - (base64.endsWith("==") ? 2 : base64.endsWith("=") ? 1 : 0);
  }

  async function encodeImageWithinBytes(source, region, maxBytes, options = {}, isCurrent = () => true) {
    const outputType = options.outputType || "image/jpeg";
    const aspectRatio = Number(options.aspectRatio) > 0 ? Number(options.aspectRatio) : 0;
    const { sx, sy, sw, sh } = region;
    const qualities = outputType === "image/png"
      ? [undefined]
      : [0.82, 0.65, 0.5, 0.35, 0.22, 0.12];
    const maxDimension = Number(options.maxDimension) || 0;
    let scale = maxDimension ? Math.min(1, maxDimension / Math.max(sw, sh)) : 1;
    const rounds = outputType === "image/png" ? 12 : 6;
    for (let round = 0; round < rounds; round += 1) {
      const outW = Math.max(24, Math.round(sw * scale));
      const outH = aspectRatio
        ? Math.max(24, Math.round(outW / aspectRatio))
        : Math.max(24, Math.round(sh * scale));
      const canvas = document.createElement("canvas");
      canvas.width = outW;
      canvas.height = outH;
      const ctx = canvas.getContext("2d");
      if (outputType !== "image/png") {
        ctx.fillStyle = "#fff";
        ctx.fillRect(0, 0, outW, outH);
      }
      ctx.drawImage(source, sx, sy, sw, sh, 0, 0, outW, outH);
      for (const quality of qualities) {
        await new Promise((resolve) => setTimeout(resolve, 0));
        if (!isCurrent()) return null;
        const dataUrl = canvas.toDataURL(outputType, quality);
        const size = dataUrlByteLength(dataUrl);
        if (dataUrl.startsWith(`data:${outputType};`) && size <= maxBytes) return { dataUrl, size };
      }
      scale *= outputType === "image/png" ? 0.75 : 0.65;
    }
    return null;
  }

  function loadImageElement(src) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.decoding = "async";
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error("image_decode_failed"));
      image.src = src;
    });
  }

  async function fitImageWithinBytes(src, maxBytes, options = {}) {
    try {
      const image = await loadImageElement(src);
      const region = { sx: 0, sy: 0, sw: image.naturalWidth, sh: image.naturalHeight };
      if (!region.sw || !region.sh) return null;
      return await encodeImageWithinBytes(image, region, maxBytes, options);
    } catch (_) {
      return null;
    }
  }

  const IMAGE_MARKUP_COLORS = ["#ef4444", "#f59e0b", "#22c55e", "#3b82f6", "#111827", "#ffffff"];
  const IMAGE_MARKUP_TOOLS = [
    ["pen", "pencil", "Draw"],
    ["box", "square", "Box"],
    ["arrow", "move-up-right", "Arrow"],
  ];
  const IMAGE_MARKUP_MAX_DIMENSION = 1600;

  function drawImageMarkupShape(ctx, shape, width, height) {
    const lineWidth = Math.max(2, Math.round(Math.max(width, height) / 250));
    const points = shape.points.map((point) => [point.x * width, point.y * height]);
    ctx.strokeStyle = shape.color;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (shape.tool === "pen") {
      points.forEach(([x, y], index) => (index ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
      if (points.length === 1) ctx.lineTo(points[0][0] + 0.1, points[0][1]);
      ctx.stroke();
      return;
    }
    if (points.length < 2) return;
    const [[x1, y1], [x2, y2]] = points;
    if (shape.tool === "box") {
      ctx.strokeRect(Math.min(x1, x2), Math.min(y1, y2), Math.abs(x2 - x1), Math.abs(y2 - y1));
      return;
    }
    const angle = Math.atan2(y2 - y1, x2 - x1);
    const head = lineWidth * 4;
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    for (const side of [-1, 1]) {
      ctx.moveTo(x2, y2);
      ctx.lineTo(x2 - head * Math.cos(angle + side * Math.PI / 6), y2 - head * Math.sin(angle + side * Math.PI / 6));
    }
    ctx.stroke();
  }

  function mountImageMarkupEditor(host, { src, name, shapes = [], maxBytes, encodeOptions = {}, onDone, onCancel }) {
    const history = shapes.map((shape) => ({ ...shape, points: shape.points.map((point) => ({ ...point })) }));
    let tool = "pen";
    let color = IMAGE_MARKUP_COLORS[0];
    let draft = null;
    let base = null;
    let busy = false;
    const toolButton = ([value, icon, label]) => `<button type="button" data-markup-tool="${value}" aria-pressed="${value === tool}" title="${label}" aria-label="${label}" class="inline-flex h-7 w-7 items-center justify-center rounded-md border border-transparent text-muted-foreground hover:bg-secondary hover:text-foreground aria-pressed:border-border aria-pressed:bg-secondary aria-pressed:text-foreground"><i data-lucide="${icon}" class="h-4 w-4"></i></button>`;
    const swatch = (value) => `<button type="button" data-markup-color="${value}" aria-pressed="${value === color}" title="Color ${value}" aria-label="Color ${value}" class="h-5 w-5 rounded-full border border-border aria-pressed:ring-2 aria-pressed:ring-foreground aria-pressed:ring-offset-1 aria-pressed:ring-offset-background" style="background:${value}"></button>`;
    host.innerHTML = `
      <div data-image-markup tabindex="-1" class="grid gap-2 rounded-md border border-border bg-background p-2 outline-none">
        <div class="flex flex-wrap items-center gap-1">
          ${IMAGE_MARKUP_TOOLS.map(toolButton).join("")}
          <span aria-hidden="true" class="mx-1 h-4 w-px bg-border"></span>
          <span class="flex items-center gap-1.5">${IMAGE_MARKUP_COLORS.map(swatch).join("")}</span>
          <span aria-hidden="true" class="mx-1 h-4 w-px bg-border"></span>
          <button type="button" data-markup-undo title="Undo (Ctrl+Z)" aria-label="Undo" class="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-secondary hover:text-foreground disabled:opacity-40"><i data-lucide="undo-2" class="h-4 w-4"></i></button>
          <button type="button" data-markup-clear class="inline-flex h-7 items-center rounded-md px-2 text-xs text-muted-foreground hover:bg-secondary hover:text-foreground disabled:opacity-40">Clear</button>
          <span class="ml-auto flex items-center gap-1.5">
            <button type="button" data-markup-cancel class="fm-btn fm-btn-sm">Cancel</button>
            <button type="button" data-markup-done class="fm-btn fm-btn-sm fm-btn-cta"><i data-lucide="check"></i>Done</button>
          </span>
        </div>
        <canvas data-markup-canvas aria-label="Mark up ${escapeHtml(name)}" class="block h-auto max-h-[70vh] w-auto max-w-full cursor-crosshair touch-none select-none justify-self-center rounded border border-border bg-secondary/30"></canvas>
        <span data-markup-status class="text-[11px] text-muted-foreground">Loading image…</span>
      </div>`;
    window.lucide?.createIcons();
    const root = host.querySelector("[data-image-markup]");
    const canvas = root.querySelector("[data-markup-canvas]");
    const status = root.querySelector("[data-markup-status]");
    const undoButton = root.querySelector("[data-markup-undo]");
    const clearButton = root.querySelector("[data-markup-clear]");
    const doneButton = root.querySelector("[data-markup-done]");
    const ctx = canvas.getContext("2d");
    const setStatus = (text, bad = false) => {
      status.className = `text-[11px] ${bad ? "text-destructive" : "text-muted-foreground"}`;
      status.textContent = text;
    };
    const redraw = () => {
      if (!base) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(base, 0, 0, canvas.width, canvas.height);
      for (const shape of draft ? [...history, draft] : history) drawImageMarkupShape(ctx, shape, canvas.width, canvas.height);
      undoButton.disabled = clearButton.disabled = !history.length;
    };
    const point = (event) => {
      const rect = canvas.getBoundingClientRect();
      return {
        x: Math.min(Math.max((event.clientX - rect.left) / (rect.width || 1), 0), 1),
        y: Math.min(Math.max((event.clientY - rect.top) / (rect.height || 1), 0), 1),
      };
    };
    const undo = () => {
      history.pop();
      redraw();
    };
    const finish = async () => {
      if (!base || busy) return;
      busy = true;
      doneButton.disabled = true;
      setStatus("Compressing…");
      const flat = document.createElement("canvas");
      flat.width = canvas.width;
      flat.height = canvas.height;
      const flatCtx = flat.getContext("2d");
      flatCtx.drawImage(base, 0, 0, flat.width, flat.height);
      for (const shape of history) drawImageMarkupShape(flatCtx, shape, flat.width, flat.height);
      const result = await encodeImageWithinBytes(flat, { sx: 0, sy: 0, sw: flat.width, sh: flat.height }, maxBytes, encodeOptions);
      if (!root.isConnected) return;
      if (!result) {
        busy = false;
        doneButton.disabled = false;
        setStatus(`Still too large to fit under ${formatSize(maxBytes)} - remove another image first.`, true);
        return;
      }
      onDone({ ...result, shapes: history });
    };

    root.addEventListener("click", (event) => {
      const toolTarget = event.target.closest("[data-markup-tool]");
      const colorTarget = event.target.closest("[data-markup-color]");
      if (toolTarget) {
        tool = toolTarget.dataset.markupTool;
        root.querySelectorAll("[data-markup-tool]").forEach((button) => button.setAttribute("aria-pressed", String(button === toolTarget)));
      } else if (colorTarget) {
        color = colorTarget.dataset.markupColor;
        root.querySelectorAll("[data-markup-color]").forEach((button) => button.setAttribute("aria-pressed", String(button === colorTarget)));
      } else if (event.target.closest("[data-markup-undo]")) {
        undo();
      } else if (event.target.closest("[data-markup-clear]")) {
        history.length = 0;
        redraw();
      } else if (event.target.closest("[data-markup-cancel]")) {
        onCancel();
      } else if (event.target.closest("[data-markup-done]")) {
        void finish();
      }
    });
    root.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        onCancel();
      } else if ((event.ctrlKey || event.metaKey) && !event.shiftKey && event.key.toLowerCase() === "z") {
        event.preventDefault();
        undo();
      } else if ((event.ctrlKey || event.metaKey) && event.key === "Enter") {
        event.preventDefault();
        event.stopPropagation();
        void finish();
      }
    });
    canvas.addEventListener("pointerdown", (event) => {
      if (!base || event.button > 0) return;
      event.preventDefault();
      root.focus({ preventScroll: true });
      canvas.setPointerCapture(event.pointerId);
      const start = point(event);
      draft = { tool, color, points: tool === "pen" ? [start] : [start, start] };
      redraw();
    });
    canvas.addEventListener("pointermove", (event) => {
      if (!draft) return;
      if (draft.tool === "pen") draft.points.push(point(event));
      else draft.points[1] = point(event);
      redraw();
    });
    const endStroke = () => {
      if (!draft) return;
      const [first, last] = [draft.points[0], draft.points[draft.points.length - 1]];
      if (draft.tool === "pen" || Math.hypot(last.x - first.x, last.y - first.y) > 0.01) history.push(draft);
      draft = null;
      redraw();
    };
    canvas.addEventListener("pointerup", endStroke);
    canvas.addEventListener("pointercancel", endStroke);

    loadImageElement(src).then((image) => {
      if (!root.isConnected) return;
      const scale = Math.min(1, IMAGE_MARKUP_MAX_DIMENSION / Math.max(image.naturalWidth, image.naturalHeight, 1));
      canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
      canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
      base = image;
      redraw();
      setStatus("Draw, box or point at what matters, then press Done. Esc cancels.");
      root.focus({ preventScroll: true });
    }).catch(() => setStatus("This image could not be opened for markup.", true));
  }

  function bytesToB64url(bytes) {
    const arr = new Uint8Array(bytes);
    let bin = "";
    for (let i = 0; i < arr.length; i += 1) bin += String.fromCharCode(arr[i]);
    return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  async function sha256HexLower(text) {
    const digest = await crypto.subtle.digest("SHA-256", ISSUE_TEXT_ENCODER.encode(text));
    return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, "0")).join("");
  }

  async function getWebIssueKey() {
    let stored = null;
    try { stored = JSON.parse(localStorage.getItem(WEB_ISSUE_KEY_STORAGE) || "null"); } catch (_) {}
    if (stored && stored.jwk && stored.pub) {
      try {
        const privateKey = await crypto.subtle.importKey("jwk", stored.jwk, { name: "Ed25519" }, false, ["sign"]);
        return { privateKey, pub: stored.pub };
      } catch (_) { /* fall through and mint a fresh key */ }
    }
    const pair = await crypto.subtle.generateKey({ name: "Ed25519" }, true, ["sign", "verify"]);
    const rawPub = await crypto.subtle.exportKey("raw", pair.publicKey);
    const jwk = await crypto.subtle.exportKey("jwk", pair.privateKey);
    const pub = bytesToB64url(rawPub);
    try { localStorage.setItem(WEB_ISSUE_KEY_STORAGE, JSON.stringify({ jwk, pub })); } catch (_) {}
    const privateKey = await crypto.subtle.importKey("jwk", jwk, { name: "Ed25519" }, false, ["sign"]);
    return { privateKey, pub };
  }

  // Mirrors IssueStore::contentForSigning + canonicalString and the desktop's
  // submission POST (verify_issue_event in the worker). New issues are signed
  // with number 0; the relay atomically reserves the durable number after it
  // verifies the event, and eligible mirrors keep that slot when they commit.
  //
  // Split out from submitWebIssue because the microjobs page needs the signed
  // event on its own: a paid report is reviewed for duplicates before anything
  // reaches the issue inbox, so it hands the event to /api/microjobs/claims
  // instead of posting it to the repo itself.
  function webEventSigningPrefix(kind, repo) {
    const owner = String(repo?.owner || "").trim().toLowerCase();
    const name = String(repo?.name || "").trim().toLowerCase();
    return `forkmesh-${kind}-v2\n${owner}/${name}\n`;
  }

  async function signWebIssueOpenEvent(title, body, repo) {
    const { privateKey, pub } = await getWebIssueKey();
    // IssueStore timestamps are epoch milliseconds. Keep browser-created
    // events on the same wire format as desktop-created events; seconds are
    // rendered by Qt as dates in 1970 and appear as decades-old activity.
    const ts = Date.now();
    const cleanBody = String(body || "").replace(/[\r\n]+$/, "");
    // open event content = title \0 body \0 attachments(joined by ","; empty here)
    const NUL = String.fromCharCode(0);
    const content = title + NUL + cleanBody + NUL;
    const contentHash = await sha256HexLower(content);
    const canonical = `${webEventSigningPrefix("issue-event", repo)}open\n0\n${pub}\n${ts}\n${contentHash}`;
    const sig = bytesToB64url(await crypto.subtle.sign({ name: "Ed25519" }, privateKey, ISSUE_TEXT_ENCODER.encode(canonical)));
    return {
      type: "open",
      id: "open-web-" + ts,
      title,
      body: cleanBody,
      attachments: [],
      author: pub,
      authorName: state.session?.nodeName || "",
      ts,
      sig,
    };
  }

  async function submitWebIssue(repo, title, body, assignAgent = false, agentModel = "", agentProvider = "", extraMeta = {}, onProgress = null) {
    onProgress?.({ phase: "signing" });
    let event;
    try {
      event = await signWebIssueOpenEvent(title, body, repo);
    } catch (cause) {
      // WebCrypto Ed25519 is missing from older browsers; without it nothing
      // can be signed, and "try again" would never help.
      const error = new Error("signing_unavailable");
      error.cause = cause;
      throw error;
    }
    const payload = {
      owner: repo.owner,
      repo: repo.name,
      number: 0,
      titleIfNew: title,
      event,
      meta: {
        labels: Array.isArray(extraMeta.labels) ? extraMeta.labels.map((x) => String(x)) : [],
        milestone: String(extraMeta.milestone || ""),
        project: String(extraMeta.project || ""),
        priority: Number.isFinite(extraMeta.priority) ? extraMeta.priority : 0,
        assignees: Array.isArray(extraMeta.assignees) ? extraMeta.assignees.map((x) => String(x)) : [],
        wantsAgent: Boolean(assignAgent),
        model: assignAgent ? String(agentModel || "") : "",
        provider: assignAgent ? String(agentProvider || "") : "",
      },
    };
    // When assignAgent is true, include the account session so the server can
    // verify the caller really is the repo owner or an admin (adhoc #225). The
    // session token is the proof; ownerAccount stays only as a display hint.
    if (assignAgent) {
      payload.ownerAccount = state.session?.nodeName || "";
      payload.sessionToken = state.session?.sessionToken || "";
    }
    const data = await fetchRepoMutation(
      repo, "issues", payload, { onProgress, retryTransient: true });
    onProgress?.({ phase: "accepted", number: Number(data?.number || 0) });
    return { ...data, event };
  }

  // A checklist is a portable sub-issue queue. Keep the relationship in the
  // signed descriptions so older clients and raw Git readers still see it:
  // children say "Parent issue: #N" and converted parent rows carry the stable
  // "(sub-issue #N)" suffix. The latter also makes retries idempotent.
  function issueSubtaskCandidates(body) {
    const lines = String(body || "").split("\n");
    const tasks = [];
    for (let line = 0; line < lines.length && tasks.length < 50; line++) {
      const match = /^(\s*(?:[-*+]\s+)?\[\s\]\s+)(.*?)(?:\r)?$/.exec(lines[line]);
      if (!match) continue;
      const label = match[2].trim();
      if (!label || /\s+\(sub-issue\s+#\d+\)\s*$/i.test(label)) continue;
      const title = label.slice(0, 240).trim();
      if (title) tasks.push({ line, prefix: match[1], label, title });
    }
    return tasks;
  }

  function linkIssueSubtasks(body, linkedTasks) {
    const lines = String(body || "").split("\n");
    (linkedTasks || []).forEach((task) => {
      if (Number.isInteger(task.line) && task.line >= 0 && task.line < lines.length) {
        lines[task.line] = `${task.prefix}${task.label} (sub-issue #${task.number})`;
      }
    });
    return lines.join("\n").replace(/[\r\n]+$/, "");
  }

  // Row actions address the source Markdown by line number. Keep these body
  // transforms independent of the DOM so a checkbox click or drag operation
  // becomes one normal signed description edit and remains portable to Git,
  // desktop, and older clients.
  function issueSubtaskCandidateAtLine(body, line) {
    const lines = String(body || "").split("\n");
    if (!Number.isInteger(line) || line < 0 || line >= lines.length) return null;
    const match = /^(\s*(?:[-*+]\s+)?\[([ xX])\]\s+)(.*?)(?:\r)?$/.exec(lines[line]);
    if (!match) return null;
    const label = match[3].trim();
    if (!label || /\s+\(sub-issue\s+#\d+\)\s*$/i.test(label)) return null;
    const title = label.slice(0, 240).trim();
    return title
      ? { line, prefix: match[1], label, title, checked: match[2].toLowerCase() === "x" }
      : null;
  }

  function setIssueTaskChecked(body, line, checked) {
    const source = String(body || "");
    const lines = source.split("\n");
    if (!Number.isInteger(line) || line < 0 || line >= lines.length) return null;
    const match = /^(\s*(?:[-*+]\s+)?\[)([ xX])(\]\s+.*?)(\r?)$/.exec(lines[line]);
    if (!match) return null;
    lines[line] = `${match[1]}${checked ? "x" : " "}${match[3]}${match[4]}`;
    return lines.join("\n");
  }

  function issueTaskIndent(value) {
    return String(value || "").replace(/\t/g, "  ").length;
  }

  // A task can own wrapped prose and nested bullets. Dragging its visible row
  // moves that whole block, stopping at the next sibling or outer block.
  function issueTaskBlockEnd(lines, start) {
    const first = /^(\s*)(?:[-*+]\s+)?\[[ xX]\]\s+/.exec(lines[start] || "");
    if (!first) return start + 1;
    const baseIndent = issueTaskIndent(first[1]);
    let end = start + 1;
    while (end < lines.length) {
      const line = lines[end];
      if (!line.trim()) {
        let next = end + 1;
        while (next < lines.length && !lines[next].trim()) next += 1;
        if (next >= lines.length) break;
        const leading = /^(\s*)/.exec(lines[next])?.[1] || "";
        if (issueTaskIndent(leading) > baseIndent) {
          end = next;
          continue;
        }
        break;
      }
      const leading = /^(\s*)/.exec(line)?.[1] || "";
      const indent = issueTaskIndent(leading);
      if (/^\s*(?:[-*+]|\d+[.)])\s+/.test(line) && indent <= baseIndent) break;
      if (indent <= baseIndent
          && /^\s*(?:#{1,6}\s|```|~~~|>|(?:-{3,}|\*{3,}|_{3,})\s*$|<)/.test(line)) break;
      end += 1;
    }
    return end;
  }

  function reorderIssueTaskBody(body, fromLine, toLine, placeAfter) {
    const source = String(body || "");
    const lines = source.split("\n");
    const from = Number(fromLine);
    const to = Number(toLine);
    if (!Number.isInteger(from) || !Number.isInteger(to)
        || from < 0 || to < 0 || from >= lines.length || to >= lines.length
        || from === to) return source;
    const taskPattern = /^(\s*)(?:[-*+]\s+)?\[[ xX]\]\s+/;
    const sourceTask = taskPattern.exec(lines[from]);
    const targetTask = taskPattern.exec(lines[to]);
    // Cross-level moves are ambiguous Markdown (and could silently re-parent a
    // nested list), so the UI and this defensive check keep peers together.
    if (!sourceTask || !targetTask
        || issueTaskIndent(sourceTask[1]) !== issueTaskIndent(targetTask[1])) return source;
    const sourceEnd = issueTaskBlockEnd(lines, from);
    const targetEnd = issueTaskBlockEnd(lines, to);
    const moved = lines.splice(from, sourceEnd - from);
    const removedBeforeTarget = from < to ? moved.length : 0;
    const adjustedTargetStart = to - removedBeforeTarget;
    const adjustedTargetEnd = targetEnd - removedBeforeTarget;
    const insertAt = placeAfter ? adjustedTargetEnd : adjustedTargetStart;
    lines.splice(insertAt, 0, ...moved);
    return lines.join("\n");
  }

  // The compact World chat composer is a second presentation of the canonical
  // dashboard actions. Expose the signed issue operation narrowly so the chat
  // bundle can file through the same eligible-mirror delivery path without duplicating key,
  // signature, authorization, or payload logic.
  window.ForkMeshDashboardActions = Object.assign(
    window.ForkMeshDashboardActions || {},
    { submitWebIssue },
  );

  // Mirrors IssueStore::contentForSigning's "comment" case (body NUL
  // attachments) and the desktop's inbox POST (verify_issue_event in the
  // worker). Unlike a new issue's "open" event, a comment is signed against the
  // issue's real number - the maintainer's node appends it to that issue when it
  // drains the inbox (IssueStore::applyRemoteEvent).
  async function submitWebIssueComment(repo, number, body) {
    const { privateKey, pub } = await getWebIssueKey();
    const ts = Date.now();
    const cleanBody = String(body || "").replace(/[\r\n]+$/, "");
    // comment event content = body \0 attachments(joined by ","; empty here)
    const NUL = String.fromCharCode(0);
    const contentHash = await sha256HexLower(cleanBody + NUL);
    const canonical = `${webEventSigningPrefix("issue-event", repo)}comment\n${number}\n${pub}\n${ts}\n${contentHash}`;
    const sig = bytesToB64url(await crypto.subtle.sign({ name: "Ed25519" }, privateKey, ISSUE_TEXT_ENCODER.encode(canonical)));
    const event = {
      type: "comment",
      id: "comment-web-" + ts,
      body: cleanBody,
      attachments: [],
      author: pub,
      authorName: state.session?.nodeName || "",
      ts,
      sig,
    };
    const payload = { owner: repo.owner, repo: repo.name, number, event };
    const data = await fetchRepoMutation(repo, "issues", payload);
    return { ...data, event };
  }

  // Lifecycle controls name the state they move an issue TO, and they spell it
  // differently depending on where they were authored: the detail header emits
  // "closed"/"open" (it reads the rendered state badge), the comment form emits
  // "close"/"open". Both must land on the two canonical Qt status values, since
  // the mirror stores whatever string the signed event carries verbatim
  // (applyIssueProjection in server/intake.go) - a stray "close" would leave the
  // issue neither open nor closed. Returns "" for anything that isn't a
  // lifecycle action, which is how callers tell a plain comment apart.
  function webIssueStatusForAction(action) {
    const name = String(action || "").trim().toLowerCase();
    if (name === "close" || name === "closed") return "closed";
    if (name === "open" || name === "reopen" || name === "reopened") return "open";
    return "";
  }

  function webIssueEventContent(type, fields = {}) {
    const NUL = String.fromCharCode(0);
    if (type === "edit") {
      return String(fields.body || "") + NUL
        + (Array.isArray(fields.attachments) ? fields.attachments.join(",") : "");
    }
    if (type === "title") return String(fields.title || "");
    if (type === "status") return String(fields.status || "");
    if (type === "labels") {
      return (Array.isArray(fields.labels) ? fields.labels : []).join(",");
    }
    if (type === "milestone") return String(fields.milestone || "");
    if (type === "dates") {
      return `${Number(fields.startDate) || 0}${NUL}${Number(fields.endDate) || 0}`;
    }
    if (type === "priority") return String(Number(fields.priority) || 0);
    if (type === "progress") return String(Number(fields.progress) || 0);
    if (type === "assignees") {
      return (Array.isArray(fields.assignees) ? fields.assignees : []).join(",");
    }
    if (type === "claim") {
      return String(fields.assignee || "") + NUL + String(fields.claimState || "");
    }
    if (type === "delete") return String(fields.target || "");
    if (type === "vote") return "";
    throw new Error("unsupported_issue_action");
  }

  function webIssueEventId(type, ts) {
    const suffix = new Uint32Array(1);
    crypto.getRandomValues(suffix);
    return `${type}-web-${ts}-${suffix[0].toString(36)}`;
  }

  // Owner-side issue actions use the same append-only event model as Qt. The
  // event is signed by this browser key, while the account session separately
  // proves repository authority to the Worker before it enters the mirror
  // inbox. Votes remain available to any signed-in contributor.
  async function submitWebIssueEvent(repo, number, type, fields = {}) {
    const issueNumber = Number(number);
    if (!Number.isInteger(issueNumber) || issueNumber <= 0) {
      throw new Error("invalid_issue_number");
    }
    const { privateKey, pub } = await getWebIssueKey();
    const ts = Date.now();
    const event = {
      type,
      id: webIssueEventId(type, ts),
      author: pub,
      authorName: state.session?.nodeName || "",
      ts,
    };
    const fieldNames = {
      edit: ["target", "body", "attachments"],
      title: ["title"],
      status: ["status"],
      labels: ["labels"],
      milestone: ["milestone"],
      dates: ["startDate", "endDate"],
      priority: ["priority"],
      progress: ["progress"],
      assignees: ["assignees"],
      claim: ["assignee", "claimState"],
      delete: ["target"],
      vote: [],
    }[type];
    if (!fieldNames) throw new Error("unsupported_issue_action");
    fieldNames.forEach((name) => {
      event[name] = fields[name];
    });
    if (type === "status") {
      // Signed and then replayed verbatim onto the issue JSON, so a status this
      // side does not recognize is refused here rather than committed.
      event.status = webIssueStatusForAction(event.status);
      if (!event.status) throw new Error("unsupported_issue_action");
    }
    if (type === "edit") {
      event.body = String(event.body || "").replace(/[\r\n]+$/, "");
      event.attachments = Array.isArray(event.attachments)
        ? event.attachments.map((value) => String(value))
        : [];
    }
    if (type === "labels" || type === "assignees") {
      event[type] = (Array.isArray(event[type]) ? event[type] : [])
        .map((value) => String(value).trim())
        .filter(Boolean)
        .slice(0, 20);
    }
    const contentHash = await sha256HexLower(
      webIssueEventContent(type, event),
    );
    const canonical = `${webEventSigningPrefix("issue-event", repo)}${type}\n${issueNumber}\n${pub}\n${ts}\n${contentHash}`;
    event.sig = bytesToB64url(await crypto.subtle.sign(
      { name: "Ed25519" },
      privateKey,
      ISSUE_TEXT_ENCODER.encode(canonical),
    ));
    const payload = {
      owner: repo.owner,
      repo: repo.name,
      number: issueNumber,
      event,
      ownerAccount: state.session?.nodeName || "",
      sessionToken: state.session?.sessionToken || "",
    };
    const data = await fetchRepoMutation(repo, "issues", payload);
    // Kept past this page so the next mirror read, which still predates the
    // owner's drain, cannot undo the change on screen (issue #715).
    if (type === "status") rememberPendingIssueStatus(repo, issueNumber, event);
    return { ...data, event };
  }

  async function setWebIssueSubscription(repo, number, subscribed) {
    const response = await fetch(`${repoApiBase(repo)}/subscribe`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json",
      },
      body: JSON.stringify({
        node: state.session?.nodeName || "",
        sessionToken: state.session?.sessionToken || "",
        source: "issue",
        number: Number(number),
        subscribed: subscribed === true,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      throw new Error(data.error || `HTTP ${response.status}`);
    }
    return data;
  }

  async function loadWebIssueSubscription(repo, number) {
    if (!state.session?.nodeName || !state.session?.sessionToken) return false;
    const response = await fetch(`${repoApiBase(repo)}/subscribe`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json",
      },
      body: JSON.stringify({
        action: "status",
        node: state.session.nodeName,
        sessionToken: state.session.sessionToken,
        source: "issue",
        number: Number(number),
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) return false;
    return data.subscribed === true;
  }

  // Mirrors DiscussionStore::contentForSigning's "comment" case (just the
  // reply body) and the desktop's discussion inbox POST (verify_discussion_event
  // in the worker). Replies are signed against the discussion's real number -
  // unlike a new discussion's "open" event, they don't use the placeholder 0.
  async function submitWebDiscussionComment(repo, number, body) {
    const { privateKey, pub } = await getWebIssueKey();
    const ts = Math.floor(Date.now() / 1000);
    const cleanBody = String(body || "").replace(/[\r\n]+$/, "");
    const contentHash = await sha256HexLower(cleanBody);
    const canonical = `${webEventSigningPrefix("discussion-event", repo)}comment\n${number}\n${pub}\n${ts}\n${contentHash}`;
    const sig = bytesToB64url(await crypto.subtle.sign({ name: "Ed25519" }, privateKey, ISSUE_TEXT_ENCODER.encode(canonical)));
    const event = {
      type: "comment",
      id: "comment-web-" + ts,
      body: cleanBody,
      author: pub,
      authorName: state.session?.nodeName || "",
      ts,
      sig,
    };
    const payload = { owner: repo.owner, repo: repo.name, number, event };
    const data = await fetchRepoMutation(repo, "discussions", payload);
    return data;
  }

  async function submitWebDiscussionAnswer(repo, number, target) {
    const { privateKey, pub } = await getWebIssueKey();
    const ts = Math.floor(Date.now() / 1000);
    const cleanTarget = String(target || "");
    const contentHash = await sha256HexLower(cleanTarget);
    const canonical = `${webEventSigningPrefix("discussion-event", repo)}answer\n${number}\n${pub}\n${ts}\n${contentHash}`;
    const sig = bytesToB64url(await crypto.subtle.sign({ name: "Ed25519" }, privateKey, ISSUE_TEXT_ENCODER.encode(canonical)));
    const event = {
      type: "answer",
      id: "answer-web-" + ts,
      target: cleanTarget,
      author: pub,
      authorName: state.session?.nodeName || "",
      ts,
      sig,
    };
    const payload = {
      owner: repo.owner,
      repo: repo.name,
      number,
      event,
      sessionToken: state.session?.sessionToken || "",
    };
    return fetchRepoMutation(repo, "discussions", payload);
  }

  function webIssueKeyPublic() {
    try {
      return String(JSON.parse(localStorage.getItem(WEB_ISSUE_KEY_STORAGE) || "null")?.pub || "");
    } catch (_) {
      return "";
    }
  }

  // Mirrors PullStore::contentForSigning's per-type field order (comment,
  // review, line-comment, thread-comment, thread-reply, thread-state,
  // suggestion-state) and the desktop's pull inbox POST
  // (verify_pull_comment_event/pull_comment_content in the worker). Covers
  // every conversation-shaped pull event; opening a brand new pull request is
  // a distinct signed shape (submitWebPullOpen, below).
  async function submitWebPullEvent(repo, number, type, fields = {}) {
    const { privateKey, pub } = await getWebIssueKey();
    const ts = Math.floor(Date.now() / 1000);
    const randomId = typeof crypto.randomUUID === "function"
      ? crypto.randomUUID()
      : bytesToB64url(crypto.getRandomValues(new Uint8Array(12)));
    const eventId = `${type}-web-${ts}-${randomId}`;
    // Native clients use the opening event id as the review-thread id. Do the
    // same in the browser so an inline comment can receive replies/resolution
    // events later without changing the signed wire format.
    if (type === "thread-comment" && !fields.threadId) fields.threadId = eventId;
    const NUL = String.fromCharCode(0);
    const cleanBody = String(fields.body || "").replace(/[\r\n]+$/, "");
    // A line-anchored event that names the patchset it was written against
    // and/or the commented text signs both (PullEvent::hasAnchor on the
    // desktop); without them the signed bytes are exactly the pre-anchor ones.
    const anchorFields = (fields.patchset || fields.anchorLines)
      ? [String(fields.patchset || ""), String(fields.anchorLines || "")]
      : [];
    let content;
    if (type === "comment") {
      content = cleanBody;
    } else if (type === "review") {
      content = [fields.state || "", cleanBody].join(NUL);
    } else if (type === "line-comment") {
      content = [fields.path || "", fields.side || "", String(fields.line || 0), cleanBody, ...anchorFields].join(NUL);
    } else if (type === "thread-comment") {
      content = [
        fields.threadId || "", fields.path || "", fields.side || "",
        String(fields.lineStart || 0), String(fields.lineEnd || 0),
        cleanBody, fields.suggestionPatch || "", ...anchorFields,
      ].join(NUL);
    } else if (type === "thread-reply") {
      content = [fields.threadId || "", fields.parentId || "", cleanBody].join(NUL);
    } else if (type === "thread-state") {
      content = [fields.threadId || "", fields.state || "", cleanBody].join(NUL);
    } else if (type === "suggestion-state") {
      content = [fields.threadId || "", fields.state || "", fields.appliedCommit || "", cleanBody].join(NUL);
    } else if (type === "status") {
      content = [fields.state || "", cleanBody].join(NUL);
    } else if (type === "delete") {
      content = cleanBody;
    } else {
      throw new Error("unsupported_pull_event_type");
    }
    const contentHash = await sha256HexLower(content);
    const canonical = `${webEventSigningPrefix("pull-comment", repo)}${type}\n${number}\n${pub}\n${ts}\n${contentHash}`;
    const sig = bytesToB64url(await crypto.subtle.sign({ name: "Ed25519" }, privateKey, ISSUE_TEXT_ENCODER.encode(canonical)));
    const event = {
      type,
      id: eventId,
      body: cleanBody,
      author: pub,
      authorName: state.session?.nodeName || "",
      ts,
      sig,
    };
    for (const key of ["state", "path", "side", "line", "threadId", "parentId", "lineStart", "lineEnd", "suggestionPatch", "appliedCommit", "patchset", "anchorLines"]) {
      if (fields[key] !== undefined && fields[key] !== "") event[key] = fields[key];
    }
    const payload = { owner: repo.owner, repo: repo.name, number, event };
    const data = await fetchRepoMutation(repo, "pulls", payload);
    return { ...data, event };
  }

  async function submitWebPullComment(repo, number, body) {
    return submitWebPullEvent(repo, number, "comment", { body });
  }

  async function submitWebPullReview(repo, number, reviewState, body) {
    return submitWebPullEvent(repo, number, "review", { state: reviewState, body });
  }

  async function submitWebPullClose(repo, number) {
    return submitWebPullEvent(repo, number, "status", { state: "closed" });
  }

  async function submitWebPullDelete(repo, number) {
    return submitWebPullEvent(repo, number, "delete", {});
  }

  function pullRequestParent(repo) {
    const parent = repoForkParent(repo);
    if (!parent) return null;
    const parentRecord = findRepository(parent.key);
    return parentRecord && repoReadOnlyMirror(parentRecord) ? null : parent;
  }

  function pullRequestTargetRepo(repo) {
    const parent = pullRequestParent(repo);
    if (!parent) return repo;
    return findRepository(parent.key) || {
      owner: parent.owner,
      name: parent.name,
      canonicalOwner: parent.owner,
      canonicalName: parent.name,
    };
  }

  // Mirrors PullStore::canonicalString for a new pull (verify_pull_event in
  // the Worker). Branch names alone are mutable and may not exist on the
  // owner's node, so resolve them through an attested mirror once and sign the
  // resulting portable binary patch + commit series. For a fork, comparison
  // happens on the fork's mirror while the signed, self-contained proposal is
  // delivered to the parent's durable inbox; the parent node can be offline.
  async function submitWebPullOpen(repo, title, body, base, head) {
    const targetRepo = pullRequestTargetRepo(repo);
    const parent = pullRequestParent(repo);
    const signedHead = parent
      ? `${repoDisplayOwner(repo) || repo.owner}:${head}`
      : head;
    const pull = await signWebPull(repo, targetRepo, title, body, base, head, signedHead);
    const payload = { owner: targetRepo.owner, repo: targetRepo.name, pull };
    try {
      const data = await fetchRepoMutation(targetRepo, "pulls", payload);
      return { ...data, pull, targetRepo };
    } catch (error) {
      if (targetRepo === repo || String(error?.code || error?.message || "") !== "read_only_mirror") throw error;
    }
    const ownPull = await signWebPull(repo, repo, title, body, base, head, head);
    const data = await fetchRepoMutation(repo, "pulls", { owner: repo.owner, repo: repo.name, pull: ownPull });
    return { ...data, pull: ownPull, targetRepo: repo };
  }

  const REMOTE_FORK_ORIGIN = /^https:\/\/[a-z0-9.-]+(?::\d{1,5})?$/;

  async function submitRemotePullOpen(repo, remote, title, body, base, head, compareBase = "") {
    const origin = String(remote?.origin || "").toLowerCase();
    const owner = String(remote?.owner || "");
    const name = String(remote?.name || "");
    if (!REMOTE_FORK_ORIGIN.test(origin) || !owner || !name) {
      throw new Error("invalid_remote_fork");
    }
    const signedHead = `${location.host}/${repoDisplayKey(repo)}:${head}`;
    const pull = await signWebPull(repo, { owner, name }, title, body, base, head, signedHead, compareBase);
    let response;
    try {
      response = await fetch(`${origin}/api/repo/${encodeURIComponent(owner)}/${encodeURIComponent(name)}/pulls`, {
        method: "POST",
        credentials: "omit",
        cache: "no-store",
        headers: { accept: "application/json", "content-type": "application/json" },
        body: JSON.stringify({ owner, repo: name, pull }),
      });
    } catch (cause) {
      const error = new Error("remote_unreachable");
      error.cause = cause;
      throw error;
    }
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      const error = new Error(String(data.error || `HTTP ${response.status}`));
      error.code = String(data.error || "");
      error.status = response.status;
      error.data = data;
      throw error;
    }
    return { ...data, pull, remote };
  }

  async function signWebPull(repo, signingRepo, title, body, base, head, signedHead, compareBase = "") {
    // The comparison is the first thing that can fail, and it fails BEFORE
    // anything is signed or sent - a mirror answers 404 for a branch name it
    // cannot resolve yet, which is the common case for a branch that was just
    // pushed. Tag it so the composer reports a comparison that never ran
    // instead of a pull request that could not be delivered; the raw 404
    // surfaced as "Could not send the pull request (not_found, HTTP 404)",
    // which reads as a rejected submission and invites a pointless resend.
    let comparison;
    try {
      comparison = await fetchRepoJson(repoLiveUrl(repo, "compare", {
        base: compareBase || base,
        head,
        ref: "",
      }));
    } catch (cause) {
      const error = new Error("comparison_unavailable");
      error.status = Number(cause?.status) || 0;
      error.code = String(cause?.code || "");
      error.cause = cause;
      throw error;
    }
    const patch = String(comparison.patch || "");
    const commits = String(comparison.commits || "");
    const baseOid = String(comparison.baseOid || "").toLowerCase();
    const headOid = String(comparison.headOid || "").toLowerCase();
    const validOid = (value) => /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(value);
    if (!validOid(baseOid) || !validOid(headOid)) {
      throw new Error("invalid_comparison");
    }
    if (!patch.trim()) {
      throw new Error("no_changes");
    }
    return signWebPullContent(signingRepo, title, body, base, signedHead, patch, commits);
  }

  async function submitWebFileProposal(repo, proposal, title, body = "") {
    const patch = String(proposal?.patch || "");
    const commits = String(proposal?.commits || "");
    const base = String(proposal?.base || "");
    const head = String(proposal?.head || "");
    if (!patch.trim() || !base || !head) throw new Error("no_changes");
    const pull = await signWebPullContent(repo, title, body, base, head, patch, commits);
    const data = await fetchRepoMutation(repo, "pulls", { owner: repo.owner, repo: repo.name, pull });
    return { ...data, pull, targetRepo: repo };
  }

  async function signWebPullContent(signingRepo, title, body, base, signedHead, patch, commits) {
    if (ISSUE_TEXT_ENCODER.encode(patch).byteLength
        + ISSUE_TEXT_ENCODER.encode(commits).byteLength > 4 * 1024 * 1024) {
      throw new Error("pull_too_large");
    }
    const { privateKey, pub } = await getWebIssueKey();
    const ts = Math.floor(Date.now() / 1000);
    const cleanBody = String(body || "").replace(/[\r\n]+$/, "");
    const NUL = String.fromCharCode(0);
    const content = [title, base, signedHead, patch, commits].join(NUL);
    const contentHash = await sha256HexLower(content);
    const canonical = `${webEventSigningPrefix("pull-event", signingRepo)}${pub}\n${ts}\n${contentHash}`;
    const sig = bytesToB64url(await crypto.subtle.sign({ name: "Ed25519" }, privateKey, ISSUE_TEXT_ENCODER.encode(canonical)));
    return {
      title,
      description: cleanBody,
      base,
      head: signedHead,
      patch,
      commits,
      author: pub,
      authorName: state.session?.nodeName || "",
      ts,
      sig,
    };
  }

  async function handleIssueCommentSubmit(repo, form) {
    if (!repo || !form) return;
    const number = Number(form.dataset.repoIssueCommentNumber || 0);
    const bodyInput = form.querySelector("[data-repo-issue-comment-body]");
    const submit = form.querySelector("[data-repo-issue-comment-submit]");
    const actionButtons = form.querySelectorAll(
      "[data-repo-issue-comment-action]",
    );
    // Resolved per call, not captured: a lifecycle submit re-renders the whole
    // issue detail on success, so the form (and its hint) this handler started
    // with is detached by the time there is an outcome to report.
    const setHint = (text, tone) => {
      const hint = document.querySelector("[data-repo-issue-comment-hint]");
      if (!hint) return;
      hint.className = `text-[11px] ${tone === "bad" ? "text-destructive" : "text-muted-foreground"}`;
      hint.textContent = text;
    };
    const body = String(bodyInput?.value || "").trim();
    if (!number) {
      setHint("This issue hasn't finished loading yet.", "bad");
      return;
    }
    // "Close issue" / "Reopen issue" with an empty box is the lifecycle
    // change alone, as on GitHub.
    const requestedAction = String(form._issueSubmitAction || "comment");
    if (!body && webIssueStatusForAction(requestedAction)) {
      form._issueSubmitAction = "comment";
      await handleWebIssueAction(requestedAction);
      return;
    }
    if (!body) {
      setHint("Write a comment before sending.", "bad");
      bodyInput?.focus();
      return;
    }
    actionButtons.forEach((button) => { button.disabled = true; });
    // The Comment button spins while the event is signed and delivered
    // (issue #687).
    const spinner = form.querySelector("[data-repo-issue-comment-spinner]");
    const stopSpinner = () => { if (spinner) spinner.hidden = true; };
    if (spinner) spinner.hidden = false;
    setHint("Signing and sending…");
    try {
      const result = await submitWebIssueComment(repo, number, body);
      // Show the comment straight away: it only reaches the mirror once the
      // maintainer's node drains the inbox, so the timeline can't reload it yet.
      // The composer sits in its own row of the conversation, so find the
      // timeline through the conversation rather than the form's parent.
      const timeline = form.closest("[data-repo-record-conversation]")
        ?.querySelector("[data-repo-issue-timeline]");
      if (timeline) {
        if (timeline.dataset.empty === "true") {
          timeline.innerHTML = "";
          timeline.dataset.empty = "false";
        }
        timeline.insertAdjacentHTML("beforeend", renderIssueTimelineComment({
          authorName: state.session?.nodeName || "you",
          ts: Date.now(), body,
        }));
      }
      stopSpinner();
      if (bodyInput) bodyInput.value = "";
      optimisticWebIssueEvent(result.event);
      const action = String(form._issueSubmitAction || "comment");
      form._issueSubmitAction = "comment";
      const nextStatus = webIssueStatusForAction(action);
      if (nextStatus) {
        // The comment is already accepted at this point, so a rejected status
        // event must not read as "the comment failed" - that invites a resend
        // and a duplicate. Report the half that failed and keep the rest.
        try {
          const statusResult = await submitWebIssueEvent(
            repo,
            number,
            "status",
            { status: nextStatus },
          );
          optimisticWebIssueEvent(statusResult.event);
          syncWebIssueListStatus(number, nextStatus);
        } catch (error) {
          actionButtons.forEach((button) => { button.disabled = false; });
          renderCurrentWebIssueDetail();
          setHint(
            `Comment sent, but the issue stayed ${nextStatus === "closed" ? "open" : "closed"}. ${webIssueActionError(error)}`,
            "bad",
          );
          return;
        }
      }
      actionButtons.forEach((button) => { button.disabled = false; });
      renderCurrentWebIssueDetail();
      setHint(
        nextStatus === "closed"
          ? "Comment sent and the issue is closed."
          : nextStatus === "open"
            ? "Comment sent and the issue is reopened."
            : "Comment accepted for direct delivery to an eligible mirror.",
        "good",
      );
    } catch (error) {
      stopSpinner();
      actionButtons.forEach((button) => { button.disabled = false; });
      const code = String(error?.message || "");
      setHint(
        code === "inbox_full" ? "Comment delivery is temporarily full. Try again later."
          : code === "author_quota" ? "You've reached the submission limit for this repository."
          : code === "issue_too_large" ? "The comment is too large - please shorten it."
          : code === "bad_signature" ? "Could not verify the comment's signature."
          : "Could not send the comment. Please try again.",
        "bad");
    }
  }

  function optimisticWebIssueEvent(event) {
    const detail = state.repoRecordDetail;
    if (!event || detail?.kind !== "issues") return;
    const parsed = detail.parsed || {};
    const values = parsed.values || (parsed.values = {});
    const events = Array.isArray(parsed.issueEvents)
      ? parsed.issueEvents
      : (parsed.issueEvents = []);
    if (!events.some((existing) => existing?.id === event.id)) events.push(event);
    if (event.type === "title") values.title = event.title;
    if (event.type === "status") values.status = event.status;
    if (event.type === "labels") values.labels = `[${event.labels.join(", ")}]`;
    if (event.type === "milestone") values.milestone = event.milestone;
    if (event.type === "priority") values.priority = Number(event.priority) || 0;
    if (event.type === "progress") values.progress = Number(event.progress) || 0;
    if (event.type === "assignees") {
      values.assignees = `[${event.assignees.join(", ")}]`;
    }
    if (event.type === "claim") {
      values.assignees = `[${webIssueClaimApplied(
        parseFrontMatterList(values.assignees), event,
      ).join(", ")}]`;
    }
    if (event.type === "dates") {
      values.startDate = Number(event.startDate) || 0;
      values.endDate = Number(event.endDate) || 0;
    }
    if (event.type === "vote") values.votes = (Number(values.votes) || 0) + 1;
    if (event.type === "edit" && event.target === parsed.issueOpenEventId) {
      parsed.body = event.body;
    }
    if (event.type === "delete" && event.target === "self") {
      parsed.issueDeleted = true;
    }
  }

  // The Issues list, its Open/Closed filter and the tab badge are all served
  // from the cached rows in state, and the mirror only learns about the signed
  // status event once the owner node drains its inbox. Move the row here so
  // navigating back from a just-closed issue does not show it as open again.
  function syncWebIssueListStatus(number, status) {
    const view = state.issuesView;
    const items = Array.isArray(view?.items) ? view.items : null;
    if (!items) return;
    const row = items.find((issue) => Number(issue.number) === Number(number));
    if (!row || row.status === status) return;
    const closing = status === "closed";
    row.status = status;
    row.state = status;
    if (Number.isFinite(view.openCount) && Number.isFinite(view.closedCount)) {
      view.openCount = Math.max(0, view.openCount + (closing ? -1 : 1));
      view.closedCount = Math.max(0, view.closedCount + (closing ? 1 : -1));
      setRepoTabCount("issues", view.openCount);
      setRepoCollectionCounts("issues", view.openCount, view.closedCount);
    }
    // A reopened issue is no longer part of the lazily paged closed history;
    // dropping its path keeps loadClosedIssues from re-reading a stale blob.
    if (!closing && view.closedPaths instanceof Map) {
      view.closedPaths.delete(Number(number));
    }
  }

  // Newly filed web issues are that many more open issues than the header
  // already counts. Move the tallies by that much rather than recounting the
  // loaded rows: the list may never have loaded (a recount then read 1), and
  // the recount left the Open strip's openCount behind the badge (issue #716).
  // unservedOpen keeps them counted until a list load finds them served.
  function countFiledWebIssues(added) {
    const view = state.issuesView;
    if (!view || !(added > 0)) return;
    view.unservedOpen = Math.max(0, Number(view.unservedOpen) || 0) + added;
    if (Number.isFinite(view.openCount)) {
      view.openCount += added;
      setRepoTabCount("issues", view.openCount);
      if (Number.isFinite(view.closedCount)) {
        setRepoCollectionCounts("issues", view.openCount, view.closedCount);
      }
      return;
    }
    const badge = $('[data-dashboard-repo-tab-count="issues"]');
    const shown = Number(String(badge?.textContent || "").replace(/\D/g, ""));
    setRepoTabCount("issues", (Number.isFinite(shown) ? shown : 0) + added);
  }

  function renderCurrentWebIssueDetail() {
    const detail = state.repoRecordDetail;
    if (detail?.kind !== "issues" || !detail.repo) return;
    const container = $("[data-repo-issues]");
    if (!container) return;
    container.innerHTML = renderRepoRecordDetail(
      detail.repo,
      "issues",
      detail.number,
      detail.parsed,
    );
    mountIssueStickyHeader(container);
    window.lucide?.createIcons();
  }

  function webIssueActionError(error, action = "") {
    const code = String(error?.message || "");
    // A claim never needs repository authority, so "not_authorized" there means
    // the account session behind it is gone, not that the viewer lacks a role.
    if (code === "not_authorized" && (action === "claim" || action === "release")) {
      return "Your sign-in has expired. Sign in again to change your assignment.";
    }
    return ({
      not_authorized: "Only the repository owner or an organization admin can do that.",
      bad_signature: "The signed issue action could not be verified.",
      inbox_full: "Issue delivery is temporarily full. Try again later.",
      author_quota: "Too many issue changes are waiting to sync. Try again after the owner node drains them.",
      issue_too_large: "That issue update is too large.",
      number_unavailable: "A durable sub-issue number could not be reserved. Try again.",
    })[code] || "The issue could not be updated. Please try again.";
  }

  // Fold one signed "claim" into an assignee list. A claim is a delta naming a
  // single account, not a replacement for the whole list — that is exactly what
  // makes it safe to let a public contributor sign one for themselves (issue
  // #570), because it cannot drop anybody else's name. Matching is
  // case-insensitive, like the relay's account check; the stored spelling is
  // whatever was signed.
  function webIssueClaimApplied(assignees, event) {
    const name = String(event?.assignee || "").trim();
    const current = (Array.isArray(assignees) ? assignees : []).map(String);
    if (!name) return current;
    const isName = (value) => value.trim().toLowerCase() === name.toLowerCase();
    if (event?.claimState === "released") return current.filter((v) => !isName(v));
    return current.some(isName) ? current : [...current, name];
  }

  // The assignee list a viewer should see, given the serving node's projection
  // plus the signed events it carries. Claims recorded AFTER the last full
  // "assignees" event are re-folded here so a self-assignment shows up even
  // when the mirror that served this issue has not learned to project claims
  // yet; re-folding is idempotent against a node that has, and stopping at the
  // last "assignees" event keeps a maintainer's later replacement authoritative.
  function webIssueAssigneesWithClaims(assignees, events) {
    const log = Array.isArray(events) ? events : [];
    let start = 0;
    log.forEach((event, index) => {
      if (event?.type === "assignees") start = index + 1;
    });
    return log.slice(start).reduce(
      (list, event) => (event?.type === "claim" ? webIssueClaimApplied(list, event) : list),
      (Array.isArray(assignees) ? assignees : []).map(String),
    );
  }

  function splitWebIssueList(value) {
    return [...new Set(String(value || "").split(",")
      .map((item) => item.trim())
      .filter(Boolean))].slice(0, 20);
  }

  async function handleWebIssueAction(action, target = "") {
    const detail = state.repoRecordDetail;
    const repo = detail?.repo;
    const number = Number(detail?.number || 0);
    if (!repo || detail?.kind !== "issues" || !number) return;
    if (!state.session?.nodeName) {
      location.href = "/login?next="
        + encodeURIComponent(`${location.pathname}${location.search}`);
      return;
    }
    let type = "";
    let fields = {};
    if (action === "subscribe" || action === "unsubscribe") {
      try {
        await setWebIssueSubscription(repo, number, action === "subscribe");
        detail.parsed.issueSubscribed = action === "subscribe";
        renderCurrentWebIssueDetail();
      } catch (error) {
        showErrorNotice(webIssueActionError(error));
      }
      return;
    }
    if (action === "vote") type = "vote";
    if (action === "claim" || action === "release") {
      type = "claim";
      fields = {
        assignee: String(state.session.nodeName || ""),
        claimState: action === "claim" ? "assigned" : "released",
      };
    }
    const nextStatus = webIssueStatusForAction(action);
    if (nextStatus) {
      type = "status";
      fields = { status: nextStatus };
    }
    if (action === "delete-issue") {
      const title = String(detail.parsed?.values?.title || `issue #${number}`);
      if (!await confirmAccountAction({
        title: `Delete issue #${number} “${title}”?`,
        body: "The repository's node removes it everywhere once the signed deletion syncs. Its Git history keeps the record.",
        confirmLabel: "Delete issue",
      })) return;
      type = "delete";
      fields = { target: "self" };
    }
    if (action === "delete-comment") {
      if (!await confirmAccountAction({
        title: "Delete this comment?",
        body: "Its Git history remains recoverable.",
        confirmLabel: "Delete comment",
      })) return;
      type = "delete";
      fields = { target };
    }
    if (action === "edit-comment") {
      const events = detail.parsed?.issueEvents || [];
      const original = events.find((event) => event?.id === target);
      if (!original) return;
      const latest = events.filter(
        (event) => event?.type === "edit" && event.target === target,
      ).at(-1);
      const nextBody = await openIssueCommentEditor(target, latest?.body ?? original.body ?? "");
      if (nextBody === null) return;
      type = "edit";
      fields = { target, body: nextBody, attachments: latest?.attachments || original.attachments || [] };
    }
    if (!type) return;
    try {
      const result = await submitWebIssueEvent(repo, number, type, fields);
      optimisticWebIssueEvent(result.event);
      if (type === "status") syncWebIssueListStatus(number, fields.status);
      if (action === "delete-issue") {
        state.issuesView.items = (state.issuesView.items || []).filter(
          (issue) => Number(issue.number) !== number,
        );
        state.repoRecordDetail = null;
        navigateHistory(`${repoLinkUrl(repo)}/issues`);
        renderRepoIssues();
        return;
      }
      renderCurrentWebIssueDetail();
    } catch (error) {
      showErrorNotice(webIssueActionError(error, action));
    }
  }

  function webIssueTaskError(error) {
    return ({
      org_member_required: "Only members of this site's organization can create tasks.",
      invalid_session: "Your sign-in has expired. Sign in again to move this issue.",
      office_organization_unavailable: "Organization tasks are unavailable right now. Try again later.",
      payload_too_large: "This issue is too large to move into a task.",
    })[String(error?.code || "")] || "The task could not be created, so the issue was kept.";
  }

  function webIssueTaskBody(repo, number, values, body) {
    const owner = repoPublicOwner(repo) || String(repo.owner || "");
    const name = String(repo.name || "");
    const segment = /^[A-Za-z0-9._-]{1,100}$/;
    const repository = segment.test(owner) && segment.test(name) ? `${owner}/${name}` : "";
    const source = `Moved from issue ${repository || name}#${number} by ${state.session?.nodeName || "a repository manager"}.`;
    const text = String(body || "").trim();
    const room = 4000 - source.length - 2;
    return {
      title: String(values.title || `Issue #${number}`).trim().slice(0, 160),
      details: text ? `${text.length > room ? `${text.slice(0, room - 1)}…` : text}\n\n${source}` : source,
      repository,
      department: "general",
      destination: "department",
      assigneeKind: "unassigned",
    };
  }

  async function moveWebIssueToTask(button = null) {
    const detail = state.repoRecordDetail;
    const repo = detail?.repo;
    const number = Number(detail?.number || 0);
    if (!repo || detail?.kind !== "issues" || !number) return;
    if (!state.session?.nodeName) {
      location.href = "/login?next="
        + encodeURIComponent(`${location.pathname}${location.search}`);
      return;
    }
    const values = detail.parsed?.values || {};
    const title = String(values.title || `issue #${number}`);
    if (!await confirmAccountAction({
      title: `Move issue #${number} “${title}” to a task?`,
      body: "An organization task is created from its title and description, then the issue is deleted. If the issue cannot be deleted, the new task is moved to trash so nothing is left twice.",
      confirmLabel: "Move to task",
    })) return;
    if (button) button.disabled = true;
    let task = null;
    try {
      const created = await orgApiRequest(
        "POST", "/api/tasks", webIssueTaskBody(repo, number, values, detail.parsed?.body));
      task = created.task;
    } catch (error) {
      if (button) button.disabled = false;
      showErrorNotice(webIssueTaskError(error));
      return;
    }
    try {
      const result = await submitWebIssueEvent(repo, number, "delete", { target: "self" });
      optimisticWebIssueEvent(result.event);
    } catch (error) {
      const undone = await orgApiRequest(
        "DELETE", `/api/tasks/${encodeURIComponent(task.id)}`,
        { reason: `Issue #${number} could not be deleted.` },
      ).then(() => true, () => false);
      if (button) button.disabled = false;
      showErrorNotice(`${webIssueActionError(error, "delete-issue")} ${undone
        ? "The new task was moved to trash, so the issue is unchanged."
        : "The new task could not be removed; delete it from Tasks."}`);
      return;
    }
    state.issuesView.items = (state.issuesView.items || []).filter(
      (issue) => Number(issue.number) !== number,
    );
    state.repoRecordDetail = null;
    location.assign(`/dashboard/tasks?task=${encodeURIComponent(task.id)}`);
  }

  async function handleWebIssueTitleSubmit(form) {
    const detail = state.repoRecordDetail;
    const title = String(
      form.querySelector("[data-repo-issue-title-input]")?.value || "",
    ).trim();
    if (!title) return;
    try {
      const result = await submitWebIssueEvent(
        detail.repo,
        detail.number,
        "title",
        { title },
      );
      optimisticWebIssueEvent(result.event);
      renderCurrentWebIssueDetail();
    } catch (error) {
      showErrorNotice(webIssueActionError(error));
    }
  }

  async function handleWebIssueDescriptionSubmit(form) {
    const detail = state.repoRecordDetail;
    const body = String(
      form.querySelector("[data-repo-issue-description-input]")?.value || "",
    );
    try {
      const result = await submitWebIssueEvent(
        detail.repo,
        detail.number,
        "edit",
        {
          target: detail.parsed.issueOpenEventId,
          body,
          attachments: detail.parsed.issueOpenAttachments || [],
        },
      );
      optimisticWebIssueEvent(result.event);
      renderCurrentWebIssueDetail();
    } catch (error) {
      showErrorNotice(webIssueActionError(error));
    }
  }

  let issueTaskMutationPending = false;
  let issueTaskDrag = null;

  function setIssueTaskControlsBusy(busy) {
    const taskList = document.querySelector("[data-repo-issue-task-list]");
    taskList?.setAttribute("aria-busy", busy ? "true" : "false");
    document.querySelectorAll(
      "[data-repo-issue-task-toggle], [data-repo-issue-task-drag], [data-repo-issue-create-subissues]",
    ).forEach((control) => {
      control.disabled = busy;
      if (control.matches("[data-repo-issue-task-drag]")) {
        control.draggable = !busy;
      }
    });
  }

  function setIssueTaskRowChecked(row, checked) {
    if (!row) return;
    row.classList.toggle("is-complete", checked);
    const toggle = row.querySelector("[data-repo-issue-task-toggle]");
    if (toggle) {
      toggle.checked = checked;
      const label = String(toggle.getAttribute("aria-label") || "")
        .replace(/^(?:Mark complete|Mark incomplete)/, checked ? "Mark incomplete" : "Mark complete");
      toggle.setAttribute("aria-label", label);
    }
  }

  // The checkbox is a little ForkMesh constellation: completing a task sends
  // ten colored nodes out from the box; reopening reels them back in. Motion is
  // decorative and omitted for people who request reduced motion.
  function playIssueTaskToggleMotion(toggle, checked) {
    const row = toggle?.closest("[data-repo-issue-task-row]");
    const control = toggle?.closest(".issue-task-control");
    if (!row || !control) return;
    row.classList.remove("is-checking", "is-unchecking");
    void row.offsetWidth;
    row.classList.add(checked ? "is-checking" : "is-unchecking");
    window.setTimeout(
      () => row.classList.remove("is-checking", "is-unchecking"),
      760,
    );
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
    control.querySelector(".issue-task-burst")?.remove();
    const burst = document.createElement("span");
    burst.className = `issue-task-burst ${checked ? "is-bursting" : "is-rewinding"}`;
    burst.setAttribute("aria-hidden", "true");
    for (let index = 0; index < 10; index += 1) {
      const particle = document.createElement("span");
      particle.style.setProperty("--task-angle", `${index * 36}deg`);
      particle.style.setProperty("--task-hue", String(138 + (index * 19)));
      particle.style.setProperty("--task-delay", `${index * 12}ms`);
      burst.appendChild(particle);
    }
    control.appendChild(burst);
    window.setTimeout(() => burst.remove(), 900);
  }

  async function submitWebIssueTaskBody(body) {
    const detail = state.repoRecordDetail;
    if (!detail?.repo || detail.kind !== "issues" || !detail.number) {
      throw new Error("invalid_issue_number");
    }
    return submitWebIssueEvent(
      detail.repo,
      detail.number,
      "edit",
      {
        target: detail.parsed.issueOpenEventId,
        body,
        attachments: detail.parsed.issueOpenAttachments || [],
      },
    );
  }

  async function handleWebIssueTaskToggle(toggle) {
    if (!toggle || issueTaskMutationPending) return;
    const detail = state.repoRecordDetail;
    const body = String(detail?.parsed?.body || "");
    const line = Number(toggle.dataset.repoIssueTaskToggle);
    const lines = body.split("\n");
    const current = /^(?:\s*(?:[-*+]\s+)?\[)([ xX])\]/.exec(lines[line] || "");
    const checked = Boolean(toggle.checked);
    if (!current) {
      renderCurrentWebIssueDetail();
      return;
    }
    const wasChecked = current[1].toLowerCase() === "x";
    const nextBody = setIssueTaskChecked(body, line, checked);
    if (nextBody === null || checked === wasChecked) return;

    issueTaskMutationPending = true;
    const row = toggle.closest("[data-repo-issue-task-row]");
    const status = row?.querySelector("[data-repo-issue-task-status]");
    setIssueTaskRowChecked(row, checked);
    playIssueTaskToggleMotion(toggle, checked);
    if (status) status.textContent = checked ? "Marking complete…" : "Reopening task…";
    setIssueTaskControlsBusy(true);
    const motionDone = new Promise((resolve) => window.setTimeout(resolve, 680));
    try {
      const result = await submitWebIssueTaskBody(nextBody);
      optimisticWebIssueEvent(result.event);
      if (status) status.textContent = checked ? "Task complete." : "Task reopened.";
      await motionDone;
      renderCurrentWebIssueDetail();
    } catch (error) {
      setIssueTaskRowChecked(row, wasChecked);
      playIssueTaskToggleMotion(toggle, wasChecked);
      if (status) status.textContent = "Could not save the task.";
      showErrorNotice(webIssueActionError(error));
    } finally {
      issueTaskMutationPending = false;
      setIssueTaskControlsBusy(false);
    }
  }

  async function handleWebIssueTaskReorder(sourceRow, targetRow, placeAfter) {
    if (!sourceRow || !targetRow || sourceRow === targetRow || issueTaskMutationPending) return;
    if (sourceRow.dataset.repoIssueTaskGroup !== targetRow.dataset.repoIssueTaskGroup) return;
    const detail = state.repoRecordDetail;
    const body = String(detail?.parsed?.body || "");
    const nextBody = reorderIssueTaskBody(
      body,
      Number(sourceRow.dataset.repoIssueTaskLine),
      Number(targetRow.dataset.repoIssueTaskLine),
      Boolean(placeAfter),
    );
    if (nextBody === body) return;

    issueTaskMutationPending = true;
    if (placeAfter) targetRow.after(sourceRow);
    else targetRow.before(sourceRow);
    sourceRow.classList.add("is-task-settling");
    const status = sourceRow.querySelector("[data-repo-issue-task-status]");
    if (status) status.textContent = "Saving new position…";
    setIssueTaskControlsBusy(true);
    const motionDone = new Promise((resolve) => window.setTimeout(resolve, 320));
    try {
      const result = await submitWebIssueTaskBody(nextBody);
      optimisticWebIssueEvent(result.event);
      await motionDone;
      renderCurrentWebIssueDetail();
    } catch (error) {
      renderCurrentWebIssueDetail();
      showErrorNotice(webIssueActionError(error));
    } finally {
      issueTaskMutationPending = false;
      setIssueTaskControlsBusy(false);
    }
  }

  function clearIssueTaskDragState() {
    document.querySelectorAll(
      ".is-task-dragging, .is-task-drop-before, .is-task-drop-after",
    ).forEach((row) => row.classList.remove(
      "is-task-dragging", "is-task-drop-before", "is-task-drop-after",
    ));
  }

  function handleIssueTaskDragStart(event) {
    const handle = event.target.closest?.("[data-repo-issue-task-drag]");
    const row = handle?.closest("[data-repo-issue-task-row]");
    if (!row || issueTaskMutationPending) {
      event.preventDefault();
      return;
    }
    issueTaskDrag = { row, group: row.dataset.repoIssueTaskGroup };
    row.classList.add("is-task-dragging");
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", row.dataset.repoIssueTaskLine || "");
    }
  }

  function handleIssueTaskDragOver(event) {
    if (!issueTaskDrag) return;
    const targetRow = event.target.closest?.("[data-repo-issue-task-row]");
    if (!targetRow || targetRow === issueTaskDrag.row
        || targetRow.dataset.repoIssueTaskGroup !== issueTaskDrag.group) return;
    event.preventDefault();
    clearIssueTaskDragState();
    issueTaskDrag.row.classList.add("is-task-dragging");
    const bounds = targetRow.getBoundingClientRect();
    targetRow.classList.add(
      event.clientY >= bounds.top + (bounds.height / 2)
        ? "is-task-drop-after"
        : "is-task-drop-before",
    );
    if (event.dataTransfer) event.dataTransfer.dropEffect = "move";
  }

  function handleIssueTaskDrop(event) {
    if (!issueTaskDrag) return;
    const targetRow = event.target.closest?.("[data-repo-issue-task-row]");
    const sourceRow = issueTaskDrag.row;
    const sameGroup = targetRow
      && targetRow !== sourceRow
      && targetRow.dataset.repoIssueTaskGroup === issueTaskDrag.group;
    if (sameGroup) {
      event.preventDefault();
      const placeAfter = targetRow.classList.contains("is-task-drop-after");
      clearIssueTaskDragState();
      issueTaskDrag = null;
      void handleWebIssueTaskReorder(sourceRow, targetRow, placeAfter);
      return;
    }
    clearIssueTaskDragState();
    issueTaskDrag = null;
  }

  function handleIssueTaskDragEnd() {
    clearIssueTaskDragState();
    issueTaskDrag = null;
  }

  function handleIssueTaskReorderKey(event) {
    const handle = event.target.closest?.("[data-repo-issue-task-drag]");
    if (!handle || !["ArrowUp", "ArrowDown"].includes(event.key)) return false;
    const row = handle.closest("[data-repo-issue-task-row]");
    const peers = [...(row?.parentElement?.children || [])].filter(
      (candidate) => candidate.matches?.("[data-repo-issue-task-row]")
        && candidate.dataset.repoIssueTaskGroup === row.dataset.repoIssueTaskGroup,
    );
    const index = peers.indexOf(row);
    const target = event.key === "ArrowUp" ? peers[index - 1] : peers[index + 1];
    if (!target) return false;
    event.preventDefault();
    void handleWebIssueTaskReorder(row, target, event.key === "ArrowDown");
    return true;
  }

  async function handleWebIssueSubtasks(button) {
    const detail = state.repoRecordDetail;
    const repo = detail?.repo;
    const parentNumber = Number(detail?.number || 0);
    const parentBody = String(detail?.parsed?.body || "");
    const requestedLine = button?.hasAttribute("data-repo-issue-task-subissue")
      ? Number(button.dataset.repoIssueTaskSubissue)
      : null;
    const selectedCandidate = requestedLine === null
      ? null
      : issueSubtaskCandidateAtLine(parentBody, requestedLine);
    const candidates = requestedLine === null
      ? issueSubtaskCandidates(parentBody)
      : (selectedCandidate ? [selectedCandidate] : []);
    if (!repo || detail?.kind !== "issues" || !parentNumber || !candidates.length) {
      return;
    }
    if (issueTaskMutationPending) return;
    const prompt = requestedLine !== null
      ? "Turn this task into an attached sub-issue? The child will link back here and this row will keep its issue number."
      : candidates.length === 1
      ? "Create one sub-issue from this unchecked task? The child will link back here and the task will gain its issue number."
      : `Create ${candidates.length} sub-issues from the unchecked tasks? Each child will link back here and each task will gain its issue number.`;
    if (!await confirmAccountAction({
      title: requestedLine !== null ? "Turn this task into a sub-issue?" : "Create sub-issues?",
      body: prompt,
      confirmLabel: requestedLine !== null || candidates.length === 1 ? "Create sub-issue" : "Create sub-issues",
      danger: false,
    })) return;

    issueTaskMutationPending = true;
    setIssueTaskControlsBusy(true);
    if (button) {
      button.disabled = true;
      button.textContent = "Creating sub-issues…";
    }
    const linked = [];
    let failure = null;
    for (const candidate of candidates) {
      try {
        const childBody = `Parent issue: #${parentNumber}`;
        const result = await submitWebIssue(repo, candidate.title, childBody);
        const childNumber = Number(result.number || 0);
        if (!Number.isInteger(childNumber) || childNumber <= 0) {
          throw new Error("number_unavailable");
        }
        linked.push({ ...candidate, number: childNumber });
        const author = result.event.authorName || state.session?.nodeName || "you";
        const item = {
          number: childNumber,
          title: candidate.title,
          status: "open",
          state: "open",
          author,
          date: "just now",
          meta: `parent: #${parentNumber}`,
          body: childBody,
        };
        state.issuesView.items = [
          item,
          ...(state.issuesView.items || []).filter(
            (issue) => Number(issue.number) !== childNumber),
        ];
        rememberOptimisticRepoRecord(repo, "issues", childNumber, {
          values: {
            title: candidate.title,
            status: "open",
            author: result.event.author,
            authorName: author,
            createdAt: result.event.ts,
          },
          body: childBody,
          issueEvents: [result.event],
          issueCreator: result.event.author,
          issueOpenEventId: result.event.id,
          issueOpenAttachments: [],
        });
      } catch (error) {
        failure = error;
        break;
      }
    }

    if (linked.length) {
      try {
        const result = await submitWebIssueEvent(
          repo,
          parentNumber,
          "edit",
          {
            target: detail.parsed.issueOpenEventId,
            body: linkIssueSubtasks(parentBody, linked),
            attachments: detail.parsed.issueOpenAttachments || [],
          },
        );
        optimisticWebIssueEvent(result.event);
      } catch (error) {
        failure ||= error;
      }
    }

    if (linked.length) {
      setRepoTabCount(
        "issues",
        (state.issuesView.items || []).filter(
          (issue) => issue.status !== "closed" && !issue.deleted).length,
      );
      renderCurrentWebIssueDetail();
    } else if (button) {
      if (requestedLine !== null) renderCurrentWebIssueDetail();
      else {
        button.disabled = false;
        button.textContent = candidates.length === 1
          ? "Create sub-issue"
          : `Create ${candidates.length} sub-issues`;
      }
    }
    issueTaskMutationPending = false;
    setIssueTaskControlsBusy(false);
    if (failure) {
      const prefix = linked.length
        ? `${linked.length} sub-issue${linked.length === 1 ? " was" : "s were"} created. `
        : "";
      showErrorNotice(prefix + webIssueActionError(failure));
    }
  }

  async function handleWebIssueMetadataSubmit(form) {
    const detail = state.repoRecordDetail;
    const values = detail?.parsed?.values || {};
    // The sidebar pickers submit a hidden form; its status line sits above
    // the sidebar sections rather than inside the form.
    const hint = form.querySelector("[data-repo-issue-metadata-hint]")
      || document.querySelector("[data-repo-issue-metadata-hint]");
    const submit = form.querySelector("[data-repo-issue-metadata-save]");
    const labels = splitWebIssueList(form.querySelector("[data-repo-issue-labels]")?.value);
    const assignees = splitWebIssueList(form.querySelector("[data-repo-issue-assignees]")?.value);
    const milestone = String(form.querySelector("[data-repo-issue-milestone-edit]")?.value || "").trim();
    const priority = Math.min(99, Math.max(0, Number(form.querySelector("[data-repo-issue-priority]")?.value) || 0));
    const progress = Math.min(100, Math.max(0, Number(form.querySelector("[data-repo-issue-progress]")?.value) || 0));
    const dateValue = (selector) => {
      const value = String(form.querySelector(selector)?.value || "");
      return value ? Date.parse(`${value}T00:00:00Z`) || 0 : 0;
    };
    const startDate = dateValue("[data-repo-issue-start-date]");
    const endDate = dateValue("[data-repo-issue-end-date]");
    const actions = [];
    if (labels.join(",") !== parseFrontMatterList(values.labels).join(",")) actions.push(["labels", { labels }]);
    // Compare against the same claim-folded list the form was seeded with, so
    // opening and saving the editor without touching assignees does not emit an
    // "assignees" event that silently reverts a contributor's self-assignment.
    const shownAssignees = webIssueAssigneesWithClaims(
      parseFrontMatterList(values.assignees), detail?.parsed?.issueEvents,
    );
    if (assignees.join(",") !== shownAssignees.join(",")) actions.push(["assignees", { assignees }]);
    if (milestone !== String(values.milestone || "")) actions.push(["milestone", { milestone }]);
    if (priority !== (Number(values.priority) || 0)) actions.push(["priority", { priority }]);
    if (progress !== (Number(values.progress) || 0)) actions.push(["progress", { progress }]);
    if (startDate !== (Number(values.startDate) || 0) || endDate !== (Number(values.endDate) || 0)) actions.push(["dates", { startDate, endDate }]);
    if (!actions.length) {
      if (hint) hint.textContent = "No changes";
      return;
    }
    if (submit) submit.disabled = true;
    if (hint) hint.textContent = "Signing…";
    try {
      for (const [type, fields] of actions) {
        const result = await submitWebIssueEvent(
          detail.repo,
          detail.number,
          type,
          fields,
        );
        optimisticWebIssueEvent(result.event);
      }
      renderCurrentWebIssueDetail();
    } catch (error) {
      if (submit) submit.disabled = false;
      if (hint) {
        hint.className = "text-[10px] text-destructive";
        hint.textContent = webIssueActionError(error);
      }
    }
  }

  async function handleDiscussionAnswerClick(repo, button) {
    if (!repo || !button) return;
    const number = Number(button.dataset.repoDiscussionAnswerNumber || 0);
    const target = String(button.dataset.repoDiscussionAnswer || "");
    const section = button.closest("[data-repo-record-conversation]");
    const hint = section?.querySelector("[data-repo-discussion-reply-hint]");
    const setHint = (text, bad) => {
      if (!hint) return;
      hint.className = `text-[11px] ${bad ? "text-destructive" : "text-muted-foreground"}`;
      hint.textContent = text;
    };
    if (!number) return;
    button.disabled = true;
    setHint("Signing and sending…");
    try {
      await submitWebDiscussionAnswer(repo, number, target);
      const detail = state.repoRecordDetail;
      const parsed = detail?.parsed;
      if (parsed && Number(detail.number) === number) {
        parsed.discussionAnswer = target ? { target } : null;
        const list = section?.querySelector("[data-repo-discussion-conversation]");
        if (list) {
          list.innerHTML = renderRepoDiscussionConversation(parsed.discussionConversation || [], {
            answer: parsed.discussionAnswer,
            canMark: parsed.discussionAnswerAuthorized,
            number,
          });
          window.lucide?.createIcons();
        }
      }
      setHint(target ? "Answer marked. It shows for everyone once the repository records it." : "Answer cleared.");
    } catch (error) {
      button.disabled = false;
      const code = String(error?.message || "");
      setHint(
        code === "bad_signature" ? "Could not verify the answer's signature."
          : code === "inbox_full" ? "Delivery is temporarily full. Try again later."
          : "Could not mark the answer. Please try again.",
        true,
      );
    }
  }

  async function handleDiscussionReplySubmit(repo, form) {
    if (!repo || !form) return;
    const number = Number(form.dataset.repoDiscussionReplyNumber || 0);
    const bodyInput = form.querySelector("[data-repo-discussion-reply-body]");
    const submit = form.querySelector("[data-repo-discussion-reply-submit]");
    const hint = form.querySelector("[data-repo-discussion-reply-hint]");
    const setHint = (text, tone) => {
      if (hint) hint.className = `text-[11px] ${tone === "bad" ? "text-destructive" : "text-muted-foreground"}`;
      if (hint) hint.textContent = text;
    };
    const body = String(bodyInput?.value || "").trim();
    if (!number) {
      setHint("This discussion hasn't finished loading yet.", "bad");
      return;
    }
    if (!body) {
      setHint("Write a reply before sending.", "bad");
      bodyInput?.focus();
      return;
    }
    if (submit) submit.disabled = true;
    setHint("Signing and sending…");
    try {
      await submitWebDiscussionComment(repo, number, body);
      const list = form.parentElement?.querySelector("[data-repo-discussion-conversation]");
      if (list) {
        if (list.dataset.empty === "true") list.innerHTML = "";
        list.dataset.empty = "false";
        list.insertAdjacentHTML("beforeend", renderPullConversationEvent({
          type: "comment", authorName: state.session?.nodeName || "you",
          ts: Math.floor(Date.now() / 1000), body,
        }));
      }
      if (bodyInput) bodyInput.value = "";
      if (submit) submit.disabled = false;
      setHint("Reply accepted for direct delivery to an eligible mirror.", "good");
    } catch (error) {
      if (submit) submit.disabled = false;
      const code = String(error?.message || "");
      setHint(
        code === "inbox_full" ? "Reply delivery is temporarily full. Try again later."
          : code === "author_quota" ? "You've reached the submission limit for this repository."
          : code === "discussion_too_large" ? "The reply is too large - please shorten it."
          : code === "bad_signature" ? "Could not verify the reply's signature."
          : "Could not send the reply. Please try again.",
        "bad");
    }
  }

  function sessionFromAccountPayload(body, base = {}) {
    rememberUserNameCase(body.nodeName || body.name || base.nodeName || "", body.nameCase);
    const nextSession = {
      ...(base || {}),
      nodeName: body.nodeName || body.name || base.nodeName || "",
      nameCase: body.nameCase ?? base.nameCase ?? "",
      email: body.email ?? base.email ?? "",
      status: body.status || base.status || "active",
      pubkey: body.pubkey || base.pubkey || "",
      emailVerified: Object.prototype.hasOwnProperty.call(body, "emailVerified")
        ? Boolean(body.emailVerified)
        : Boolean(base.emailVerified),
      isAdmin: Object.prototype.hasOwnProperty.call(body, "isAdmin")
        ? Boolean(body.isAdmin)
        : Boolean(base.isAdmin),
      adminUrl: body.adminUrl || base.adminUrl || "",
      solana: body.solana || base.solana || "",
      hasPayoutAddress: Object.prototype.hasOwnProperty.call(body, "hasPayoutAddress")
        ? Boolean(body.hasPayoutAddress)
        : Boolean(base.hasPayoutAddress),
      sessionToken: body.sessionToken ?? base.sessionToken ?? "",
      avatarPng: body.avatarPng || "",
      avatarUpdatedAt: Number(body.avatarUpdatedAt) || 0,
      createdAt: Number(body.createdAt ?? base.createdAt ?? 0) || 0,
      profileBio: body.profileBio ?? base.profileBio ?? "",
      userStatus: body.userStatus ?? base.userStatus ?? null,
      profileAbout: body.profileAbout ?? body.profileReadme ?? base.profileAbout ?? base.profileReadme ?? "",
      profileReadme: body.profileReadme ?? body.profileAbout ?? base.profileReadme ?? base.profileAbout ?? "",
      profileLocation: body.profileLocation ?? base.profileLocation ?? "",
      profileTimezone: body.profileTimezone ?? base.profileTimezone ?? "",
      profileFollowers: Number(body.followers ?? body.profileFollowers ?? base.profileFollowers ?? 0) || 0,
      profileFollowing: Number(body.following ?? body.profileFollowing ?? base.profileFollowing ?? 0) || 0,
      profileMirrorCount: Number(body.mirrorCount ?? body.profileMirrorCount ?? base.profileMirrorCount ?? 0) || 0,
      referralClicks: Number(body.referralClicks ?? base.referralClicks ?? 0) || 0,
      creditedReferrals: Number(body.creditedReferrals ?? base.creditedReferrals ?? 0) || 0,
      referralLastAt: Number(body.referralLastAt ?? base.referralLastAt ?? 0) || 0,
      referredUsers: Array.isArray(body.referredUsers)
        ? body.referredUsers
        : (base.referredUsers || []),
      legacyUnattributed: Number(body.legacyUnattributed ?? base.legacyUnattributed ?? 0) || 0,
      profilePrivate: Object.prototype.hasOwnProperty.call(body, "profilePrivate")
        ? Boolean(body.profilePrivate)
        : Boolean(base.profilePrivate),
      followersPublic: Object.prototype.hasOwnProperty.call(body, "followersPublic")
        ? Boolean(body.followersPublic)
        : Boolean(base.followersPublic),
      publicEmail: body.publicEmail ?? base.publicEmail ?? "",
      mastodon: body.mastodon ?? base.mastodon ?? "",
      mastodonUrl: body.mastodonUrl ?? base.mastodonUrl ?? "",
      profileLinks: Array.isArray(body.profileLinks)
        ? body.profileLinks
        : (base.profileLinks || []),
      emailNotifications: Object.prototype.hasOwnProperty.call(body, "emailNotifications")
        ? Boolean(body.emailNotifications)
        : Boolean(base.emailNotifications ?? true),
      notificationPreferences: body.notificationPreferences && typeof body.notificationPreferences === "object"
        ? body.notificationPreferences
        : (base.notificationPreferences || {}),
      notificationDelivery: body.notificationDelivery || base.notificationDelivery || "digest",
      notificationPauseUntil: Number(
        Object.prototype.hasOwnProperty.call(body, "notificationPauseUntil")
          ? body.notificationPauseUntil
          : base.notificationPauseUntil,
      ) || 0,
      // The Pings settings page (#347) paints from these before its own read.
      pingMutedKinds: Array.isArray(body.pingMutedKinds)
        ? body.pingMutedKinds
        : (Array.isArray(base.pingMutedKinds) ? base.pingMutedKinds : []),
      notificationQuietHours: body.notificationQuietHours && typeof body.notificationQuietHours === "object"
        ? body.notificationQuietHours
        : (base.notificationQuietHours || null),
      notificationQuietUntil: Number(body.notificationQuietUntil ?? base.notificationQuietUntil ?? 0) || 0,
      pingKindCatalog: Array.isArray(body.pingKindCatalog)
        ? body.pingKindCatalog
        : (Array.isArray(base.pingKindCatalog) ? base.pingKindCatalog : null),
      kind: body.kind || base.kind || "",
      owner: body.owner ?? base.owner ?? "",
      online: Object.prototype.hasOwnProperty.call(body, "online")
        ? Boolean(body.online)
        : Boolean(base.online),
      nodes: Array.isArray(body.nodes) ? body.nodes : (base.nodes || []),
      accountSnapshotVersion: 1,
      at: Date.now(),
    };
    if (!Object.prototype.hasOwnProperty.call(body, "avatarPng")) {
      nextSession.avatarPng = base.avatarPng || "";
    }
    if (!Object.prototype.hasOwnProperty.call(body, "avatarUpdatedAt")) {
      nextSession.avatarUpdatedAt = Number(base.avatarUpdatedAt) || 0;
    }
    return nextSession;
  }

  function applyAvatar(container, session) {
    if (!container) return;
    const name = session?.nodeName || session?.email || platformName();
    const initial = (name[0] || "F").toUpperCase();
    const avatarPng = session?.avatarPng || "";
    const image = container.querySelector("img");
    const initialEl = container.querySelector("[data-avatar-initial]");
    if (image) {
      if (avatarPng) {
        image.src = `data:image/png;base64,${avatarPng}`;
        image.alt = `${name} profile picture`;
      } else {
        image.removeAttribute("src");
        image.alt = "";
      }
      image.classList.toggle("hidden", !avatarPng);
    }
    if (initialEl) {
      initialEl.textContent = initial;
      initialEl.classList.toggle("hidden", Boolean(avatarPng));
    } else if (!image) {
      container.textContent = initial;
    }
    container.classList.toggle("font-mono", !avatarPng);
  }

  async function refreshPublicProfile(session = state.session, options = {}) {
    return hydrateCanonicalProfile(session, options);
  }

  async function hydrateCanonicalProfile(session, { force = false } = {}) {
    const nodeName = String(session?.nodeName || "").trim().toLowerCase();
    if (!validNodeName(nodeName)) return session;
    // Login already returns the same canonical account payload this endpoint
    // serves. Keep one fallback read for sessions written by older clients or
    // restored from a cross-origin cookie, then persist the version above so
    // subsequent dashboard documents do not request the account again.
    if (!force && Number(session?.accountSnapshotVersion) >= 1) return session;
    const mutationVersion = state.profileMutationVersion;
    try {
      // A viewer-qualified lookup is deliberately outside the guest profile
      // edge cache. Combined with a no-store browser fetch, this makes the
      // signed-in owner's reload an authoritative read after an edit instead
      // of reusing the pre-edit public snapshot.
      const encodedName = encodeURIComponent(nodeName);
      const body = await fetchJson(
        `/api/accounts/${encodedName}?viewer=${encodedName}`,
        {
          fresh: true,
          // The viewer query already bypasses the Worker's manual edge cache.
          // Keep the URL stable so simultaneous boot/page hydration shares
          // one in-flight no-store request.
          cacheBust: false,
        });
      // A profile POST may have started while this request was in flight. Its
      // response is newer even if this older GET happens to finish last.
      if (mutationVersion !== state.profileMutationVersion) {
        return state.session || session;
      }
      if (body.exists === false) return session;
      const nextSession = sessionFromAccountPayload(body, session);
      writeSession(nextSession);
      renderProfile(nextSession);
      return nextSession;
    } catch (_) {
      return session;
    }
  }
  // Every top-level page is its own document now (/dashboard, /dashboard/repos,
  // /dashboard/network, ...) — navigation between them is a real page load via
  // plain <a href> links, so there is no client-side section router anymore.
  // The only client-routed state left is within-page: repo tabs/tree/blob on
  // the repo page, and the settings sub-tabs below.

  // Every password field sits in its own <form data-credential-scope>. Chrome
  // pools all form-less inputs of a page into one synthetic login form, and a
  // bare password field anywhere (even inside a hidden modal) made it treat the
  // visible search boxes as the username and stuff the saved email into them
  // (#671). The forms are scopes only; the buttons beside them do the saving.
  document.addEventListener("submit", (event) => {
    if (event.target instanceof Element && event.target.matches("[data-credential-scope]")) {
      event.preventDefault();
    }
  });

  const SETTINGS_SECTIONS = ["public-profile", "account", "ssh-keys", "appearance", "notifications", "payout", "nodes", "organizations", "danger", "apps", "agents"];

  function normalizeSettingsSection(section) {
    return SETTINGS_SECTIONS.includes(section) ? section : "public-profile";
  }

  // The settings sub-tab addressed by the URL (/dashboard/settings/<tab>), so a
  // refresh keeps the tab instead of snapping back to public-profile.
  function settingsSectionFromPath() {
    const parts = location.pathname.split("/").filter(Boolean);
    return normalizeSettingsSection(parts[0] === "dashboard" && parts[1] === "settings" ? parts[2] || "" : "");
  }

  function setSettingsSection(section, { scroll = true, push = false } = {}) {
    const activeSection = normalizeSettingsSection(section);
    if (!state.settingsView) state.settingsView = {};
    state.settingsView.section = activeSection;
    if (push) {
      // Reflect the tab in the URL so refresh/back keep it. public-profile is
      // the default, so it stays on the bare /dashboard/settings URL.
      navigateHistory(activeSection === "public-profile"
        ? "/dashboard/settings"
        : `/dashboard/settings/${activeSection}`);
    }

    $$("[data-settings-section]").forEach((panel) => {
      const active = panel.dataset.settingsSection === activeSection;
      panel.classList.toggle("hidden", !active);
    });

    $$("[data-settings-section-link]").forEach((button) => {
      const active = button.dataset.settingsSectionLink === activeSection;
      button.setAttribute("aria-current", active ? "page" : "false");
      button.className = active
        ? "relative flex h-10 items-center gap-3 rounded-md bg-secondary px-3 pl-4 text-left font-semibold text-foreground"
        : "relative flex h-10 items-center gap-3 rounded-md px-4 text-left text-muted-foreground hover:bg-secondary hover:text-foreground";
      button.querySelector("[data-settings-active-indicator]")?.classList.toggle("hidden", !active);
    });

    const settingsMain = $("[data-settings-main]");
    if (scroll && settingsMain) {
      settingsMain.scrollIntoView({ block: "start", behavior: "smooth" });
    }

    // The Organizations tab is data-driven and only fetched when first opened.
    if (activeSection === "organizations") initOrgsSection();
    if (activeSection === "ssh-keys") loadSshKeys();
    if (activeSection === "notifications") loadPingSettings();
    if (activeSection === "agents") initSettingsAgents();
    // Session state changes on other devices, so re-entering this tab always
    // performs a fresh no-store read instead of keeping a page-lifetime copy.
    if (activeSection === "account") {
      bindAccountPasswordControls();
      loadAccountSessions({ force: true });
      loadAccountDevices({ force: true });
      loadPatreonConnection();
      consumePatreonCallbackOutcome();
      loadMembership({ force: true });
      loadPlanUsage();
      loadEmailFooter();
    }
  }

  // ---- Patreon membership link ---------------------------------------------
  const PATREON_OUTCOME_TEXT = {
    connected: ["Patreon linked. Membership syncs from your current pledge.", "good"],
    denied: ["Patreon authorization was denied.", "bad"],
    duplicate_identity: ["That Patreon account is already linked to another ForkMesh user.", "bad"],
    expired: ["The Patreon link expired. Start Connect Patreon again.", "bad"],
    failed: ["Patreon linking failed. Try Connect Patreon again.", "bad"],
    invalid: ["Patreon linking could not be completed.", "bad"],
    invalid_membership: ["Patreon membership data was incomplete. Try again after your pledge is active.", "bad"],
    mismatch: ["Patreon linking did not match this signed-in session.", "bad"],
    not_configured: ["Patreon linking is not configured on this instance.", "bad"],
    replayed: ["That Patreon link was already used.", "bad"],
    wrong_campaign: ["That Patreon membership is not for the ForkMesh campaign.", "bad"],
  };

  function accountBlankslate(icon, title, desc = "") {
    return `<div class="fm-blankslate"><i data-lucide="${escapeHtml(icon)}" aria-hidden="true"></i><p class="fm-blankslate-title">${escapeHtml(title)}</p>${desc ? `<p class="fm-blankslate-desc">${escapeHtml(desc)}</p>` : ""}</div>`;
  }

  function accountListError(message) {
    return `<p class="flex items-center gap-2 p-4 text-sm text-destructive"><i data-lucide="circle-alert" class="h-4 w-4 shrink-0" aria-hidden="true"></i>${escapeHtml(message)}</p>`;
  }

  function confirmAccountAction({ title, body = "", confirmLabel = "Confirm", danger = true } = {}) {
    return new Promise((resolve) => {
      const previous = document.activeElement;
      const overlay = document.createElement("div");
      overlay.dataset.accountConfirm = "";
      overlay.className = "fixed inset-0 z-[90] flex items-start justify-center bg-background/70 p-4 pt-[15vh]";
      overlay.innerHTML = `
        <div role="alertdialog" aria-modal="true" aria-labelledby="accountConfirmTitle"${body ? ' aria-describedby="accountConfirmBody"' : ""} class="fm-dialog w-full max-w-md">
          <div class="fm-dialog-header">
            <h2 id="accountConfirmTitle" class="fm-dialog-title">${escapeHtml(title)}</h2>
            <button type="button" data-account-confirm-cancel aria-label="Close" class="fm-btn fm-btn-sm fm-btn-icon fm-btn-invisible"><i data-lucide="x"></i></button>
          </div>
          ${body ? `<div id="accountConfirmBody" class="fm-dialog-body text-muted-foreground">${escapeHtml(body)}</div>` : ""}
          <div class="fm-dialog-footer">
            <button type="button" data-account-confirm-cancel class="fm-btn fm-btn-sm">Cancel</button>
            <button type="button" data-account-confirm-ok class="fm-btn fm-btn-sm ${danger ? "fm-btn-danger" : "fm-btn-cta"}">${escapeHtml(confirmLabel)}</button>
          </div>
        </div>`;
      const onKey = (event) => {
        if (event.key !== "Escape") return;
        event.preventDefault();
        event.stopPropagation();
        finish(false);
      };
      const finish = (value) => {
        document.removeEventListener("keydown", onKey, true);
        overlay.remove();
        if (previous?.isConnected && typeof previous.focus === "function") previous.focus();
        resolve(value);
      };
      overlay.addEventListener("click", (event) => {
        if (event.target === overlay || event.target.closest("[data-account-confirm-cancel]")) finish(false);
        else if (event.target.closest("[data-account-confirm-ok]")) finish(true);
      });
      document.addEventListener("keydown", onKey, true);
      document.body.appendChild(overlay);
      window.lucide?.createIcons();
      overlay.querySelector(".fm-dialog-footer [data-account-confirm-cancel]")?.focus();
    });
  }

  function setPatreonStatus(message, kind = "") {
    const target = $("[data-patreon-connection-status]");
    if (!target) return;
    target.textContent = message || "";
    target.className = "min-h-4 text-xs " + (
      kind === "bad" ? "text-destructive"
        : kind === "good" ? "text-success"
        : "text-muted-foreground"
    );
  }

  function consumePatreonCallbackOutcome() {
    const params = new URLSearchParams(location.search);
    const outcome = (params.get("patreon") || "").trim();
    if (!outcome) return;
    params.delete("patreon");
    const rest = params.toString();
    window.history.replaceState(
      null,
      "",
      location.pathname + (rest ? `?${rest}` : "") + location.hash,
    );
    const mapped = PATREON_OUTCOME_TEXT[outcome] || PATREON_OUTCOME_TEXT.invalid;
    setPatreonStatus(mapped[0], mapped[1]);
  }

  async function loadPatreonConnection() {
    const stateEl = $("[data-patreon-connection-state]");
    const button = $("[data-patreon-connect]");
    if (!stateEl || !button) return;
    if (!state.session?.sessionToken) {
      stateEl.textContent = "Sign in to link Patreon.";
      button.textContent = "Connect Patreon";
      button.disabled = true;
      return;
    }
    button.disabled = true;
    stateEl.textContent = "Checking connection…";
    try {
      const token = state.session.sessionToken || "";
      const response = await fetch("/api/accounts/patreon", {
        headers: {
          accept: "application/json",
          ...(token && token !== "cookie"
            ? { authorization: "Bearer " + token }
            : {}),
        },
        credentials: "same-origin",
        cache: "no-store",
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        stateEl.textContent = "Could not load Patreon connection.";
        button.textContent = "Connect Patreon";
        button.disabled = true;
        return;
      }
      button.dataset.patreonConfigured = data.configured ? "true" : "false";
      button.disabled = !data.configured;
      if (data.connected) {
        const tier = String(data.tier || "core");
        const tierLabel = {
          supporter: "Supporter",
          pro: "Pro",
          builder: "Builder",
          studio: "Studio",
        }[tier];
        stateEl.textContent = tierLabel
          ? `Connected · ${tierLabel} membership synced`
          : "Connected · waiting for an active pledge sync";
        button.textContent = "Reconnect Patreon";
      } else {
        stateEl.textContent = "Not connected";
        button.textContent = "Connect Patreon";
      }
      if (!data.configured) {
        button.textContent = data.connected
          ? "Patreon linking unavailable"
          : "Use Patreon memberships";
        button.disabled = true;
        setPatreonStatus(
          "Account linking is not configured here. Use the Patreon memberships link below.",
        );
      }
    } catch (_) {
      stateEl.textContent = "Could not load Patreon connection.";
      button.textContent = "Connect Patreon";
      button.disabled = true;
    }
  }

  async function startPatreonOAuth() {
    const button = $("[data-patreon-connect]");
    const token = state.session?.sessionToken || "";
    if (!token) {
      setPatreonStatus("Sign in to link Patreon.", "bad");
      return;
    }
    if (button?.dataset.patreonConfigured === "false") {
      setPatreonStatus(
        "Account linking is not configured here. Use the Patreon memberships link below.",
      );
      return;
    }
    if (button) {
      button.disabled = true;
      button.textContent = "Redirecting…";
    }
    setPatreonStatus("Starting Patreon connection…", "");
    try {
      const body = {};
      if (token !== "cookie") body.sessionToken = token;
      const response = await fetch("/api/accounts/patreon/oauth/start", {
        method: "POST",
        headers: {
          accept: "application/json",
          "content-type": "application/json",
          ...(token !== "cookie" ? { authorization: "Bearer " + token } : {}),
        },
        credentials: "same-origin",
        body: JSON.stringify(body),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.authorizationUrl) {
        throw new Error(data.error || "oauth_start_failed");
      }
      location.href = String(data.authorizationUrl);
      return;
    } catch (error) {
      const code = String(error.message || "");
      setPatreonStatus(
        code === "patreon_oauth_not_configured"
          ? "Patreon linking is not configured on this instance yet."
          : "Could not start Patreon linking. Try again.",
        "bad",
      );
    } finally {
      if (button) {
        button.disabled = true;
        void loadPatreonConnection();
      }
    }
  }

  // ---- Membership ---------------------------------------------------------
  function sessionHeaders(json = false) {
    const token = String(state.session?.sessionToken || "");
    return {
      accept: "application/json",
      ...(json ? { "content-type": "application/json" } : {}),
      ...(token && token !== "cookie"
        ? { authorization: "Bearer " + token }
        : {}),
    };
  }

  // Whoever sold the membership, the entitlement is a role grant; the plan
  // surface reports it, so this card needs no payment provider of its own.
  let membershipLoaded = false;
  let membershipLoading = null;

  function renderMembership(plan) {
    const summary = $("[data-membership-summary]");
    const choose = $("[data-membership-choose]");
    const invite = $("[data-membership-invite]");
    if (!summary || !choose) return;
    const membership = plan?.membership || null;
    const promotion = plan?.promotion || null;
    const held = membership || promotion;
    const tier = String(held?.tier || "");
    const expires = Number(held?.expiresAt || 0);
    const name = tier === "pro" ? "Pro" : "Supporter";
    summary.textContent = !held
      ? "No active membership. ForkMesh plans remain free during launch."
      : membership
        ? `${name} membership active${expires ? ` through ${formatDate(expires)}` : ""}.`
        : `${name} membership through ${expires ? `${formatDate(expires)}` : "a ForkMesh award"}, on the house.`;
    choose.hidden = Boolean(held);
    if (invite) invite.hidden = !held;
    if (held && (tier === "pro" || tier === "supporter")) {
      document.documentElement.dataset.fmPlan = tier;
    } else {
      delete document.documentElement.dataset.fmPlan;
    }
  }

  async function loadMembership({ force = false } = {}) {
    if (!$("[data-membership-summary]")) return;
    if (membershipLoaded && !force) return;
    if (membershipLoading) return membershipLoading;
    membershipLoading = (async () => {
      try {
        const response = await fetch("/api/plans/usage", {
          headers: sessionHeaders(),
          credentials: "same-origin",
          cache: "no-store",
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(String(data.error || response.status));
        renderMembership(data);
        membershipLoaded = true;
      } catch (_) {
        const summary = $("[data-membership-summary]");
        if (summary) summary.textContent = "Could not load membership.";
      } finally {
        membershipLoading = null;
      }
    })();
    return membershipLoading;
  }

  // ---- Plan usage + trial (issue #488) -------------------------------------
  function setPlanUsageStatus(message, kind = "") {
    const target = $("[data-plan-usage-status]");
    if (!target) return;
    target.textContent = message || "";
    target.className = "mt-2 min-h-4 text-xs " + (
      kind === "bad" ? "text-destructive"
        : kind === "good" ? "text-success"
        : "text-muted-foreground"
    );
  }

  async function planServicesApi(action, method = "GET") {
    const token = String(state.session?.sessionToken || "");
    if (!token) throw new Error("invalid_session");
    const response = await fetch("/api/plans/" + action, {
      method,
      headers: sessionHeaders(method !== "GET"),
      credentials: "same-origin",
      cache: "no-store",
      ...(method !== "GET"
        ? { body: JSON.stringify(token === "cookie" ? {} : { sessionToken: token }) }
        : {}),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      throw new Error(data.error || `http_${response.status}`);
    }
    return data;
  }

  function renderPlanUsage(data) {
    const list = $("[data-plan-usage-meters]");
    if (!list) return;
    const meters = data?.meters && typeof data.meters === "object" ? data.meters : {};
    list.textContent = "";
    for (const meter of Object.values(meters)) {
      const row = document.createElement("div");
      row.className = "flex items-center justify-between gap-3 rounded-md border border-border px-3 py-2";
      const label = document.createElement("dt");
      label.className = "text-sm text-muted-foreground";
      label.textContent = String(meter?.label || "");
      const value = document.createElement("dd");
      value.className = "text-sm font-semibold text-foreground";
      value.textContent = `${Number(meter?.used || 0)} / ${Number(meter?.limit || 0)}`;
      row.append(label, value);
      list.append(row);
    }
    list.hidden = !list.childElementCount;
    const summary = $("[data-plan-usage-summary]");
    if (summary) {
      summary.textContent = "What this account uses today, against the limits every account shares.";
    }
  }

  function renderPlanTrial(trial) {
    const button = $("[data-plan-trial-start]");
    if (!button) return;
    button.hidden = !trial?.eligible;
    if (trial?.active) {
      setPlanUsageStatus(`Supporter trial active through ${formatDate(Number(trial.endsAt || 0))}.`);
    } else if (trial?.used) {
      setPlanUsageStatus("Your one Supporter trial has ended. Memberships continue through checkout above.");
    }
  }

  function bindPlanTrialControls() {
    const button = $("[data-plan-trial-start]");
    if (!button || button.dataset.bound === "true") return;
    button.dataset.bound = "true";
    button.addEventListener("click", async () => {
      button.disabled = true;
      setPlanUsageStatus("Starting your Supporter trial…");
      try {
        const data = await planServicesApi("trial", "POST");
        button.hidden = true;
        setPlanUsageStatus(`Supporter trial active through ${formatDate(Number(data.endsAt || 0))}.`);
        loadMembership({ force: true });
      } catch (error) {
        const code = String(error.message || "");
        setPlanUsageStatus(
          code === "trial_already_used" ? "This account already used its Supporter trial."
            : code === "already_subscribed" ? "You already have an active membership — no trial needed."
              : "Could not start the trial. Please try again.",
          "bad",
        );
        button.disabled = false;
      }
    });
  }

  async function loadPlanUsage() {
    if (!$("[data-plan-usage-summary]")) return;
    bindPlanTrialControls();
    try {
      renderPlanUsage(await planServicesApi("usage"));
      renderPlanTrial(await planServicesApi("trial"));
    } catch (_) {
      const summary = $("[data-plan-usage-summary]");
      if (summary) summary.textContent = "Could not load usage.";
      setPlanUsageStatus("Sign in again to see plan usage.", "bad");
    }
  }

  // ---- Active account sessions ---------------------------------------------
  let accountSessionsLoaded = false;
  let accountSessionsLoading = null;

  function setAccountSessionStatus(message, kind = "") {
    const target = $("[data-account-session-status]");
    if (!target) return;
    target.textContent = message || "";
    target.className = "min-h-4 text-xs " + (
      kind === "bad" ? "text-destructive"
        : kind === "good" ? "text-success"
        : "text-muted-foreground"
    );
  }

  async function accountSessionApi(method, path = "") {
    const token = state.session?.sessionToken || "";
    if (!token) throw new Error("invalid_session");
    const response = await fetch("/api/accounts/sessions" + path, {
      method,
      headers: {
        accept: "application/json",
        authorization: "Bearer " + token,
      },
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      throw new Error(data.error || `http_${response.status}`);
    }
    return data;
  }

  function renderAccountSessions(data) {
    const list = $("[data-account-session-list]");
    if (!list) return;
    const sessions = Array.isArray(data?.sessions) ? data.sessions : [];
    if (!sessions.length) {
      list.innerHTML = accountBlankslate("monitor", "No active sessions were returned.");
      window.lucide?.createIcons();
      return;
    }
    list.innerHTML = sessions.map((session, index) => `
      <article class="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between ${index ? "border-t border-border" : ""}">
        <div class="min-w-0">
          <p class="text-sm font-semibold text-foreground">
            ${escapeHtml(session.deviceLabel || "Unknown device")}
            ${session.current ? '<span class="fm-label fm-label-accent ml-2">This device</span>' : ""}
          </p>
          <p class="mt-1 text-xs text-muted-foreground">${escapeHtml(String(session.ipAddress || "address unavailable"))} · last active ${escapeHtml(formatTimeAgo(Number(session.lastSeenAt || 0)))} · signed in ${escapeHtml(formatDate(Number(session.createdAt || 0)))} · expires ${escapeHtml(formatDate(Number(session.expiresAt || 0)))}</p>
        </div>
        <button type="button" data-account-session-revoke="${escapeHtml(session.id || "")}" data-account-session-current="${session.current ? "true" : "false"}" class="fm-btn fm-btn-sm fm-btn-danger shrink-0">
          ${session.current ? "Sign out here" : "Sign out"}
        </button>
      </article>`).join("");
  }

  // Coarse kinds only — the Worker stores when an account was emailed and
  // whether the provider accepted it, never the subject or body.
  const ACCOUNT_EMAIL_KIND_LABELS = {
    verification: "Email verification",
    password_reset: "Password reset",
    password_change: "Password change",
    feedback: "Founder feedback",
    notifications: "Notification digest",
    general_chat: "#general digest",
    admin_test: "Test email",
  };

  function renderAccountActivity(data) {
    const account = data?.account || {};
    const lastSeen = $("[data-account-last-seen]");
    if (lastSeen) {
      const seenAt = Number(account.lastSeenAt || 0);
      lastSeen.textContent = seenAt ? formatTimeAgo(seenAt) : "Never";
      lastSeen.title = seenAt ? formatDate(seenAt) : "";
    }
    const emailedAt = Number(account.lastEmailAt || 0);
    const lastEmail = $("[data-account-last-email]");
    if (lastEmail) {
      lastEmail.textContent = emailedAt ? formatTimeAgo(emailedAt) : "Never emailed";
      lastEmail.title = emailedAt ? formatDate(emailedAt) : "";
    }
    const detail = $("[data-account-last-email-detail]");
    if (detail) {
      const status = String(account.lastEmailStatus || "");
      const kind = ACCOUNT_EMAIL_KIND_LABELS[String(account.lastEmailKind || "")] || "Email";
      const sent = Number(account.emailSendCount || 0);
      detail.textContent = !emailedAt ? "" : kind + " · " + (
        status === "delivered" ? "Delivered to the mail provider"
          : status === "failed" ? "The mail provider rejected it"
            : "Delivery status unknown") + (
        sent > 0 ? ` · ${sent} email${sent === 1 ? "" : "s"} sent to this account` : "");
      detail.className = "mt-1 text-xs " + (
        status === "delivered" && emailedAt ? "text-muted-foreground"
          : status === "failed" && emailedAt ? "text-destructive"
            : "text-muted-foreground");
    }
  }

  function bindAccountSessionControls() {
    const list = $("[data-account-session-list]");
    if (list && list.dataset.controlsBound !== "true") {
      list.dataset.controlsBound = "true";
      list.addEventListener("click", (event) => {
        const button = event.target.closest("[data-account-session-revoke]");
        if (!button) return;
        revokeAccountSession(
          button.dataset.accountSessionRevoke || "",
          button.dataset.accountSessionCurrent === "true");
      });
    }
    const others = $("[data-account-sessions-revoke-others]");
    if (others && others.dataset.controlsBound !== "true") {
      others.dataset.controlsBound = "true";
      others.addEventListener("click", () => revokeOtherAccountSessions());
    }
    const all = $("[data-account-sessions-revoke-all]");
    if (all && all.dataset.controlsBound !== "true") {
      all.dataset.controlsBound = "true";
      all.addEventListener("click", () => revokeAllAccountSessions());
    }
  }

  async function loadAccountSessions({ force = false } = {}) {
    if (!$("[data-account-session-list]")) return;
    bindAccountSessionControls();
    if (accountSessionsLoaded && !force) return;
    if (accountSessionsLoading) return accountSessionsLoading;
    accountSessionsLoading = (async () => {
      try {
        const data = await accountSessionApi("GET");
        renderAccountSessions(data);
        renderAccountActivity(data);
        accountSessionsLoaded = true;
        setAccountSessionStatus(data.privacyNotice || "");
      } catch (error) {
        const list = $("[data-account-session-list]");
        if (list) {
          list.innerHTML = accountListError(error.message === "invalid_session" ? "Sign in to manage active sessions." : "Could not load active sessions.");
          window.lucide?.createIcons();
        }
      } finally {
        accountSessionsLoading = null;
      }
    })();
    return accountSessionsLoading;
  }

  async function revokeAccountSession(sessionId, current) {
    if (!sessionId || !await confirmAccountAction({
      title: current ? "Sign out this device now?" : "Sign out that device?",
      confirmLabel: "Sign out",
    })) return;
    try {
      const result = await accountSessionApi(
        "DELETE", "/" + encodeURIComponent(sessionId));
      if (current || result.currentRevoked) {
        logout();
        return;
      }
      accountSessionsLoaded = false;
      await loadAccountSessions({ force: true });
      setAccountSessionStatus("That device was signed out.", "good");
    } catch (_) {
      setAccountSessionStatus("Could not sign out that device.", "bad");
    }
  }

  async function revokeOtherAccountSessions() {
    if (!await confirmAccountAction({
      title: "Sign out every other active device?",
      body: "This browser stays signed in.",
      confirmLabel: "Sign out others",
    })) return;
    const button = $("[data-account-sessions-revoke-others]");
    if (button) button.disabled = true;
    try {
      await accountSessionApi("DELETE", "/others");
      accountSessionsLoaded = false;
      await loadAccountSessions({ force: true });
      setAccountSessionStatus("All other devices were signed out.", "good");
    } catch (_) {
      setAccountSessionStatus("Could not sign out the other devices.", "bad");
    } finally {
      if (button) button.disabled = false;
    }
  }

  // A sign-in lasts years, so a lost laptop or a shared browser needs one
  // action that ends every session, this browser included. The Worker revokes
  // them all; logout() then clears this browser and tells its other tabs.
  async function revokeAllAccountSessions() {
    if (!await confirmAccountAction({
      title: `Sign out of ${platformName()} on every device, including this one?`,
      confirmLabel: "Sign out everywhere",
    })) return;
    const button = $("[data-account-sessions-revoke-all]");
    if (button) button.disabled = true;
    try {
      await accountSessionApi("DELETE", "/all");
      logout();
    } catch (_) {
      if ($("[data-account-session-status]")) {
        setAccountSessionStatus("Could not sign out all devices.", "bad");
      } else {
        showErrorNotice("Could not sign out all devices. Please try again.");
      }
      if (button) button.disabled = false;
    }
  }

  let emailFooter = null;

  function setEmailFooterStatus(message, kind = "") {
    const target = $("[data-email-footer-status]");
    if (!target) return;
    target.textContent = message || "";
    target.className = "min-h-4 text-xs " + (kind === "bad" ? "text-destructive" : kind === "good" ? "text-success" : "text-muted-foreground");
  }

  function renderEmailFooter(data) {
    const preview = $("[data-email-footer-preview]");
    if (preview) preview.innerHTML = data.previewHtml || "";
    const opens = $("[data-email-footer-opens]");
    if (opens) {
      const count = Number(data.opens || 0);
      opens.textContent = count
        ? `Opened ${count.toLocaleString()} time${count === 1 ? "" : "s"}, last ${formatTimeAgo(data.lastOpenedAt)}.`
        : "Not opened yet.";
    }
    $$("[data-email-footer-copy], [data-email-footer-copy-html]").forEach((button) => {
      button.disabled = !data.html;
    });
  }

  async function copyEmailFooter(asHtml) {
    if (!emailFooter?.html) return;
    try {
      if (!asHtml && window.ClipboardItem && navigator.clipboard?.write) {
        await navigator.clipboard.write([new ClipboardItem({
          "text/html": new Blob([emailFooter.html], { type: "text/html" }),
          "text/plain": new Blob([`Sent with ${platformName()}`], { type: "text/plain" }),
        })]);
      } else {
        await navigator.clipboard.writeText(emailFooter.html);
      }
      setEmailFooterStatus(asHtml
        ? "HTML copied. Paste it into your signature's HTML view."
        : "Footer copied. Paste it into your mail app's signature.");
    } catch (_) {
      setEmailFooterStatus("Could not copy. Select the footer above and copy it.", "bad");
    }
  }

  async function loadEmailFooter() {
    const panel = $("[data-email-footer]");
    if (!panel) return;
    if (!panel.dataset.bound) {
      panel.dataset.bound = "true";
      $("[data-email-footer-copy]")?.addEventListener("click", () => copyEmailFooter(false));
      $("[data-email-footer-copy-html]")?.addEventListener("click", () => copyEmailFooter(true));
    }
    const token = state.session?.sessionToken || "";
    if (!token) {
      setEmailFooterStatus("Sign in to get your tracked footer.", "bad");
      return;
    }
    try {
      const response = await fetch("/api/mail/footer", {
        headers: { accept: "application/json", authorization: "Bearer " + token },
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.error || `http_${response.status}`);
      emailFooter = data;
      renderEmailFooter(data);
      setEmailFooterStatus("");
    } catch (_) {
      const preview = $("[data-email-footer-preview]");
      if (preview) preview.textContent = "";
      setEmailFooterStatus("Could not load your tracked footer.", "bad");
    }
  }

  // ---- Change password (issue #648) ----------------------------------------
  // Settings' other "Current password" boxes each CONFIRM some other action
  // (rename, payout, pings, claim, delete); this is the only one that sets a
  // new password, so a signed-in user no longer has to log out and wait for a
  // reset email. The Worker re-verifies the current password and signs every
  // other device out, so the sessions list above is refetched on success.
  const ACCOUNT_PASSWORD_MIN_LENGTH = 8;
  const ACCOUNT_PASSWORD_ERRORS = {
    email_not_verified: "Confirm your email address before changing your password.",
    invalid_credentials: "That current password is not right.",
    invalid_session: "Sign in again to change your password.",
    password_not_set: "This account signs in with a key, not a password.",
    password_too_short: `Use at least ${ACCOUNT_PASSWORD_MIN_LENGTH} characters.`,
    password_unchanged: "Choose a password different from your current one.",
    too_many_attempts: "Too many attempts. Wait a few minutes and try again.",
  };

  function setAccountPasswordStatus(message, kind = "") {
    const target = $("[data-account-password-status]");
    if (!target) return;
    target.textContent = message || "";
    target.className = "min-h-4 text-xs " + (
      kind === "bad" ? "text-destructive"
        : kind === "good" ? "text-success"
        : "text-muted-foreground"
    );
  }

  function accountPasswordFields() {
    return [
      $("[data-account-password-current]"),
      $("[data-account-password-new]"),
      $("[data-account-password-confirm]"),
    ];
  }

  function bindAccountPasswordControls() {
    const button = $("[data-account-password-save]");
    if (!button || button.dataset.controlsBound === "true") return;
    button.dataset.controlsBound = "true";
    button.addEventListener("click", () => changeAccountPassword());
    // The card's <form data-credential-scope> exists only to keep browser
    // password managers away from the page's search boxes; it never submits,
    // so Enter is wired by hand rather than leaving the keyboard path dead.
    accountPasswordFields().forEach((input) => {
      input?.addEventListener("keydown", (event) => {
        if (event.key !== "Enter") return;
        event.preventDefault();
        changeAccountPassword();
      });
    });
  }

  async function changeAccountPassword() {
    const [currentField, newField, confirmField] = accountPasswordFields();
    const currentPassword = currentField?.value || "";
    const newPassword = newField?.value || "";
    if (!currentPassword) {
      setAccountPasswordStatus("Enter your current password.", "bad");
      currentField?.focus();
      return;
    }
    if (newPassword.length < ACCOUNT_PASSWORD_MIN_LENGTH) {
      setAccountPasswordStatus(
        ACCOUNT_PASSWORD_ERRORS.password_too_short, "bad");
      newField?.focus();
      return;
    }
    if (newPassword !== (confirmField?.value || "")) {
      setAccountPasswordStatus("The new passwords do not match.", "bad");
      confirmField?.focus();
      return;
    }
    const button = $("[data-account-password-save]");
    if (button) { button.disabled = true; button.textContent = "Updating…"; }
    setAccountPasswordStatus("Updating password…");
    try {
      const token = state.session?.sessionToken || "";
      const response = await fetch("/api/accounts/change-password", {
        method: "POST",
        credentials: "same-origin",
        cache: "no-store",
        headers: {
          "content-type": "application/json",
          accept: "application/json",
          ...(token ? { authorization: "Bearer " + token } : {}),
        },
        body: JSON.stringify({ currentPassword, newPassword }),
      });
      const body = await response.json().catch(() => ({}));
      if (!response.ok || body.ok !== true) {
        throw new Error(body.error || `http_${response.status}`);
      }
      accountPasswordFields().forEach((input) => { if (input) input.value = ""; });
      // The Worker keeps this device signed in; the fallback only fires if it
      // could not tell which session made the change and cleared them all.
      if (body.currentRevoked) {
        logout();
        return;
      }
      setAccountPasswordStatus(
        "Password updated. Every other device was signed out.", "good");
      accountSessionsLoaded = false;
      await loadAccountSessions({ force: true });
    } catch (error) {
      setAccountPasswordStatus(
        ACCOUNT_PASSWORD_ERRORS[error.message]
          || "Could not update your password. Try again.", "bad");
    } finally {
      if (button) { button.disabled = false; button.textContent = "Update password"; }
    }
  }

  // ---- Nodes & devices (account_devices registry) ----------------------------
  // The web dashboard is the source of truth for every node key bound to the
  // account (desktop and mobile). Listing is session-gated like sessions; the
  // revoke routes are sudo-gated, so the browser re-collects the password (and
  // optional authenticator code) in an inline form before each call even while
  // a live session exists. Revoking a node signs out its sessions and makes its
  // owner-signed calls fail closed on the next request.
  let accountDevicesLoaded = false;
  let accountDevicesLoading = null;
  // The sudo action the inline re-auth form will run on submit:
  // { kind: "one", id, current } or { kind: "all" }.
  let accountDevicesPendingAction = null;

  const ACCOUNT_DEVICE_KIND_LABELS = {
    desktop_node: "Desktop node",
    mobile_node: "Mobile node",
    browser_control: "Browser desktop control",
    browser: "Browser",
    client: "Client",
  };
  // Short hints for the capability strings that change what a key may do on
  // the owner's behalf; the browse/comment/submit baseline is implied.
  const ACCOUNT_DEVICE_CAPABILITY_HINTS = [
    ["host_repo", "hosts"],
    ["mirror_repo", "mirrors"],
    ["publish_repo", "publishes"],
    ["owner_sign", "signs as owner"],
    ["desktop_control", "controls your desktop's agents"],
  ];

  function accountDeviceKindLabel(kind) {
    const key = String(kind || "").trim();
    if (ACCOUNT_DEVICE_KIND_LABELS[key]) return ACCOUNT_DEVICE_KIND_LABELS[key];
    return key ? key.replace(/[_-]+/g, " ").replace(/^\w/, (c) => c.toUpperCase()) : "Device";
  }

  function accountDeviceCapabilityHint(device) {
    const caps = Array.isArray(device?.capabilities) ? device.capabilities.map(String) : [];
    const hints = ACCOUNT_DEVICE_CAPABILITY_HINTS
      .filter(([cap]) => caps.includes(cap))
      .map(([, hint]) => hint);
    if (hints.length) return hints.join(" · ");
    const kind = String(device?.kind || "");
    if (kind === "mobile_node") return "publishes · signs as owner";
    if (kind === "desktop_node") return "hosts · publishes";
    return "";
  }

  function setAccountDevicesStatus(message, kind = "") {
    const target = $("[data-account-devices-status]");
    if (!target) return;
    target.textContent = message || "";
    target.className = "min-h-4 text-xs " + (
      kind === "bad" ? "text-destructive"
        : kind === "good" ? "text-success"
        : "text-muted-foreground"
    );
  }

  async function accountDeviceApi(method, path = "", body) {
    const token = state.session?.sessionToken || "";
    if (!token) throw new Error("invalid_session");
    const headers = {
      accept: "application/json",
      authorization: "Bearer " + token,
    };
    if (body !== undefined) headers["content-type"] = "application/json";
    const response = await fetch("/api/accounts/devices" + path, {
      method,
      headers,
      cache: "no-store",
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      throw new Error(data.error || `http_${response.status}`);
    }
    return data;
  }

  function renderAccountDevices(data) {
    const list = $("[data-account-devices-list]");
    if (!list) return;
    const devices = Array.isArray(data?.devices) ? data.devices : [];
    if (!devices.length) {
      list.innerHTML = accountBlankslate("laptop", "No nodes or devices are bound to this account yet.");
      window.lucide?.createIcons();
      return;
    }
    list.innerHTML = devices.map((device, index) => {
      const enabled = device.enabled !== false && !device.revokedAt;
      const lastSeen = Number(device.lastSeen || 0);
      const created = Number(device.createdAt || 0);
      const hint = accountDeviceCapabilityHint(device);
      const meta = [
        enabled
          ? "last seen " + (lastSeen ? formatTimeAgo(lastSeen) : "never")
          : "revoked " + formatDate(Number(device.revokedAt || 0)),
        created ? "added " + formatDate(created) : "",
        hint,
      ].filter(Boolean).join(" · ");
      const control = !enabled
        ? '<span class="fm-label shrink-0">Revoked</span>'
        : device.current
          ? '<span class="fm-label fm-label-accent shrink-0">This device</span>'
          : `<button type="button" data-account-device-revoke="${escapeHtml(device.id || "")}" class="fm-btn fm-btn-sm fm-btn-danger shrink-0">Revoke</button>`;
      return `
      <article data-account-device-row="${escapeHtml(device.id || "")}" class="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between ${index ? "border-t border-border" : ""} ${enabled ? "" : "opacity-60"}">
        <div class="min-w-0">
          <p class="flex flex-wrap items-center gap-2 text-sm font-semibold text-foreground">
            <span class="fm-label">${escapeHtml(accountDeviceKindLabel(device.kind))}</span>
            <span class="truncate">${escapeHtml(device.label || "Unnamed device")}</span>
            ${device.current ? '<span class="fm-label fm-label-accent">This device</span>' : ""}
          </p>
          <p class="mt-1 text-xs text-muted-foreground">${escapeHtml(meta)}</p>
          ${device.id ? `<p class="mt-1 text-[11px] text-muted-foreground">Device ID <span data-account-device-id class="break-all font-mono text-foreground select-all">${escapeHtml(device.id)}</span></p>` : ""}
        </div>
        ${control}
      </article>`;
    }).join("");
  }

  function accountDevicesReauthForm() {
    return $("[data-account-devices-reauth]");
  }

  function openAccountDevicesReauth(action) {
    const form = accountDevicesReauthForm();
    if (!form) return;
    accountDevicesPendingAction = action;
    const title = $("[data-account-devices-reauth-title]");
    if (title) {
      title.textContent = action.kind === "all"
        ? "Sign out all other nodes?"
        : "Revoke " + (action.label || "this node") + "?";
    }
    const confirm = $("[data-account-devices-reauth-confirm]");
    if (confirm) {
      confirm.textContent = action.kind === "all" ? "Sign out other nodes" : "Revoke node";
      confirm.disabled = false;
    }
    const password = $("[data-account-devices-reauth-password]");
    const totp = $("[data-account-devices-reauth-totp]");
    if (password) password.value = "";
    if (totp) totp.value = "";
    form.hidden = false;
    setAccountDevicesStatus("");
    password?.focus();
  }

  function closeAccountDevicesReauth() {
    const form = accountDevicesReauthForm();
    accountDevicesPendingAction = null;
    if (!form) return;
    form.hidden = true;
    const password = $("[data-account-devices-reauth-password]");
    const totp = $("[data-account-devices-reauth-totp]");
    if (password) password.value = "";
    if (totp) totp.value = "";
  }

  function accountDevicesReauthBody() {
    const password = String($("[data-account-devices-reauth-password]")?.value || "");
    const totp = String($("[data-account-devices-reauth-totp]")?.value || "").replace(/\s+/g, "");
    const body = { password };
    if (totp) body.totp = totp;
    return body;
  }

  function accountDevicesErrorText(error, fallback) {
    const code = String(error?.message || "");
    if (code === "reauth_required" || code === "invalid_password" || code === "invalid_totp") {
      return "Password or authenticator code was not accepted. Try again.";
    }
    if (code === "invalid_session") return "Sign in again to manage nodes and devices.";
    if (code === "not_found") return "That node was already removed.";
    return fallback;
  }

  async function submitAccountDevicesReauth() {
    const action = accountDevicesPendingAction;
    if (!action) return;
    const body = accountDevicesReauthBody();
    if (!body.password) {
      setAccountDevicesStatus("Enter your current password to continue.", "bad");
      $("[data-account-devices-reauth-password]")?.focus();
      return;
    }
    const confirm = $("[data-account-devices-reauth-confirm]");
    if (confirm) confirm.disabled = true;
    setAccountDevicesStatus(action.kind === "all" ? "Signing out other nodes…" : "Revoking node…");
    try {
      if (action.kind === "all") {
        const result = await accountDeviceApi("POST", "/revoke-all", body);
        closeAccountDevicesReauth();
        accountDevicesLoaded = false;
        accountSessionsLoaded = false;
        await Promise.all([
          loadAccountDevices({ force: true }),
          loadAccountSessions({ force: true }),
        ]);
        const count = Number(result?.revokedDevices || 0);
        setAccountDevicesStatus(
          count ? `${count} other node${count === 1 ? " was" : "s were"} signed out.` : "No other nodes needed signing out.",
          "good");
      } else {
        const result = await accountDeviceApi(
          "DELETE", "/" + encodeURIComponent(action.id), body);
        closeAccountDevicesReauth();
        if (action.current || result?.currentRevoked) {
          // Revoking the node bound to this session invalidates it too.
          logout();
          return;
        }
        accountDevicesLoaded = false;
        accountSessionsLoaded = false;
        await Promise.all([
          loadAccountDevices({ force: true }),
          loadAccountSessions({ force: true }),
        ]);
        setAccountDevicesStatus("That node was revoked and signed out.", "good");
      }
    } catch (error) {
      setAccountDevicesStatus(accountDevicesErrorText(
        error,
        action.kind === "all" ? "Could not sign out the other nodes." : "Could not revoke that node."), "bad");
      if (confirm) confirm.disabled = false;
    }
  }

  function bindAccountDevicesControls() {
    const list = $("[data-account-devices-list]");
    if (list && list.dataset.controlsBound !== "true") {
      list.dataset.controlsBound = "true";
      list.addEventListener("click", (event) => {
        const button = event.target.closest("[data-account-device-revoke]");
        if (!button) return;
        const row = button.closest("[data-account-device-row]");
        const label = row?.querySelector(".truncate")?.textContent?.trim() || "";
        openAccountDevicesReauth({
          kind: "one",
          id: button.dataset.accountDeviceRevoke || "",
          label,
          current: false,
        });
      });
    }
    const others = $("[data-account-devices-revoke-others]");
    if (others && others.dataset.controlsBound !== "true") {
      others.dataset.controlsBound = "true";
      others.addEventListener("click", () => openAccountDevicesReauth({ kind: "all" }));
    }
    const form = accountDevicesReauthForm();
    if (form && form.dataset.controlsBound !== "true") {
      form.dataset.controlsBound = "true";
      form.addEventListener("submit", (event) => {
        event.preventDefault();
        submitAccountDevicesReauth();
      });
      $("[data-account-devices-reauth-cancel]")?.addEventListener("click", () => {
        closeAccountDevicesReauth();
        setAccountDevicesStatus("");
      });
    }
  }

  async function loadAccountDevices({ force = false } = {}) {
    if (!$("[data-account-devices-list]")) return;
    bindAccountDevicesControls();
    if (accountDevicesLoaded && !force) return;
    if (accountDevicesLoading) return accountDevicesLoading;
    accountDevicesLoading = (async () => {
      try {
        const data = await accountDeviceApi("GET");
        renderAccountDevices(data);
        accountDevicesLoaded = true;
      } catch (error) {
        const list = $("[data-account-devices-list]");
        if (list) {
          list.innerHTML = accountListError(error.message === "invalid_session" ? "Sign in to manage nodes and devices." : "Could not load nodes and devices.");
          window.lucide?.createIcons();
        }
      } finally {
        accountDevicesLoading = null;
      }
    })();
    return accountDevicesLoading;
  }

  // ---- SSH public keys (settings tab) ---------------------------------------
  // Public keys are account-scoped and encrypted at rest by the Worker. The
  // browser never handles a private key; every push is authorized again by the
  // Worker and executed by a separately operated node-side SSH gateway.
  let sshKeysLoaded = false;
  let sshKeysLoading = null;

  function setSshKeyStatus(message, kind = "") {
    const target = $("[data-ssh-key-status]");
    if (!target) return;
    target.textContent = message || "";
    target.className = "min-h-4 text-xs " + (
      kind === "bad" ? "text-destructive"
        : kind === "good" ? "text-success"
        : "text-muted-foreground"
    );
  }

  async function sshKeyApi(method, path = "", body) {
    const token = state.session?.sessionToken || "";
    if (!token) throw new Error("invalid_session");
    const headers = {
      accept: "application/json",
      authorization: "Bearer " + token,
    };
    if (body !== undefined) headers["content-type"] = "application/json";
    const response = await fetch("/api/accounts/ssh-keys" + path, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      throw new Error(data.error || `http_${response.status}`);
    }
    return data;
  }

  let gitPushWired = false;

  function setGitPushStatus(message, kind = "") {
    const target = $("[data-git-push-status]");
    if (!target) return;
    target.textContent = message || "";
    target.className = "min-h-4 text-xs " + (
      kind === "bad" ? "text-destructive"
        : kind === "good" ? "text-success"
        : "text-muted-foreground"
    );
  }

  async function loadGitPushSettings() {
    const note = $("[data-git-push-contributor]");
    const input = $("[data-git-push-repo]");
    try {
      const response = await fetch("/api/hosted-repositories", { headers: { accept: "application/json" } });
      const data = await response.json().catch(() => ({}));
      const listed = (Array.isArray(data?.contributorPush) ? data.contributorPush : [])
        .filter((item) => /^[^*/\s]+\/[^*/\s]+$/.test(String(item)));
      const account = String(state.session?.nodeName || state.session?.name || "").toLowerCase();
      if (note && listed.length) {
        note.textContent = `To contribute, Fork the repository from its page (Forks, then Fork this repository), push any branch to your fork with a credential for it, and open a pull request back. Without a fork, anyone with a verified email address can also push branches named pr/${account || "<your-name>"}/… to ${listed.join(", ")} directly. Other branches stay with the owners.`;
        note.classList.remove("hidden");
      }
      if (input && !input.value && listed.length) input.value = listed[0];
    } catch (_) {
    }
  }

  function renderGitPushGrant(push) {
    const target = $("[data-git-push-result]");
    if (!target) return;
    const contributor = push?.access === "contributor";
    const expires = Number(push?.expiresAt || 0);
    const field = (label, value, attr) => `
      <label class="grid gap-1 text-xs font-semibold text-foreground">${escapeHtml(label)}
        <input ${attr} type="text" readonly value="${escapeHtml(value || "")}" class="h-9 rounded-md border border-border bg-secondary px-2 font-mono text-xs font-normal text-foreground" />
      </label>`;
    const commands = (Array.isArray(push?.commands) ? push.commands : []).join("\n");
    target.innerHTML = `
      ${field("Remote URL", push?.remoteUrl, "data-git-push-remote")}
      ${field("Username", push?.username, "data-git-push-username")}
      ${field("Password (shown once; copy it now)", push?.password, "data-git-push-password")}
      <p class="text-xs text-muted-foreground">${contributor
        ? `You can push only branches named <span class="font-mono">${escapeHtml(push.branchPrefix || "")}…</span>. Pushes are fast-forward only: add commits instead of force-pushing, or push a new branch name. Then open a pull request from that branch on the repository's Pull requests tab.`
        : "You have write access to this repository; its branch protection still applies."}
        ${expires ? ` Expires ${escapeHtml(formatDate(expires))}.` : ""}</p>
      <pre class="overflow-x-auto rounded-md border border-border bg-secondary p-3 font-mono text-xs text-foreground">${escapeHtml(commands)}</pre>`;
    target.classList.remove("hidden");
  }

  async function mintGitPushCredential() {
    const raw = String($("[data-git-push-repo]")?.value || "").trim().replace(/^https?:\/\/[^/]+\//, "").replace(/\.git$/, "");
    const [owner, name, extra] = raw.split("/");
    if (!owner || !name || extra !== undefined) {
      setGitPushStatus("Enter the repository as owner/repository.", "bad");
      return;
    }
    const token = state.session?.sessionToken || "";
    if (!token) {
      setGitPushStatus("Sign in to create a push credential.", "bad");
      return;
    }
    const button = $("[data-git-push-mint]");
    if (button) button.disabled = true;
    setGitPushStatus("Creating a push credential…");
    try {
      const response = await fetch("/api/hosted-repositories/push-credential", {
        method: "POST",
        headers: { accept: "application/json", "content-type": "application/json" },
        body: JSON.stringify({ owner, name, sessionToken: token }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.push) {
        const messages = {
          unauthorized: "Sign in to create a push credential.",
          session_required: "Sign in again in this browser to create a push credential.",
          hosted_git_unavailable: "This server cannot accept pushes right now.",
        };
        setGitPushStatus(data.message || messages[data.error] || "A push credential could not be created.", "bad");
        return;
      }
      setGitPushStatus(data.push.access === "contributor" ? "Contributor push credential created." : "Push credential created.", "good");
      renderGitPushGrant(data.push);
    } catch (_) {
      setGitPushStatus("A push credential could not be created.", "bad");
    } finally {
      if (button) button.disabled = false;
    }
  }

  function wireGitPushPanel() {
    if (gitPushWired || !$("[data-git-push-panel]")) return;
    gitPushWired = true;
    $("[data-git-push-mint]")?.addEventListener("click", () => mintGitPushCredential());
    $("[data-git-push-repo]")?.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        mintGitPushCredential();
      }
    });
    loadGitPushSettings();
  }

  // How to use a key, shown once the server has an SSH gateway. The HTTPS
  // push credential above stays the fallback for networks that block SSH.
  function renderSshUsePanel(data) {
    const panel = $("[data-ssh-use-panel]");
    const steps = $("[data-ssh-use-steps]");
    if (!panel || !steps) return;
    const host = String(data?.gatewayHost || "");
    if (!data?.gatewayConfigured || !host) {
      panel.classList.add("hidden");
      return;
    }
    const port = Number(data.gatewayPort) || 22;
    const example = String(data.gatewayExampleUrl || "");
    const login = port === 22 ? `ssh -T git@${host}` : `ssh -T -p ${port} git@${host}`;
    const account = String(data.account || "<you>");
    const code = (value) => `<code class="mt-1 block overflow-x-auto rounded-md border border-border bg-secondary px-2 py-1 font-mono text-xs text-foreground">${escapeHtml(value)}</code>`;
    const items = [
      ["Create a key if you do not have one, on your own computer:", code('ssh-keygen -t ed25519 -C "you@example.com"')],
      ["Paste the public half (the .pub file) below and select <strong>Add SSH key</strong>:", code("cat ~/.ssh/id_ed25519.pub")],
      ["Check the connection. It prints a greeting; there is no shell:", code(login)],
      ["Clone with the SSH address from a repository's <strong>Code</strong> button, or switch an existing clone:", code(`git clone ${example}`) + code(`git remote set-url origin ${example}`)],
    ];
    if (data.gatewayAllRepositories) {
      items.push(["Contributing without write access: fork the repository and push to your fork, or, where the repository accepts contributor branches, push one named pr/" + escapeHtml(account) + "/&lt;topic&gt; and open a pull request:", code(`git push origin HEAD:pr/${account}/my-fix`)]);
    }
    steps.innerHTML = items.map(([text, body], index) => `
      <li class="grid gap-1"><span><span class="font-semibold text-foreground">${index + 1}.</span> ${text}</span>${body}</li>`).join("");
    panel.classList.remove("hidden");
  }

  function renderSshKeys(data) {
    const list = $("[data-ssh-key-list]");
    if (!list) return;
    const keys = Array.isArray(data?.keys) ? data.keys : [];
    const gateway = $("[data-ssh-gateway-status]");
    if (gateway) {
      gateway.textContent = data?.gatewayConfigured
        ? `SSH gateway: ${data.gatewayHost}${Number(data.gatewayPort) === 22 ? "" : `:${data.gatewayPort}`}`
        : "SSH pushes are not available on this server. Push over HTTPS with a push credential instead.";
    }
    renderSshUsePanel(data);
    if (!keys.length) {
      list.innerHTML = accountBlankslate("key-round", "No SSH keys registered.", "Add a public key above to clone and push over SSH.");
      window.lucide?.createIcons();
      return;
    }
    list.innerHTML = keys.map((key, index) => {
      const used = Number(key.lastUsedAt || 0);
      return `
        <article class="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between ${index ? "border-t border-border" : ""}">
          <div class="min-w-0">
            <p class="truncate text-sm font-semibold text-foreground">${escapeHtml(key.label || "SSH key")}</p>
            <p class="mt-1 break-all font-mono text-xs text-muted-foreground">${escapeHtml(key.fingerprint || "")}</p>
            <p class="mt-1 text-xs text-muted-foreground">${escapeHtml(key.keyType || "SSH")} · added ${escapeHtml(formatDate(key.createdAt))}${used ? ` · last used ${escapeHtml(formatTimeAgo(used))}` : " · never used"}</p>
          </div>
          <button type="button" data-ssh-key-revoke="${escapeHtml(key.id || "")}" class="fm-btn fm-btn-sm fm-btn-danger shrink-0">
            Revoke
          </button>
        </article>`;
    }).join("");
  }

  async function loadSshKeys({ force = false } = {}) {
    wireGitPushPanel();
    if (!$("[data-ssh-key-list]")) return;
    if (sshKeysLoaded && !force) return;
    if (sshKeysLoading) return sshKeysLoading;
    sshKeysLoading = (async () => {
      try {
        const data = await sshKeyApi("GET");
        renderSshKeys(data);
        sshKeysLoaded = true;
      } catch (error) {
        const list = $("[data-ssh-key-list]");
        if (list) {
          list.innerHTML = accountListError(error.message === "invalid_session" ? "Sign in to manage SSH keys." : "Could not load SSH keys.");
          window.lucide?.createIcons();
        }
      } finally {
        sshKeysLoading = null;
      }
    })();
    return sshKeysLoading;
  }

  async function addSshKey() {
    const publicKey = ($("[data-ssh-public-key]")?.value || "").trim();
    const label = ($("[data-ssh-key-label]")?.value || "").trim();
    if (!publicKey) {
      setSshKeyStatus("Paste one OpenSSH public key.", "bad");
      return;
    }
    const button = $("[data-ssh-key-add]");
    if (button) {
      button.disabled = true;
      button.textContent = "Adding…";
    }
    try {
      await sshKeyApi("POST", "", { publicKey, label });
      if ($("[data-ssh-public-key]")) $("[data-ssh-public-key]").value = "";
      if ($("[data-ssh-key-label]")) $("[data-ssh-key-label]").value = "";
      setSshKeyStatus("SSH public key registered.", "good");
      sshKeysLoaded = false;
      await loadSshKeys({ force: true });
    } catch (error) {
      const messages = {
        unsupported_key_type: "Use an Ed25519, ECDSA, security-key, or RSA (3072-bit or stronger) public key.",
        rsa_key_too_small: "RSA keys must be at least 3072 bits.",
        ssh_key_already_registered: "That public key is already registered or was previously revoked. Use a fresh keypair.",
        ssh_key_limit_reached: "Revoke an unused key before adding another.",
        one_public_key_required: "Paste exactly one public key.",
        invalid_session: "Sign in to manage SSH keys.",
      };
      setSshKeyStatus(messages[error.message] || "That SSH public key could not be registered.", "bad");
    } finally {
      if (button) {
        button.disabled = false;
        button.textContent = "Add SSH key";
      }
    }
  }

  async function revokeSshKey(keyId) {
    if (!keyId || !await confirmAccountAction({
      title: "Revoke this SSH key?",
      body: "It will stop authenticating immediately.",
      confirmLabel: "Revoke key",
    })) return;
    try {
      await sshKeyApi("DELETE", "/" + encodeURIComponent(keyId));
      setSshKeyStatus("SSH key revoked.", "good");
      sshKeysLoaded = false;
      await loadSshKeys({ force: true });
    } catch (_) {
      setSshKeyStatus("Could not revoke that SSH key.", "bad");
    }
  }

  // ---- Organizations (settings tab) -----------------------------------------
  // Client for the /api/orgs endpoints:
  // list/create the orgs you belong to, then a master/detail panel to manage
  // one org's members, teams, and linked repos. All rendered lazily into
  // [data-orgs-root] the first time the Organizations settings tab is opened.
  // Mirrors ORG_ROLES in the Worker (organization_rbac.py, strongest first).
  // The server decides what each role may do; only owners can hand out
  // owner/admin, and the members API refuses anything the matrix denies.
  const ORG_ROLE_OPTIONS = ["owner", "admin", "maintainer", "member", "auditor", "guest"];
  const ORG_TEAM_PERMISSIONS = ["read", "write", "maintain", "admin"];
  const ORG_WORLD_ACCESS_OPTIONS = ["public", "restricted", "private"];
  // Keep these aliases aligned with world-office-tower.js and the Worker's
  // OFFICE_FLOOR_TEAM_ALIASES. The server remains authoritative for elevator
  // access; this organization-admin matrix explains every floor group a user
  // can belong to and highlights access granted by their current teams.
  const ORG_OFFICE_FLOOR_GROUPS = Object.freeze([
    { id: "marketing", label: "Marketing", aliases: ["marketing", "marketing-team", "growth", "brand", "comms", "communications"] },
    { id: "engineering", label: "Engineering", aliases: ["engineering", "engineers", "development", "developers", "platform", "frontend", "backend"] },
    { id: "infrastructure", label: "Infrastructure", aliases: ["infrastructure", "infra", "devops", "site-reliability", "sre"] },
  ]);

  // Worker org-endpoint error codes -> human text. Unknown codes fall through
  // to a generic message so the UI never shows a raw slug.
  const ORG_ERROR_TEXT = {
    invalid_org_name: "Invalid name. Use lowercase letters, numbers and dashes.",
    invalid_team_name: "Invalid team name. Use lowercase letters, numbers and dashes.",
    org_name_taken: "That name is already taken.",
    too_many_orgs: "You have reached the organization limit for this account.",
    too_many_members: "This organization has reached its member limit.",
    too_many_teams: "This organization has reached its team limit.",
    too_many_repos: "This organization has reached its linked-repo limit.",
    invalid_session: "Sign in to manage organizations.",
    forbidden: "You do not have permission to do that.",
    not_found: "Not found.",
    last_owner: "An organization must keep at least one owner.",
    unknown_account: "No account exists with that name.",
    not_a_member: "That account is not a member of this organization.",
    bad_role: "Invalid role.",
    bad_permission: "Invalid permission.",
    member_required: "Enter a member account name.",
    repo_required: "Enter a repository name.",
    not_your_node: "You can only link repositories from your own node.",
    unknown_repo: "That repository is not published on your node.",
    enabled_required: "Choose whether organization digests are enabled.",
    invalid_logo_url: "Logo URLs must use HTTPS and cannot contain credentials or fragments.",
    invalid_world_access: "Choose a valid access level for every organization space.",
    invalid_provider: "Choose Codex or Claude Code.",
    invalid_bot_permissions: "Choose at least one valid bot permission.",
    invalid_expiration: "Bot tokens may expire in 1–365 days.",
    too_many_bot_tokens: "This organization has reached its active bot-token limit.",
    invalid_token_id: "That bot token is invalid.",
  };

  function orgErrorText(code) {
    return ORG_ERROR_TEXT[code] || (code ? "Request failed (" + code + ")." : "Request failed.");
  }

  // fetchJson only does cached GETs; org writes need POST/DELETE with the
  // session bearer token and must surface the structured {error} body, so they
  // go through this dedicated helper instead.
  async function orgApiRequest(method, path, body) {
    const token = state.session?.sessionToken || "";
    const headers = { accept: "application/json" };
    if (body !== undefined) headers["content-type"] = "application/json";
    if (token) headers.authorization = "Bearer " + token;
    const response = await fetch(path, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data.ok === false) {
      const error = new Error(orgErrorText(data.error || ""));
      error.code = data.error || "http_" + response.status;
      error.data = data;
      throw error;
    }
    return data;
  }

  function orgsRoot() {
    return $("[data-orgs-root]");
  }

  let orgsSectionLoaded = false;
  function initOrgsSection() {
    if (orgsSectionLoaded) return;
    orgsSectionLoaded = true;
    showOrgsList();
  }

  function orgSignedIn() {
    return Boolean(state.session?.nodeName) && state.session?.kind !== "preview";
  }

  function orgRoleBadge(role) {
    const clean = String(role || "member").toLowerCase();
    const tone = clean === "owner"
      ? " fm-label-accent"
      : clean === "admin"
        ? " fm-label-attention"
        : clean === "guest"
          ? " border-dashed"
          : "";
    return '<span class="fm-label' + tone + '">' + escapeHtml(clean) + "</span>";
  }

  function orgMemberFloorGroups(member, canManage) {
    const teams = new Set(
      (Array.isArray(member?.teams) ? member.teams : [])
        .map((team) => String(team || "").trim().toLowerCase())
        .filter(Boolean),
    );
    const groups = ORG_OFFICE_FLOOR_GROUPS.map((group) => {
      const matchingTeams = group.aliases.filter((team) => teams.has(team));
      const active = matchingTeams.length > 0;
      const state = active ? "In group" : "Available";
      const title = active
        ? "Remove from " + group.label + " (" + matchingTeams.join(", ") + ")"
        : "Add to " + group.label;
      const tag = canManage ? "button" : "span";
      const controls = canManage
        ? ' type="button" data-org-member-floor-group="' + escapeHtml(group.id) +
          '" data-org-member="' + escapeHtml(member?.name || "") +
          '" aria-pressed="' + (active ? "true" : "false") + '"'
        : "";
      return "<" + tag + controls + ' title="' + escapeHtml(title) + '" aria-label="' +
        escapeHtml(group.label + ": " + state) + '" class="inline-flex items-center gap-1 rounded-full border px-2 py-1 text-[11px] font-semibold transition-colors ' +
        (active
          ? "border-border bg-secondary text-foreground"
          : "border-border bg-background text-muted-foreground") +
        (canManage
          ? " cursor-pointer hover:border-primary/70 hover:bg-primary/10 hover:text-primary disabled:cursor-wait disabled:opacity-60"
          : "") + '">' +
        '<span aria-hidden="true" class="h-1.5 w-1.5 rounded-full ' +
        (active ? "bg-foreground" : "bg-muted-foreground/40") + '"></span>' +
        escapeHtml(group.label) + "</" + tag + ">";
    }).join("");
    const activeCount = ORG_OFFICE_FLOOR_GROUPS.filter(
      (group) => group.aliases.some((team) => teams.has(team)),
    ).length;
    return '<div data-org-member-floor-groups class="mt-2 border-t border-border/70 pt-2">' +
      '<div class="mb-1.5 flex items-center justify-between gap-2 text-[11px] text-muted-foreground">' +
        '<span class="font-semibold text-foreground">Office floor groups</span>' +
        '<span>' + activeCount + " of " + ORG_OFFICE_FLOOR_GROUPS.length + " active</span>" +
      '</div><div class="flex flex-wrap gap-1.5">' + groups + "</div></div>";
  }

  function orgOptionTags(options, selected) {
    return options.map((opt) =>
      '<option value="' + escapeHtml(opt) + '"' + (opt === selected ? " selected" : "") + ">" +
      escapeHtml(opt) + "</option>").join("");
  }

  function orgStatus(root, message, ok) {
    const status = root.querySelector("[data-org-status]");
    if (!status) return;
    status.textContent = message || "";
    status.className = "min-h-4 text-xs " + (ok ? "text-muted-foreground" : "text-destructive");
  }

  const ORG_INPUT_CLASS = "h-10 rounded-md border border-border bg-card px-3 text-sm font-normal " +
    "text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-primary";
  const ORG_BTN_PRIMARY = "fm-btn fm-btn-cta";
  const ORG_BTN_SECONDARY = "fm-btn";

  async function showOrgsList() {
    const root = orgsRoot();
    if (!root) return;
    if (!orgSignedIn()) {
      root.innerHTML = '<p class="text-sm text-muted-foreground">Sign in to create and manage organizations.</p>';
      return;
    }
    root.innerHTML = '<p class="text-sm text-muted-foreground">' + loadingHtml("Loading organizations…") + "</p>";
    let orgs = [];
    try {
      const data = await orgApiRequest("GET", "/api/orgs");
      orgs = Array.isArray(data.orgs) ? data.orgs : [];
    } catch (error) {
      root.innerHTML = '<p class="text-sm text-destructive">' + escapeHtml(error.message) + "</p>";
      return;
    }
    const rows = orgs.length
      ? orgs.map((org) => {
          const name = escapeHtml(org.name || "");
          return '<button type="button" data-org-open="' + name + '" ' +
            'class="flex w-full items-center gap-3 px-4 py-3 text-left hover:bg-secondary transition-colors">' +
            '<i data-lucide="building-2" class="h-4 w-4 text-muted-foreground"></i>' +
            '<span class="min-w-0 flex-1 truncate text-sm font-semibold text-foreground">' + name + "</span>" +
            orgRoleBadge(org.role) +
            '<i data-lucide="chevron-right" class="h-4 w-4 text-muted-foreground"></i>' +
            "</button>";
        }).join("")
      : accountBlankslate("building-2", "No organizations yet.", "Create one below.");
    root.innerHTML =
      '<div class="divide-y divide-border overflow-hidden rounded-md border border-border bg-card">' + rows + "</div>" +
      '<form data-org-create class="mt-6 grid max-w-md gap-3 border-t border-border pt-6">' +
        '<h3 class="text-sm font-semibold text-foreground">New organization</h3>' +
        '<input data-org-name required placeholder="name (lowercase, dashes)" autocomplete="off" class="' + ORG_INPUT_CLASS + '" />' +
        '<input data-org-display placeholder="Display name (optional)" autocomplete="off" class="' + ORG_INPUT_CLASS + '" />' +
        '<input data-org-description placeholder="Description (optional)" autocomplete="off" class="' + ORG_INPUT_CLASS + '" />' +
        '<p data-org-status class="min-h-4 text-xs text-muted-foreground"></p>' +
        '<button type="submit" class="' + ORG_BTN_PRIMARY + ' w-fit">Create organization</button>' +
      "</form>";
    window.lucide?.createIcons();
    root.querySelector("[data-org-create]")?.addEventListener("submit", onCreateOrgSubmit);
    root.querySelectorAll("[data-org-open]").forEach((button) => {
      button.addEventListener("click", () => showOrgDetail(button.dataset.orgOpen));
    });
  }

  async function onCreateOrgSubmit(event) {
    event.preventDefault();
    const root = orgsRoot();
    if (!root) return;
    const name = (root.querySelector("[data-org-name]")?.value || "").trim().toLowerCase();
    if (!name) {
      orgStatus(root, "Enter an organization name.", false);
      return;
    }
    const body = { name };
    const display = (root.querySelector("[data-org-display]")?.value || "").trim();
    const description = (root.querySelector("[data-org-description]")?.value || "").trim();
    if (display) body.displayName = display;
    if (description) body.description = description;
    orgStatus(root, "Creating…", true);
    try {
      const created = await orgApiRequest("POST", "/api/orgs", body);
      showOrgDetail(created.org || name);
    } catch (error) {
      orgStatus(root, error.message, false);
    }
  }

  async function showOrgDetail(name) {
    const root = orgsRoot();
    if (!root || !name) return;
    root.innerHTML = '<p class="text-sm text-muted-foreground">' + loadingHtml("Loading organization…") + "</p>";
    let profile;
    let members = [];
    let teams = [];
    let repos = [];
    let fediverse = { controls: { enabled: true }, repos: [] };
    let botTokens = { permissions: [], tokens: [], usagePreview: [] };
    try {
      const [profileData, membersData, teamsData, reposData] = await Promise.all([
        orgApiRequest("GET", "/api/orgs/" + encodeURIComponent(name)),
        orgApiRequest("GET", "/api/orgs/" + encodeURIComponent(name) + "/members"),
        orgApiRequest("GET", "/api/orgs/" + encodeURIComponent(name) + "/teams").catch(() => ({ teams: [] })),
        orgApiRequest("GET", "/api/orgs/" + encodeURIComponent(name) + "/repos"),
      ]);
      profile = profileData;
      members = membersData.members || [];
      teams = teamsData.teams || [];
      repos = reposData.repos || [];
      if (profile.viewerRole === "owner" || profile.viewerRole === "admin") {
        [fediverse, botTokens] = await Promise.all([
          orgApiRequest(
            "GET", "/api/orgs/" + encodeURIComponent(name) + "/fediverse"),
          orgApiRequest(
            "GET", "/api/orgs/" + encodeURIComponent(name) + "/bot-tokens"),
        ]);
      }
    } catch (error) {
      root.innerHTML =
        '<button type="button" data-org-back class="mb-4 inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">' +
        '<i data-lucide="arrow-left" class="h-4 w-4"></i> Back</button>' +
        '<p class="text-sm text-destructive">' + escapeHtml(error.message) + "</p>";
      window.lucide?.createIcons();
      root.querySelector("[data-org-back]")?.addEventListener("click", showOrgsList);
      return;
    }
    renderOrgDetail(
      root, name, profile, members, teams, repos, fediverse, botTokens);
    void loadOrgPullRules(root, name);
  }

  async function loadOrgPullRules(root, name) {
    const holder = root.querySelector("[data-org-pull-rules]");
    if (!holder) return;
    let data;
    try {
      data = await orgApiRequest(
        "GET", "/api/orgs/" + encodeURIComponent(name) + "/pull-rules");
    } catch (error) {
      holder.innerHTML = '<p class="text-xs text-muted-foreground">' +
        escapeHtml(error.message) + "</p>";
      return;
    }
    const updated = data.updatedAt
      ? '<p class="text-[11px] text-muted-foreground">Last changed by ' +
          escapeHtml(data.updatedBy || "an admin") + " on " +
          escapeHtml(new Date(data.updatedAt).toLocaleString()) + ".</p>"
      : "";
    holder.innerHTML = updated + pullRulesEditorHtml(data.policy, {
      editable: data.canManage === true,
      models: data.models,
      saveLabel: "Save organization rules",
    });
    window.lucide?.createIcons();
    bindPullRulesEditor(holder, {
      models: data.models,
      onSave: async (policy) => {
        try {
          await orgApiRequest(
            "POST", "/api/orgs/" + encodeURIComponent(name) + "/pull-rules",
            { policy });
        } catch (error) {
          throw new Error(error.data?.message || error.message);
        }
        return policy.rules.length
          ? "Saved. Every pull request on a linked repository is checked against these rules."
          : "Saved. This organization sets no pull request rules.";
      },
    });
  }

  function orgRemoteMcpPrompt(name, mode, token) {
    const deploy = mode === "deploy";
    const configuration = {
      mcpServers: {
        forkmesh: {
          type: "http",
          url: publicSiteOrigin() + "/mcp",
          headers: {
            Authorization: "Bearer " + token,
          },
        },
      },
    };
    const finish = deploy
      ? [
          "Fetch the latest main again and integrate it into the task branch without force-pushing.",
          "Push the branch, merge only when the merge and required checks are clean, then deploy using the repository's documented deploy command.",
          "Verify the live revision and production behavior. Only then call complete_org_task with the commit, deployed revision, tests, and exact QA steps.",
        ]
      : [
          `Push the task branch and open a focused pull request against main using the repository's normal ${platformName()} tooling.`,
          "Do not merge or deploy. After the pull request exists, call complete_org_task with its number, branch, tests, and exact QA steps.",
        ];
    return [
      "Configure the following remote Streamable HTTP MCP server named forkmesh, then immediately use it for this assignment:",
      "",
      JSON.stringify(configuration, null, 2),
      "",
      `Work the shared task list for the ${name} organization.`,
      "1. Call list_org_tasks. Select the highest-priority unfinished task routed to an agent or explicitly unassigned with a linked repository. Never take a task assigned to a person.",
      "2. Call get_org_task for the selected id. Read its repository instructions and inspect the latest main branch before planning.",
      "3. Keep the base checkout untouched. Fetch main and create a dedicated worktree and task branch. Never stash, reset, clean, commit, or edit the base checkout.",
      "4. Work only in that task worktree. Preserve unrelated changes, implement the smallest complete fix, and run focused tests plus repository-required checks.",
      "5. Commit only the task files with a clear message. Never force-push or bypass failing checks or conflicts.",
      ...finish.map((line, index) => `${index + 6}. ${line}`),
      "",
      "If credentials, authorization, infrastructure, tests, or conflict resolution block safe completion, report the blocker and do not mark the task complete. Treat the bearer credential above as a secret; never print it in logs, commits, pull requests, task notes, or chat. It can be revoked from Organization Admin.",
    ].join("\n");
  }

  function orgRemoteMcpSetup(name) {
    const workflows = [
      {
        id: "pr",
        icon: "git-pull-request-arrow",
        title: "Remote MCP → pull request",
        description: "Creates an isolated task branch and pull request, then sends the completed task to QA without deploying.",
      },
      {
        id: "deploy",
        icon: "rocket",
        title: "Remote MCP → verified deployment",
        description: "Creates isolated work, synchronizes it safely, deploys, verifies production, and then sends the task to QA.",
      },
    ];
    return '<section class="mt-6 rounded-md border border-border bg-card p-4" data-org-remote-mcp>' +
      '<div class="flex items-center gap-2"><i data-lucide="plug-zap" class="h-4 w-4 text-muted-foreground"></i>' +
        '<h4 class="text-sm font-semibold text-foreground">Remote ' + escapeHtml(platformName()) + ' MCP</h4></div>' +
      '<p class="mt-1 max-w-3xl text-xs leading-5 text-muted-foreground">Generate a revocable task-only credential and one complete paste block. It connects the agent directly to <span class="font-mono text-foreground">' +
        escapeHtml(publicSiteOrigin() + "/mcp") +
        '</span>; there is no local Python server, repository path, or Qt connector token to fill in.</p>' +
      '<div class="mt-4 grid gap-4 xl:grid-cols-2">' +
        workflows.map((workflow) =>
          '<article class="rounded-md border border-border bg-card p-3" data-org-remote-mcp-workflow="' + workflow.id + '">' +
            '<div class="flex items-start gap-2"><i data-lucide="' + workflow.icon + '" class="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground"></i>' +
              '<div class="min-w-0 flex-1"><h5 class="text-sm font-semibold text-foreground">' + workflow.title + '</h5>' +
              '<p class="mt-1 text-[11px] leading-4 text-muted-foreground">' + workflow.description + "</p></div></div>" +
            '<button type="button" data-org-remote-mcp-generate="' + workflow.id + '" class="' + ORG_BTN_SECONDARY + ' fm-btn-sm mt-3">' +
              '<i data-lucide="key-round"></i> Generate complete setup</button>' +
            '<div data-org-remote-mcp-output="' + workflow.id + '" hidden class="mt-3">' +
              '<p class="flex items-center gap-1.5 text-xs font-semibold text-attention"><i data-lucide="triangle-alert" class="h-3.5 w-3.5 shrink-0"></i>Shown once. This block contains a live credential.</p>' +
              '<textarea readonly rows="20" spellcheck="false" class="mt-1 w-full resize-y rounded-md border border-border bg-background p-2 font-mono text-[10px] leading-4 text-foreground"></textarea>' +
              '<button type="button" data-org-remote-mcp-copy="' + workflow.id + '" class="' + ORG_BTN_SECONDARY + ' fm-btn-sm mt-2"><i data-lucide="copy"></i> Copy complete prompt</button>' +
            "</div>" +
          "</article>"
        ).join("") +
      "</div>" +
      '<p data-org-remote-mcp-status class="mt-3 min-h-4 text-xs text-muted-foreground" role="status"></p>' +
    "</section>";
  }

  function renderOrgDetail(
    root, name, profile, members, teams, repos, fediverse, botTokens,
  ) {
    const canManage = profile.viewerRole === "owner" || profile.viewerRole === "admin";
    const isOwner = profile.viewerRole === "owner";
    const title = escapeHtml(profile.displayName || profile.org || name);
    const worldAccess = {
      lobby: profile.worldAccess?.lobby || "public",
      floors: profile.worldAccess?.floors || "restricted",
      offices: profile.worldAccess?.offices || "restricted",
    };
    const worldSettings = canManage
      ? '<form data-org-world-settings class="mt-5 grid gap-3 rounded-md border border-border bg-card p-4">' +
          '<div><h4 class="text-sm font-semibold text-foreground">World building</h4>' +
          '<p class="mt-1 text-xs leading-5 text-muted-foreground">Set the public identity of this building and independently control its lobby, repository floors, and personal offices. Restricted spaces are visible to organization members; private spaces are limited to owners and administrators.</p></div>' +
          '<div class="grid gap-3 md:grid-cols-2">' +
            '<label class="grid gap-1 text-xs font-semibold text-foreground">Display name' +
              '<input data-org-world-display maxlength="80" value="' + escapeHtml(profile.displayName || "") + '" class="' + ORG_INPUT_CLASS + '" /></label>' +
            '<label class="grid gap-1 text-xs font-semibold text-foreground">HTTPS logo URL' +
              '<input data-org-world-logo type="url" inputmode="url" maxlength="500" value="' + escapeHtml(profile.logoUrl || "") + '" placeholder="https://…" class="' + ORG_INPUT_CLASS + '" /></label>' +
          '</div>' +
          '<label class="grid gap-1 text-xs font-semibold text-foreground">Description' +
            '<textarea data-org-world-description maxlength="500" rows="3" class="' + ORG_INPUT_CLASS + ' h-auto py-2">' + escapeHtml(profile.description || "") + "</textarea></label>" +
          '<div class="grid gap-3 sm:grid-cols-3">' +
            '<label class="grid gap-1 text-xs font-semibold text-foreground">Lobby access<select data-org-world-lobby class="' + ORG_INPUT_CLASS + '">' +
              orgOptionTags(ORG_WORLD_ACCESS_OPTIONS, worldAccess.lobby) + "</select></label>" +
            '<label class="grid gap-1 text-xs font-semibold text-foreground">Repository floors<select data-org-world-floors class="' + ORG_INPUT_CLASS + '">' +
              orgOptionTags(ORG_WORLD_ACCESS_OPTIONS, worldAccess.floors) + "</select></label>" +
            '<label class="grid gap-1 text-xs font-semibold text-foreground">Personal offices<select data-org-world-offices class="' + ORG_INPUT_CLASS + '">' +
              orgOptionTags(ORG_WORLD_ACCESS_OPTIONS, worldAccess.offices) + "</select></label>" +
          "</div>" +
          '<button type="submit" class="' + ORG_BTN_SECONDARY + ' w-fit">Save world settings</button>' +
        "</form>"
      : '<section class="mt-5 rounded-md border border-border bg-card p-4">' +
          '<h4 class="text-sm font-semibold text-foreground">World building access</h4>' +
          '<p class="mt-1 text-xs text-muted-foreground">Lobby: ' + escapeHtml(worldAccess.lobby) +
          " · floors: " + escapeHtml(worldAccess.floors) +
          " · offices: " + escapeHtml(worldAccess.offices) + "</p></section>";

    const memberRows = members.map((member) => {
      const memberName = escapeHtml(member.name || "");
      rememberUserNameCase(member.name, member.nameCase);
      const controls = canManage
        ? '<select data-org-member-role="' + memberName + '" class="' + ORG_INPUT_CLASS + ' h-8 py-0">' +
            orgOptionTags(ORG_ROLE_OPTIONS, member.role) + "</select>" +
          '<button type="button" data-org-member-remove="' + memberName + '" title="Remove from org" ' +
            'class="fm-btn fm-btn-sm fm-btn-icon fm-btn-danger">' +
            '<i data-lucide="user-minus" class="h-4 w-4"></i></button>'
        : orgRoleBadge(member.role);
      return '<div class="rounded-md border border-border bg-card px-3 py-2">' +
        '<div class="flex items-center gap-2">' +
          '<span class="min-w-0 flex-1 truncate text-sm font-medium text-foreground">' + userNameHtml(member.name || "") + "</span>" +
          controls +
        "</div>" +
        orgMemberFloorGroups(member, canManage) +
      "</div>";
    }).join("") || '<p class="text-sm text-muted-foreground">No members.</p>';

    const teamRows = teams.map((team) => {
      const teamName = escapeHtml(team.team || "");
      const controls = canManage
        ? '<select data-org-team-perm="' + teamName + '" class="' + ORG_INPUT_CLASS + ' h-8 py-0">' +
            orgOptionTags(ORG_TEAM_PERMISSIONS, team.permission) + "</select>" +
          '<button type="button" data-org-team-delete="' + teamName + '" title="Delete team" ' +
            'class="fm-btn fm-btn-sm fm-btn-icon fm-btn-danger">' +
            '<i data-lucide="trash-2" class="h-4 w-4"></i></button>'
        : '<span class="inline-flex items-center rounded-full border border-border bg-secondary px-2 py-0.5 text-xs font-semibold text-muted-foreground">' +
            escapeHtml(team.permission || "") + "</span>";
      return '<div class="flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2">' +
        '<button type="button" data-org-team-open="' + teamName + '" class="min-w-0 flex-1 truncate text-left text-sm font-medium text-foreground hover:underline">' +
          teamName + ' <span class="text-xs text-muted-foreground">· ' + (team.members || 0) + ' member' + ((team.members === 1) ? "" : "s") + "</span></button>" +
        controls + "</div>";
    }).join("") || '<p class="text-sm text-muted-foreground">No teams.</p>';

    const repoRows = repos.map((repo) => {
      const repoName = escapeHtml(repo.repo || "");
      const serves = repo.node ? '<span class="text-xs text-muted-foreground">serves ' + escapeHtml(repo.node) + "/" + repoName + "</span>" : "";
      const control = canManage
        ? '<button type="button" data-org-repo-unlink="' + repoName + '" title="Unlink repo" ' +
            'class="fm-btn fm-btn-sm fm-btn-icon fm-btn-danger">' +
            '<i data-lucide="unlink" class="h-4 w-4"></i></button>'
        : "";
      return '<div class="flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2">' +
        '<div class="min-w-0 flex-1"><div class="truncate text-sm font-medium text-foreground">' + escapeHtml(name) + "/" + repoName + "</div>" + serves + "</div>" +
        control + "</div>";
    }).join("") || '<p class="text-sm text-muted-foreground">No repos linked.</p>';

    const memberAdd = canManage
      ? '<form data-org-member-add class="mt-2 flex flex-wrap items-start gap-2">' +
          '<div class="min-w-[14rem] flex-1">' +
            '<input data-member-name list="org-member-suggestions" role="combobox" aria-autocomplete="list" aria-controls="org-member-suggestions" placeholder="Start typing an account name" autocomplete="off" class="' + ORG_INPUT_CLASS + ' w-full" />' +
            '<datalist id="org-member-suggestions" data-org-member-suggestions></datalist>' +
            '<p data-org-member-search-status class="mt-1 min-h-4 text-[11px] text-muted-foreground">Type a name to search active ' + escapeHtml(platformName()) + ' accounts.</p>' +
          "</div>" +
          '<select data-member-role class="' + ORG_INPUT_CLASS + '">' + orgOptionTags(ORG_ROLE_OPTIONS, "member") + "</select>" +
          '<button type="submit" class="' + ORG_BTN_SECONDARY + '">Add member</button></form>'
      : "";
    const teamAdd = canManage
      ? '<form data-org-team-add class="mt-2 flex flex-wrap items-center gap-2">' +
          '<input data-team-name placeholder="team name" autocomplete="off" class="' + ORG_INPUT_CLASS + ' flex-1 min-w-[10rem]" />' +
          '<select data-team-perm class="' + ORG_INPUT_CLASS + '">' + orgOptionTags(ORG_TEAM_PERMISSIONS, "read") + "</select>" +
          '<button type="submit" class="' + ORG_BTN_SECONDARY + '">Add team</button></form>'
      : "";
    const account = String(state.session?.nodeName || "").toLowerCase();
    const repoAdd = canManage
      ? '<form data-org-repo-add class="mt-2 flex flex-wrap items-center gap-2">' +
          '<input data-repo-name placeholder="repo name" autocomplete="off" class="' + ORG_INPUT_CLASS + ' flex-1 min-w-[10rem]" />' +
          '<input data-repo-node value="' + escapeHtml(account) + '" placeholder="your node" autocomplete="off" class="' + ORG_INPUT_CLASS + '" />' +
          '<button type="submit" class="' + ORG_BTN_SECONDARY + '">Link repo</button></form>'
      : "";
    const digestRows = (fediverse?.repos || []).map((item) => {
      const repoName = escapeHtml(item.repo || "");
      const preview = String(item.preview?.text || "").trim();
      const status = !item.ownerEnabled
        ? "Disabled by repository owner"
        : item.enabled ? "Eligible for daily digest" : "Disabled for organization";
      return '<details class="rounded-md border border-border bg-card p-3">' +
        '<summary class="cursor-pointer text-sm font-medium text-foreground">' +
          escapeHtml(name) + "/" + repoName +
          ' <span class="ml-1 text-xs font-normal text-muted-foreground">· ' +
          escapeHtml(status) + "</span></summary>" +
        '<pre class="mt-2 max-h-52 overflow-auto whitespace-pre-wrap break-words rounded bg-background p-2 font-mono text-[10px] leading-4 text-foreground">' +
          escapeHtml(preview || "No meaningful public updates are queued.") +
        "</pre></details>";
    }).join("") || '<p class="text-sm text-muted-foreground">No public linked repositories have queued updates.</p>';
    const digestControls = canManage
      ? '<section class="mt-6" data-org-fediverse-controls>' +
          '<div class="flex items-start justify-between gap-4">' +
            '<div><h4 class="text-sm font-semibold text-foreground">Fediverse daily digests</h4>' +
            '<p class="mt-1 max-w-2xl text-xs leading-5 text-muted-foreground">Combine meaningful public updates for each organization alias into at most one clearly automated post per 24 hours. Repository-owner federation settings remain authoritative; empty posts are never sent.</p></div>' +
            '<label class="inline-flex shrink-0 items-center gap-2 text-xs font-semibold text-foreground"><input data-org-fediverse-enabled type="checkbox" class="h-4 w-4"' +
              (fediverse?.controls?.enabled !== false ? " checked" : "") +
              " />Enabled</label>" +
          "</div>" +
          '<div class="mt-3 grid gap-2">' + digestRows + "</div>" +
        "</section>"
      : "";
    const botTokenControls = canManage
      ? (() => {
          const permissionRows = (botTokens?.permissions || []).map((permission) =>
            '<label class="flex items-start gap-2 rounded-md border border-border bg-background px-3 py-2 text-xs text-foreground">' +
              '<input type="checkbox" data-org-bot-scope value="' +
                escapeHtml(permission.scope || "") + '" class="mt-0.5 h-4 w-4"' +
                (permission.default === false ? "" : " checked") + " />" +
              '<span><strong class="font-mono">' +
                escapeHtml(permission.scope || "") + "</strong>" +
                '<span class="mt-0.5 block leading-4 text-muted-foreground">' +
                  escapeHtml(permission.description || "") +
                "</span></span></label>"
          ).join("");
          const tokenRows = (botTokens?.tokens || []).map((token) => {
            const revoked = Number(token.revokedAt || 0) > 0;
            const linked = token.deviceName
              ? "linked to " + escapeHtml(token.deviceName)
              : "not linked yet";
            return '<div class="rounded-md border border-border bg-card p-3">' +
              '<div class="flex items-start gap-3">' +
                '<div class="min-w-0 flex-1"><strong class="block truncate text-sm text-foreground">' +
                  escapeHtml(token.label || token.provider || "Bot") +
                "</strong>" +
                '<span class="mt-1 block text-xs text-muted-foreground">' +
                  escapeHtml(token.provider || "") + " · " + linked +
                  (revoked ? " · revoked" : "") + "</span></div>" +
                (!revoked
                  ? '<button type="button" data-org-bot-revoke="' +
                      escapeHtml(token.id || "") + '" class="' +
                      ORG_BTN_SECONDARY + ' fm-btn-sm fm-btn-danger">Revoke</button>'
                  : "") +
              "</div>" +
              '<p class="mt-2 break-all font-mono text-[10px] text-muted-foreground">' +
                escapeHtml((token.scopes || []).join(" · ")) + "</p></div>";
          }).join("") || '<p class="text-sm text-muted-foreground">No bot tokens yet.</p>';
          const usageRows = (botTokens?.usagePreview || []).slice(0, 5).map((usage) =>
            '<li class="flex items-start justify-between gap-3 rounded-md border border-border bg-background px-3 py-2">' +
              '<span class="min-w-0"><strong class="block truncate text-xs text-foreground">' +
                escapeHtml(usage.label || usage.provider || "Bot token") +
              '</strong><span class="mt-0.5 block truncate font-mono text-[10px] text-muted-foreground">' +
                escapeHtml((usage.method || "GET") + " " + (usage.action || "/api/bot/session")) +
              "</span></span>" +
              '<time class="shrink-0 text-[10px] text-muted-foreground" title="' +
                escapeHtml(formatDate(Number(usage.usedAt || 0))) + '">' +
                escapeHtml(formatTimeAgo(Number(usage.usedAt || 0))) +
              "</time></li>"
          ).join("") || '<li class="text-xs text-muted-foreground">No token use recorded yet.</li>';
          return '<section class="mt-6 rounded-md border border-border bg-card p-4" data-org-bot-tokens>' +
            '<div class="flex items-center gap-2"><i data-lucide="bot" class="h-4 w-4 text-muted-foreground"></i>' +
              '<h4 class="text-sm font-semibold text-foreground">Bot tokens</h4></div>' +
            '<p class="mt-1 text-xs leading-5 text-muted-foreground">Create a revocable Codex or Claude credential for an attended local computer. The secret is shown once. Destructive node, membership, organization-administration, and merge permissions are intentionally unavailable.</p>' +
            '<form data-org-bot-create class="mt-4 grid gap-3">' +
              '<div class="grid gap-3 sm:grid-cols-3">' +
                '<label class="grid gap-1 text-xs font-semibold text-foreground">Provider<select data-org-bot-provider class="' +
                  ORG_INPUT_CLASS + '"><option value="codex">Codex</option><option value="claude-code">Claude Code</option></select></label>' +
                '<label class="grid gap-1 text-xs font-semibold text-foreground">Label<input data-org-bot-label maxlength="80" value="Codex bot" class="' +
                  ORG_INPUT_CLASS + '" /></label>' +
                '<label class="grid gap-1 text-xs font-semibold text-foreground">Expires in days<input data-org-bot-expiry type="number" min="1" max="365" value="90" class="' +
                  ORG_INPUT_CLASS + '" /></label>' +
              "</div>" +
              '<div><span class="text-xs font-semibold text-foreground">Permissions</span>' +
                '<div class="mt-2 grid gap-2 md:grid-cols-2">' + permissionRows + "</div></div>" +
              '<button type="submit" class="' + ORG_BTN_PRIMARY + ' w-fit">Create bot token</button>' +
            "</form>" +
            '<div data-org-bot-secret hidden class="mt-4 rounded-md border border-attention/40 bg-attention/10 p-3"></div>' +
            '<div class="mt-4 grid gap-2">' + tokenRows + "</div>" +
            '<div class="mt-5 border-t border-border pt-4" data-org-bot-usage-preview>' +
              '<h5 class="text-xs font-semibold text-foreground">Recent token use</h5>' +
              '<p class="mt-1 text-[11px] leading-4 text-muted-foreground">Latest five successful authentications. The full metadata-only log is available to platform administrators; secrets, bodies, network addresses, and user agents are never logged.</p>' +
              '<ol class="mt-2 grid gap-2">' + usageRows + "</ol>" +
            "</div>" +
          "</section>";
        })()
      : "";
    const accessSummary =
      '<aside class="rounded-md border border-border bg-subtle p-4 lg:sticky lg:top-4 lg:self-start" data-org-access-summary>' +
        '<div class="flex items-center gap-2"><i data-lucide="shield-check" class="h-4 w-4 text-muted-foreground"></i>' +
          '<h4 class="text-sm font-semibold text-foreground">What organization access means</h4></div>' +
        '<div class="mt-3 grid gap-3 text-xs leading-5 text-muted-foreground">' +
          '<section><strong class="block text-foreground">Every organization member can</strong>' +
            '<ul class="mt-1 list-disc space-y-1 pl-5">' +
              '<li>View the organization, linked repositories, member directory, and teams.</li>' +
              '<li>Enter member-restricted World floors and see non-private organization activity.</li>' +
            "</ul></section>" +
          '<section><strong class="block text-foreground">Engineering team members can</strong>' +
            '<p class="mt-1">View organization agents and start, review, re-prompt, and continue Claude or Codex sessions on approved headless mirrors. This is checked server-side on every agent request; organization role alone does not grant access.</p></section>' +
          '<section><strong class="block text-foreground">Member role cannot</strong>' +
            '<p class="mt-1">Change organization settings, membership, teams, or repository links. Members outside Engineering also cannot view or control Claude/Codex sessions. Team permissions can grant repository work, but protected mirror approval and merge remain owner-only.</p></section>' +
          '<section><strong class="block text-foreground">Admin role adds</strong>' +
            '<p class="mt-1">Organization settings, members, teams, linked repositories, World access, and federation controls. Admins cannot remove the final owner.</p></section>' +
          '<section><strong class="block text-foreground">Owner role adds</strong>' +
            '<p class="mt-1">Owner-only protected mirror approval/merge controls and organization deletion. The organization must always retain one owner.</p></section>' +
          '<section><strong class="block text-foreground">Team permission</strong>' +
            '<p class="mt-1"><span class="font-mono text-foreground">read</span> views; <span class="font-mono text-foreground">write</span> changes content; <span class="font-mono text-foreground">maintain</span> manages repository work; <span class="font-mono text-foreground">admin</span> manages repository access. Team permission does not change the member’s organization role.</p></section>' +
        "</div>" +
      "</aside>";
    const memberAndTeamSettings =
      '<div class="mt-5 grid gap-6 lg:grid-cols-[minmax(0,1fr)_22rem]">' +
        '<div>' +
          '<section><h4 class="text-sm font-semibold text-foreground">Members</h4>' +
            '<div class="mt-2 grid gap-2">' + memberRows + "</div>" + memberAdd + "</section>" +
          '<section class="mt-6"><h4 class="text-sm font-semibold text-foreground">Teams</h4>' +
            '<div class="mt-2 grid gap-2">' + teamRows + "</div>" + teamAdd + "</section>" +
        "</div>" +
        accessSummary +
      "</div>";

    root.innerHTML =
      '<div class="flex items-center gap-3">' +
        '<button type="button" data-org-back class="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">' +
          '<i data-lucide="arrow-left" class="h-4 w-4"></i> Organizations</button>' +
        '<span class="flex-1"></span>' +
        (isOwner ? '<button type="button" data-org-delete class="fm-btn fm-btn-sm fm-btn-danger"><i data-lucide="trash-2"></i> Delete org</button>' : "") +
      "</div>" +
      '<div class="mt-4 flex items-center gap-3">' +
        '<h3 class="text-xl font-semibold text-foreground">' + title + "</h3>" +
        (profile.viewerRole ? orgRoleBadge(profile.viewerRole) : "") +
      "</div>" +
      (profile.description ? '<p class="mt-1 text-sm text-muted-foreground">' + escapeHtml(profile.description) + "</p>" : "") +
      worldSettings +
      '<p data-org-status class="mt-2 min-h-4 text-xs text-muted-foreground"></p>' +
      memberAndTeamSettings +
      '<section class="mt-6"><h4 class="text-sm font-semibold text-foreground">Linked repos</h4>' +
        '<div class="mt-2 grid gap-2">' + repoRows + "</div>" + repoAdd + "</section>" +
      digestControls +
      '<section class="mt-6" data-org-pull-rules-section>' +
        '<h4 class="text-sm font-semibold text-foreground">Pull request rules</h4>' +
        '<p class="mt-1 max-w-2xl text-xs leading-5 text-muted-foreground">Requirements every pull request on this organization\'s linked repositories must meet: tests, documentation, size, commit format, secrets, protected paths, or a required AI model. Each repository can add its own rules in <span class="font-mono">.forkmesh/pull-rules.json</span>. A failing rule is flagged on the pull request with how to fix it; a blocking one also locks the merge.</p>' +
        '<div data-org-pull-rules class="mt-3 text-xs text-muted-foreground">Loading rules…</div>' +
      "</section>" +
      botTokenControls +
      (canManage
        ? '<section class="mt-6" data-org-actions-secrets-section>' +
            '<h4 class="text-sm font-semibold text-foreground">Actions secrets</h4>' +
            '<div data-actions-secrets data-actions-secrets-scope="org" data-actions-secrets-base="' +
              escapeHtml("/api/org/" + encodeURIComponent(name) + "/actions/secrets") +
              '" class="mt-2 text-xs text-muted-foreground"></div>' +
          "</section>"
        : "") +
      (canManage ? orgRemoteMcpSetup(name) : "");

    window.lucide?.createIcons();
    mountActionsSecrets(root.querySelector("[data-org-actions-secrets-section] [data-actions-secrets]"));
    wireOrgDetail(root, name, members, teams);
  }

  function wireOrgDetail(root, name, members, teams) {
    const reload = () => showOrgDetail(name);
    const guard = async (fn) => {
      try {
        await fn();
        reload();
      } catch (error) {
        orgStatus(root, error.message, false);
      }
    };

    root.querySelector("[data-org-back]")?.addEventListener("click", showOrgsList);

    root.querySelector("[data-org-delete]")?.addEventListener("click", async () => {
      if (!await confirmAccountAction({
        title: "Delete " + name + "?",
        body: "This dissolves the org, its members, teams, and repo links. Linked repos are not deleted.",
        confirmLabel: "Delete organization",
      })) return;
      guard(() => orgApiRequest("DELETE", "/api/orgs/" + encodeURIComponent(name), {}).then(showOrgsList));
    });

    root.querySelector("[data-org-world-settings]")?.addEventListener("submit", (event) => {
      event.preventDefault();
      const worldAccess = {
        lobby: root.querySelector("[data-org-world-lobby]")?.value || "public",
        floors: root.querySelector("[data-org-world-floors]")?.value || "restricted",
        offices: root.querySelector("[data-org-world-offices]")?.value || "restricted",
      };
      guard(() => orgApiRequest("PATCH", "/api/orgs/" + encodeURIComponent(name), {
        displayName: (root.querySelector("[data-org-world-display]")?.value || "").trim(),
        description: (root.querySelector("[data-org-world-description]")?.value || "").trim(),
        logoUrl: (root.querySelector("[data-org-world-logo]")?.value || "").trim(),
        worldAccess,
      }));
    });

    root.querySelector("[data-org-member-add]")?.addEventListener("submit", (event) => {
      event.preventDefault();
      const member = (root.querySelector("[data-member-name]")?.value || "").trim().toLowerCase();
      const role = root.querySelector("[data-member-role]")?.value || "member";
      if (!member) return;
      guard(() => orgApiRequest("POST", "/api/orgs/" + encodeURIComponent(name) + "/members", { member, role }));
    });
    wireOrgMemberAutocomplete(root, members);
    root.querySelectorAll("[data-org-member-role]").forEach((select) => {
      select.addEventListener("change", () => {
        const member = select.dataset.orgMemberRole;
        guard(() => orgApiRequest("POST", "/api/orgs/" + encodeURIComponent(name) + "/members", { member, role: select.value }));
      });
    });
    root.querySelectorAll("[data-org-member-remove]").forEach((button) => {
      button.addEventListener("click", async () => {
        const member = button.dataset.orgMemberRemove;
        if (!await confirmAccountAction({ title: "Remove " + member + " from " + name + "?", confirmLabel: "Remove" })) return;
        guard(() => orgApiRequest("DELETE", "/api/orgs/" + encodeURIComponent(name) + "/members", { member }));
      });
    });
    root.querySelectorAll("[data-org-member-floor-group]").forEach((button) => {
      button.addEventListener("click", () => {
        const member = String(button.dataset.orgMember || "").trim().toLowerCase();
        const groupId = String(button.dataset.orgMemberFloorGroup || "");
        const group = ORG_OFFICE_FLOOR_GROUPS.find((item) => item.id === groupId);
        const memberRecord = members.find(
          (item) => String(item?.name || "").trim().toLowerCase() === member);
        if (!member || !group || !memberRecord) return;
        const memberships = new Set(
          (Array.isArray(memberRecord.teams) ? memberRecord.teams : [])
            .map((team) => String(team || "").trim().toLowerCase())
            .filter(Boolean),
        );
        const matchingTeams = group.aliases.filter((team) => memberships.has(team));
        const knownTeams = new Set(
          (Array.isArray(teams) ? teams : [])
            .map((team) => String(team?.team || "").trim().toLowerCase())
            .filter(Boolean),
        );
        button.disabled = true;
        button.setAttribute("aria-busy", "true");
        guard(async () => {
          if (matchingTeams.length) {
            for (const team of matchingTeams) {
              await orgApiRequest(
                "DELETE",
                "/api/orgs/" + encodeURIComponent(name) + "/teams/" +
                  encodeURIComponent(team) + "/members",
                { member },
              );
            }
            return;
          }
          const team = group.id;
          if (!knownTeams.has(team)) {
            await orgApiRequest(
              "POST",
              "/api/orgs/" + encodeURIComponent(name) + "/teams",
              { team, permission: "read" },
            );
          }
          await orgApiRequest(
            "POST",
            "/api/orgs/" + encodeURIComponent(name) + "/teams/" +
              encodeURIComponent(team) + "/members",
            { member },
          );
        });
      });
    });

    root.querySelector("[data-org-team-add]")?.addEventListener("submit", (event) => {
      event.preventDefault();
      const team = (root.querySelector("[data-team-name]")?.value || "").trim().toLowerCase();
      const permission = root.querySelector("[data-team-perm]")?.value || "read";
      if (!team) return;
      guard(() => orgApiRequest("POST", "/api/orgs/" + encodeURIComponent(name) + "/teams", { team, permission }));
    });
    root.querySelectorAll("[data-org-team-perm]").forEach((select) => {
      select.addEventListener("change", () => {
        const team = select.dataset.orgTeamPerm;
        guard(() => orgApiRequest("POST", "/api/orgs/" + encodeURIComponent(name) + "/teams", { team, permission: select.value }));
      });
    });
    root.querySelectorAll("[data-org-team-delete]").forEach((button) => {
      button.addEventListener("click", async () => {
        const team = button.dataset.orgTeamDelete;
        if (!await confirmAccountAction({ title: "Delete team " + team + "?", confirmLabel: "Delete team" })) return;
        guard(() => orgApiRequest("DELETE", "/api/orgs/" + encodeURIComponent(name) + "/teams", { team }));
      });
    });
    root.querySelectorAll("[data-org-team-open]").forEach((button) => {
      button.addEventListener("click", () => showOrgTeamDetail(name, button.dataset.orgTeamOpen, members));
    });

    root.querySelector("[data-org-repo-add]")?.addEventListener("submit", (event) => {
      event.preventDefault();
      const repo = (root.querySelector("[data-repo-name]")?.value || "").trim().toLowerCase();
      const node = (root.querySelector("[data-repo-node]")?.value || "").trim().toLowerCase();
      if (!repo) return;
      const body = { repo };
      if (node) body.node = node;
      guard(() => orgApiRequest("POST", "/api/orgs/" + encodeURIComponent(name) + "/repos", body));
    });
    root.querySelectorAll("[data-org-repo-unlink]").forEach((button) => {
      button.addEventListener("click", async () => {
        const repo = button.dataset.orgRepoUnlink;
        if (!await confirmAccountAction({ title: "Unlink " + name + "/" + repo + "?", confirmLabel: "Unlink" })) return;
        guard(() => orgApiRequest("DELETE", "/api/orgs/" + encodeURIComponent(name) + "/repos", { repo }));
      });
    });
    root.querySelector("[data-org-fediverse-enabled]")?.addEventListener(
      "change", (event) => {
        guard(() => orgApiRequest(
          "POST", "/api/orgs/" + encodeURIComponent(name) + "/fediverse",
          { enabled: Boolean(event.target.checked) }));
      });

    const botProvider = root.querySelector("[data-org-bot-provider]");
    const botLabel = root.querySelector("[data-org-bot-label]");
    botProvider?.addEventListener("change", () => {
      if (!botLabel) return;
      botLabel.value = botProvider.value === "claude-code"
        ? "Claude bot"
        : "Codex bot";
    });
    root.querySelector("[data-org-bot-create]")?.addEventListener(
      "submit", async (event) => {
        event.preventDefault();
        const secretPanel = root.querySelector("[data-org-bot-secret]");
        const scopes = [...root.querySelectorAll("[data-org-bot-scope]:checked")]
          .map((input) => input.value);
        try {
          const created = await orgApiRequest(
            "POST",
            "/api/orgs/" + encodeURIComponent(name) + "/bot-tokens",
            {
              provider: botProvider?.value || "codex",
              label: (botLabel?.value || "").trim(),
              expiresDays: Number(
                root.querySelector("[data-org-bot-expiry]")?.value || 90),
              scopes,
            },
          );
          if (!secretPanel) return;
          secretPanel.hidden = false;
          secretPanel.replaceChildren();
          const heading = document.createElement("strong");
          heading.className = "block text-sm text-foreground";
          heading.textContent = "Copy this token now — it cannot be recovered";
          const token = document.createElement("code");
          token.className =
            "mt-2 block select-all break-all rounded border border-border bg-background p-2 text-xs text-foreground";
          token.textContent = created.token || "";
          const instructions = document.createElement("p");
          instructions.className = "mt-2 text-xs leading-5 text-muted-foreground";
          instructions.textContent =
            "On the attended local computer, store it in FORKMESH_BOT_TOKEN, then POST /api/bot/session with a deviceName to bind and verify the connection. Revoking this row stops the credential immediately.";
          const copy = document.createElement("button");
          copy.type = "button";
          copy.className = ORG_BTN_SECONDARY + " fm-btn-sm mt-2";
          copy.textContent = "Copy token";
          copy.addEventListener("click", async () => {
            const copied = await copyTextToClipboard(created.token || "");
            copy.textContent = copied ? "Copied" : "Copy failed";
            window.setTimeout(() => { copy.textContent = "Copy token"; }, 1500);
          });
          secretPanel.append(heading, token, instructions, copy);
          orgStatus(root, "Bot token created. Copy it before leaving this page.", true);
        } catch (error) {
          orgStatus(root, error.message, false);
        }
      },
    );
    root.querySelectorAll("[data-org-bot-revoke]").forEach((button) => {
      button.addEventListener("click", async () => {
        if (!await confirmAccountAction({
          title: "Revoke this bot token?",
          body: "Its local connection and API access will stop immediately.",
          confirmLabel: "Revoke token",
        })) return;
        guard(() => orgApiRequest(
          "DELETE",
          "/api/orgs/" + encodeURIComponent(name) + "/bot-tokens",
          { tokenId: button.dataset.orgBotRevoke },
        ));
      });
    });
    root.querySelectorAll("[data-org-remote-mcp-generate]").forEach((button) => {
      button.addEventListener("click", async () => {
        const mode = button.dataset.orgRemoteMcpGenerate || "pr";
        const output = [...root.querySelectorAll("[data-org-remote-mcp-output]")]
          .find((element) => element.dataset.orgRemoteMcpOutput === mode);
        const status = root.querySelector("[data-org-remote-mcp-status]");
        button.disabled = true;
        if (status) {
          status.textContent = "Creating a revocable task-only credential…";
          status.className = "mt-3 min-h-4 text-xs text-muted-foreground";
        }
        try {
          const created = await orgApiRequest(
            "POST",
            "/api/orgs/" + encodeURIComponent(name) + "/bot-tokens",
            {
              provider: "codex",
              label: "Remote MCP " + (mode === "deploy" ? "deploy" : "pull request"),
              expiresDays: 90,
              scopes: [
                "organization.tasks.read",
                "organization.tasks.write",
              ],
            },
          );
          const prompt = orgRemoteMcpPrompt(name, mode, created.token || "");
          const textarea = output?.querySelector("textarea");
          if (textarea) textarea.value = prompt;
          if (output) output.hidden = false;
          await navigator.clipboard.writeText(prompt).catch(() => {});
          if (status) {
            status.textContent = "Complete remote setup generated and copied. Paste it into the agent once; no fields need editing.";
            status.className = "mt-3 min-h-4 text-xs text-muted-foreground";
          }
        } catch (error) {
          if (status) {
            status.textContent = error.message;
            status.className = "mt-3 min-h-4 text-xs text-destructive";
          }
        } finally {
          button.disabled = false;
        }
      });
    });
    root.querySelectorAll("[data-org-remote-mcp-copy]").forEach((button) => {
      button.addEventListener("click", async () => {
        const mode = button.dataset.orgRemoteMcpCopy || "pr";
        const output = [...root.querySelectorAll("[data-org-remote-mcp-output]")]
          .find((element) => element.dataset.orgRemoteMcpOutput === mode);
        const textarea = output?.querySelector("textarea");
        if (!textarea) return;
        try {
          await navigator.clipboard.writeText(textarea.value || "");
          const label = button.innerHTML;
          button.textContent = "Copied";
          window.setTimeout(() => { button.innerHTML = label; }, 1500);
        } catch (_) {
          textarea.focus();
          textarea.select();
        }
      });
    });
  }

  function wireOrgMemberAutocomplete(root, members) {
    const input = root.querySelector("[data-member-name]");
    const suggestions = root.querySelector("[data-org-member-suggestions]");
    const status = root.querySelector("[data-org-member-search-status]");
    if (!input || !suggestions || !status) return;
    const existing = new Set(
      (Array.isArray(members) ? members : [])
        .map((member) => String(member?.name || "").trim().toLowerCase())
        .filter(Boolean),
    );
    let timer = 0;
    let generation = 0;
    input.addEventListener("input", () => {
      window.clearTimeout(timer);
      const query = String(input.value || "").trim().toLowerCase();
      const currentGeneration = ++generation;
      suggestions.replaceChildren();
      if (!query) {
        status.textContent = `Type a name to search active ${platformName()} accounts.`;
        return;
      }
      status.textContent = "Searching active accounts…";
      timer = window.setTimeout(async () => {
        try {
          const data = await orgApiRequest(
            "GET",
            "/api/chat/direct-messages/users?query=" +
              encodeURIComponent(query),
          );
          if (currentGeneration !== generation) return;
          const names = (Array.isArray(data?.users) ? data.users : [])
            .map((user) => String(user?.name || "").trim().toLowerCase())
            .filter((account, index, all) =>
              account &&
              !existing.has(account) &&
              all.indexOf(account) === index
            )
            .slice(0, 12);
          const fragment = document.createDocumentFragment();
          names.forEach((account) => {
            const option = document.createElement("option");
            option.value = account;
            fragment.appendChild(option);
          });
          suggestions.replaceChildren(fragment);
          status.textContent = names.length
            ? `${names.length} matching active account${names.length === 1 ? "" : "s"}.`
            : "No matching account outside this organization.";
        } catch (_) {
          if (currentGeneration !== generation) return;
          status.textContent =
            "Account search is unavailable; an exact account name still works.";
        }
      }, 180);
    });
  }

  async function showOrgTeamDetail(name, team, orgMembers) {
    const root = orgsRoot();
    if (!root || !team) return;
    root.innerHTML = '<p class="text-sm text-muted-foreground">' + loadingHtml("Loading team…") + "</p>";
    let data;
    try {
      data = await orgApiRequest("GET", "/api/orgs/" + encodeURIComponent(name) + "/teams/" + encodeURIComponent(team) + "/members");
    } catch (error) {
      root.innerHTML =
        '<button type="button" data-org-team-back class="mb-4 inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">' +
        '<i data-lucide="arrow-left" class="h-4 w-4"></i> Back</button>' +
        '<p class="text-sm text-destructive">' + escapeHtml(error.message) + "</p>";
      window.lucide?.createIcons();
      root.querySelector("[data-org-team-back]")?.addEventListener("click", () => showOrgDetail(name));
      return;
    }
    const teamMembers = data.members || [];
    const onTeam = new Set(teamMembers.map((member) => member.name));
    const candidates = (orgMembers || []).filter((member) => !onTeam.has(member.name));
    const rows = teamMembers.map((member) => {
      const memberName = escapeHtml(member.name || "");
      return '<div class="flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2">' +
        '<span class="min-w-0 flex-1 truncate text-sm font-medium text-foreground">' + userNameHtml(member.name || "") +
          (member.external
            ? ' <small class="ml-1 rounded-full border border-border px-1.5 py-0.5 text-[10px] font-semibold text-muted-foreground">outside collaborator</small>'
            : "") + "</span>" +
        '<button type="button" data-org-team-member-remove="' + memberName + '" title="Remove from team" ' +
          'class="fm-btn fm-btn-sm fm-btn-icon fm-btn-danger">' +
          '<i data-lucide="x" class="h-4 w-4"></i></button></div>';
    }).join("") || '<p class="text-sm text-muted-foreground">No members on this team yet.</p>';
    const addForm =
      '<form data-org-team-member-add class="mt-3 grid gap-2 rounded-md border border-border bg-card p-3">' +
        '<div class="flex flex-wrap items-center gap-2">' +
          '<input data-team-member-name list="org-team-member-candidates" autocomplete="off" placeholder="' + escapeHtml(platformName()) + ' account name" class="' + ORG_INPUT_CLASS + ' flex-1 min-w-[10rem]" />' +
          '<datalist id="org-team-member-candidates">' +
            candidates.map((member) => '<option value="' + escapeHtml(member.name) + '"></option>').join("") +
          "</datalist>" +
          '<button type="submit" class="' + ORG_BTN_SECONDARY + '">Add to team</button>' +
        "</div>" +
        '<label class="flex items-start gap-2 text-xs leading-5 text-muted-foreground">' +
          '<input type="checkbox" data-team-member-external class="mt-1 h-4 w-4" />' +
          '<span><strong class="text-foreground">Outside collaborator</strong> — team-limited access only. This does not make the account an organization member and does not grant Office entry or repository permissions.</span>' +
        "</label>" +
      "</form>";
    root.innerHTML =
      '<button type="button" data-org-team-back class="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">' +
        '<i data-lucide="arrow-left" class="h-4 w-4"></i> ' + escapeHtml(name) + "</button>" +
      '<div class="mt-4 flex items-center gap-3"><h3 class="text-xl font-semibold text-foreground">' + escapeHtml(team) + "</h3>" +
        '<span class="inline-flex items-center rounded-full border border-border bg-secondary px-2 py-0.5 text-xs font-semibold text-muted-foreground">' + escapeHtml(data.permission || "") + " permission</span></div>" +
      '<p data-org-status class="mt-2 min-h-4 text-xs text-muted-foreground"></p>' +
      '<div class="mt-4 grid gap-2">' + rows + "</div>" + addForm;
    window.lucide?.createIcons();

    const guard = async (fn) => {
      try {
        await fn();
        showOrgTeamDetail(name, team, orgMembers);
      } catch (error) {
        orgStatus(root, error.message, false);
      }
    };
    root.querySelector("[data-org-team-back]")?.addEventListener("click", () => showOrgDetail(name));
    root.querySelector("[data-org-team-member-add]")?.addEventListener("submit", (event) => {
      event.preventDefault();
      const member = (root.querySelector("[data-team-member-name]")?.value || "").trim().toLowerCase();
      const external = root.querySelector("[data-team-member-external]")?.checked === true;
      if (!member) return;
      guard(() => orgApiRequest("POST", "/api/orgs/" + encodeURIComponent(name) + "/teams/" + encodeURIComponent(team) + "/members", { member, external }));
    });
    root.querySelectorAll("[data-org-team-member-remove]").forEach((button) => {
      button.addEventListener("click", () => {
        const member = button.dataset.orgTeamMemberRemove;
        guard(() => orgApiRequest("DELETE", "/api/orgs/" + encodeURIComponent(name) + "/teams/" + encodeURIComponent(team) + "/members", { member }));
      });
    });
  }

  function setMobileSidebarOpen(open) {
    document.body.classList.toggle("dashboard-sidebar-open", open);
    $$("[data-mobile-menu-toggle]").forEach((button) => {
      button.setAttribute("aria-expanded", open ? "true" : "false");
      button.setAttribute("aria-label", open ? "Close dashboard menu" : "Open dashboard menu");
    });
  }

  function closeMobileDrawers() {
    setMobileSidebarOpen(false);
  }

  function currentSection() {
    // The legacy section name is baked into the page document at build time
    // (dashboard_shell.PAGES[page]["section"] -> data-dashboard-section).
    return $("[data-dashboard-root]")?.dataset?.dashboardSection
      || $("[data-view].active")?.dataset?.view
      || "home";
  }

  function repoDocumentTitle(label, title) {
    const text = String(title || "");
    const at = text.lastIndexOf(" - ");
    return `${label}${at >= 0 ? text.slice(at) : ""}`;
  }

  function restoreDocumentTitle() {
    if (state.documentTitleBase === undefined) return;
    document.title = state.documentTitleBase;
    state.documentTitleBase = undefined;
  }

  function renderHeaderContext(section = currentSection()) {
    const headerContext = $("[data-dashboard-header-context]");
    if (!headerContext) return;
    const repoMeta = $("[data-repo-header-meta]");
    const repoVisibility = $("[data-repo-header-visibility]");
    const repoTerms = $("[data-repo-header-terms]");
    const repoAvailability = $("[data-repo-availability-status]");
    const repo = section === "explore" ? state.selectedRepo : null;
    if (repo) {
      const live = repoIsLive(repo);
      const viaMirror = repoServedByMirror(repo);
      // Owner and repository are separate links: the owner segment opens the
      // user's or organization's /@name page, the name opens the repository.
      // repoDisplayKey(repo) stays the single source of both labels.
      const [owner, ...nameParts] = repoDisplayKey(repo).split("/");
      const repoHref = repoLinkUrl(repo);
      const shortAddress = repoHref.split("/").filter(Boolean).length === 1;
      const repoLink = `<a href="${escapeHtml(repoHref)}" class="hover:underline">${escapeHtml(nameParts.join("/"))}</a>`;
      headerContext.innerHTML = owner && !shortAddress
        ? `<a href="${escapeHtml(publicProfileUrl(owner))}" data-repo-header-owner class="hover:underline">${escapeHtml(owner)}</a><span class="px-1 font-normal text-muted-foreground" aria-hidden="true">/</span>${repoLink}`
        : repoLink;
      if (shortAddress) {
        if (state.documentTitleBase === undefined) state.documentTitleBase = document.title;
        document.title = repoDocumentTitle(nameParts.join("/"), document.title);
      } else {
        restoreDocumentTitle();
      }
      repoMeta?.classList.add("sm:flex");
      if (repoVisibility) {
        repoVisibility.textContent = repo.isPrivate ? "private" : "public";
      }
      if (repoTerms) repoTerms.innerHTML = repositoryTermsBadge(repo, true);
      if (repoAvailability && dashboardOnInstance()) {
        repoAvailability.textContent = "";
        repoAvailability.classList.add("hidden");
      } else if (repoAvailability) {
        repoAvailability.classList.remove("hidden");
        const servedBy = String(state.repoServedBy?.name || "").trim();
        repoAvailability.textContent = servedBy
          ? `served by ${servedBy}`
          : viaMirror
            ? "served by mirror"
          : live
            ? "mirror online"
            : "mirror offline";
        repoAvailability.classList.toggle("text-success", live);
        repoAvailability.classList.toggle("text-muted-foreground", !live);
      }
      return;
    }
    restoreDocumentTitle();
    repoMeta?.classList.remove("sm:flex");
    if (repoVisibility) repoVisibility.textContent = "";
    if (repoTerms) repoTerms.innerHTML = "";
    if (repoAvailability) repoAvailability.textContent = "";
    if (section === "profile-overview" || section === "profile-repositories") {
      const renderedName = ($("[data-profile-page-node-name]")?.textContent || "").trim();
      headerContext.textContent = (state.session?.nodeName ? userDisplayName(state.session.nodeName) : "") || state.session?.email || renderedName || "Profile";
      return;
    }
    if (section === "profile") {
      headerContext.textContent = "Settings";
      return;
    }
    if (section === "repos") {
      headerContext.textContent = "Repositories";
      return;
    }
    if (section === "network") {
      headerContext.textContent = "Network";
      return;
    }
    if (section === "chat") {
      headerContext.textContent = "Chat";
      return;
    }
    if (section === "explore" && state.selectedRepo) {
      headerContext.textContent = repoKey(state.selectedRepo);
      return;
    }
    // No label for the dashboard itself: the logo already says where you are,
    // so the header keeps a page name only where it names something narrower.
    headerContext.textContent = "";
  }

  // ---- Public-profile mode (/@name) ---------------------------------------
  // The worker serves the SAME prebuilt profile documents at /@name; the
  // profile-page machinery renders whatever profileSubject() returns, so
  // public mode is: fetch the named account's public payload, park it in
  // state.publicProfile, and strip the owner-only chrome.

  function publicProfileNameFromPath() {
    const match = /^\/@([a-z][a-z0-9-]{0,62})(?:\/repositories)?\/?$/
      .exec(location.pathname.toLowerCase());
    return match ? match[1] : "";
  }

  function profileSubject() {
    return state.publicProfile || state.session;
  }

  // On /@name pages the profile markup belongs to the fetched PUBLIC profile;
  // the shared-chrome boot path still calls the profile renderers with the
  // session, which must not overwrite (or briefly flash) the wrong identity.
  function profileMarkupOwnedByPublicProfile(session) {
    const publicName = publicProfileNameFromPath();
    return Boolean(publicName) && session !== state.publicProfile &&
      publicName !== String(session?.nodeName || "").toLowerCase();
  }

  async function loadPublicProfile(name) {
    document.body.classList.add("public-profile-mode");
    let body = null;
    try {
      const viewer = state.session?.nodeName
        ? "?viewer=" + encodeURIComponent(state.session.nodeName) : "";
      body = await fetchJson("/api/accounts/" + encodeURIComponent(name) + viewer);
    } catch (_) {}
    if (!body || body.exists === false) {
      const organization = await fetchJson("/api/orgs/" + encodeURIComponent(name)).catch(() => null);
      if (organization?.ok) {
        loadPublicOrganizationProfile(name, organization);
        return;
      }
      $$("[data-profile-page-node-name]").forEach((el) => {
        el.textContent = "@" + name + " was not found";
      });
      return;
    }
    const profile = sessionFromAccountPayload(body, { nodeName: name });
    profile.nodeName = profile.nodeName || name;
    // Never show a mailbox on someone else's page — the handle is the
    // public identity here.
    profile.email = "@" + userDisplayName(profile.nodeName);
    profile.isFollowing = Boolean(body?.social?.isFollowing);
    state.publicProfile = profile;
    renderProfilePage(profile);
    applyPublicProfileChrome(profile);
    // Repository lists still use the catalog, while the native contribution
    // card reads its own account ledger after the public subject is installed.
    renderProfileContributionGraph();
    // Both the list AND the tab count are filtered by the profile subject, so
    // both have to be recomputed here: when the catalog lands before this
    // fetch, it counted against an empty subject and pinned the tab at 0.
    renderProfileRepositories();
    renderProfileRepositoryCount();
  }

  function loadPublicOrganizationProfile(name, organization) {
    const orgName = String(organization.org || name).toLowerCase();
    const profile = {
      kind: "organization",
      nodeName: orgName,
      email: "@" + orgName,
      status: "active",
      createdAt: Number(organization.createdAt) || 0,
      profileBio: organization.description || organization.displayName || "",
      displayName: String(organization.displayName || ""),
      logoUrl: String(organization.logoUrl || ""),
      memberCount: Number(organization.members) || 0,
      teamCount: Number(organization.teams) || 0,
    };
    state.publicProfile = profile;
    document.body.classList.add("organization-profile-mode");
    renderProfilePage(profile);
    applyPublicProfileChrome(profile);
    $$("[data-profile-contribution-card], [data-profile-overview-layout], [data-profile-sidebar-slot]")
      .forEach((el) => el.classList.add("hidden"));
    renderOrganizationProfileHeader(profile);
    renderProfileRepositories();
    renderProfileRepositoryCount();
  }

  function organizationSafeLogoUrl(value) {
    const url = String(value || "").trim();
    return /^(?:https:\/\/|\/(?!\/))[^\s"'<>]+$/i.test(url) ? url : "";
  }

  function renderOrganizationProfileHeader(profile) {
    const title = profile.displayName || profile.nodeName;
    $$("[data-org-profile-header]").forEach((header) => {
      header.hidden = false;
      const avatar = header.querySelector("[data-org-profile-avatar]");
      if (avatar) {
        const logo = organizationSafeLogoUrl(profile.logoUrl);
        avatar.innerHTML = logo
          ? `<img src="${escapeHtml(logo)}" alt="${escapeHtml(title)} logo" class="h-full w-full object-cover" />`
          : escapeHtml((title[0] || "F").toUpperCase());
      }
      const nameEl = header.querySelector("[data-org-profile-name]");
      if (nameEl) nameEl.textContent = title;
      const description = header.querySelector("[data-org-profile-description]");
      if (description) {
        description.textContent = profile.profileBio && profile.profileBio !== title ? profile.profileBio : "";
        description.hidden = !description.textContent;
      }
      const meta = header.querySelector("[data-org-profile-meta]");
      if (meta) {
        const url = publicProfileUrl(profile.nodeName);
        const items = [
          `<li class="inline-flex items-center gap-1.5"><i data-lucide="users" class="h-4 w-4"></i><span class="font-semibold text-foreground">${formatCount(profile.memberCount)}</span> ${profile.memberCount === 1 ? "member" : "members"}</li>`,
          `<li class="inline-flex items-center gap-1.5"><i data-lucide="link" class="h-4 w-4"></i><a href="${escapeHtml(url)}" class="text-foreground hover:text-accent hover:underline">${escapeHtml(url.replace(/^https?:\/\//, ""))}</a></li>`,
        ];
        if (profile.createdAt) {
          items.push(`<li class="inline-flex items-center gap-1.5"><i data-lucide="calendar" class="h-4 w-4"></i>Since ${escapeHtml(new Date(profile.createdAt).toLocaleDateString([], { month: "long", year: "numeric" }))}</li>`);
        }
        meta.innerHTML = items.join("");
      }
    });
    $$("[data-org-profile-people-count]").forEach((el) => { el.textContent = formatCount(profile.memberCount); });
    $$("[data-org-profile-teams-count]").forEach((el) => { el.textContent = formatCount(profile.teamCount); });
    $$("[data-org-profile-people-label]").forEach((el) => {
      el.textContent = profile.memberCount === 1 ? "member" : "members";
    });
    $$("[data-org-profile-teams-label]").forEach((el) => {
      el.textContent = profile.teamCount === 1 ? "team" : "teams";
    });
    $$("[data-org-profile-overview]").forEach((el) => { el.hidden = false; });
    window.lucide?.createIcons();
  }

  function organizationRepositoryLanguages(group) {
    const repos = [sourceOfTruth(group), ...(group.members || [])];
    const found = repos.map((repo) => repo?.logoMetadata?.languages)
      .find((languages) => languages && typeof languages === "object" && Object.keys(languages).length);
    return Object.entries(found || {})
      .filter(([language, weight]) => language !== "C/C++" && Number(weight) > 0)
      .map(([language, weight]) => [language, Number(weight)])
      .sort((a, b) => b[1] - a[1]);
  }

  function organizationPopularGroups(groups) {
    const score = (group) => (group.members || []).length * 1e9 +
      (Number(sourceOfTruth(group).commitCount) || 0);
    return [...groups].sort((a, b) => score(b) - score(a)).slice(0, 6);
  }

  const organizationPopularStarCounts = new Map();

  function organizationPopularStarCount(repo) {
    const key = repoKey(repo).toLowerCase();
    if (!organizationPopularStarCounts.has(key)) {
      organizationPopularStarCounts.set(key, fetch(`${repoApiBase(repo)}/star`, {
        headers: { accept: "application/json" },
      })
        .then((response) => response.ok ? response.json() : null)
        .then((data) => (data && data.ok !== false ? Number(data.count) || 0 : 0))
        .catch(() => {
          organizationPopularStarCounts.delete(key);
          return 0;
        }));
    }
    return organizationPopularStarCounts.get(key);
  }

  function hydrateOrganizationPopularStars(root) {
    root.querySelectorAll("[data-org-popular-star][data-repo-key]").forEach(async (holder) => {
      const repo = findRepository(holder.dataset.repoKey || "");
      if (!repo) return;
      const count = await organizationPopularStarCount(repo);
      if (!holder.isConnected || count <= 0) return;
      const value = holder.querySelector("[data-org-popular-star-count]");
      if (value) value.textContent = formatCount(count);
      holder.classList.remove("hidden");
    });
  }

  function organizationPopularCard(group) {
    const repo = sourceOfTruth(group);
    const languages = organizationRepositoryLanguages(group);
    const language = languages[0]?.[0] || String(repo.language || repo.primaryLanguage || "").trim();
    const color = REPO_LANGUAGE_COLORS[language] || "#8b949e";
    const description = repo.description ||
      (group.members || []).map((member) => member.description).find(Boolean) || "";
    return `<article data-org-popular-repo class="flex min-w-0 flex-col rounded-md border border-border bg-card p-4">
      <div class="flex min-w-0 items-center gap-2">
        <i data-lucide="book-marked" class="h-4 w-4 shrink-0 text-muted-foreground"></i>
        <a href="${escapeHtml(groupLinkUrl(group))}" class="min-w-0 truncate text-sm font-semibold text-accent hover:underline">${escapeHtml(repo.name || "repository")}</a>
        <span class="inline-flex shrink-0 items-center rounded-full border border-border px-[7px] text-xs font-medium leading-[18px] text-muted-foreground">${repo.isPrivate ? "Private" : "Public"}</span>
      </div>
      <p class="mb-4 mt-2 flex-1 break-words text-xs leading-5 text-muted-foreground">${escapeHtml(description)}</p>
      <p class="flex flex-wrap items-center gap-4 text-xs text-muted-foreground">
        ${language ? `<span class="inline-flex items-center gap-1"><span data-repo-language-dot class="inline-block h-3 w-3 shrink-0 rounded-full border border-black/10" style="background-color:${escapeHtml(color)}"></span><span>${escapeHtml(language)}</span></span>` : ""}
        <span data-org-popular-star data-repo-key="${escapeHtml(repoKey(repo))}" class="hidden inline-flex items-center gap-1"><i data-lucide="star" class="h-4 w-4"></i><span data-org-popular-star-count>0</span></span>
      </p>
    </article>`;
  }

  function renderOrganizationRepositories() {
    const popular = $("[data-org-profile-popular]");
    const languagesEl = $("[data-org-profile-languages]");
    if (profileSubject()?.kind !== "organization" || (!popular && !languagesEl)) return;
    const groups = profileRepositoryGroups();
    if (popular) {
      popular.innerHTML = groups.length
        ? organizationPopularGroups(groups).map(organizationPopularCard).join("")
        : `<p class="text-sm text-muted-foreground">This organization has no public repositories yet.</p>`;
      hydrateOrganizationPopularStars(popular);
    }
    $$("[data-org-profile-all-repos]").forEach((link) => {
      link.href = publicProfileUrl(profileSubject().nodeName, "/repositories");
    });
    if (languagesEl) {
      const totals = new Map();
      groups.forEach((group) => {
        organizationRepositoryLanguages(group).forEach(([language, weight]) => {
          totals.set(language, (totals.get(language) || 0) + weight);
        });
      });
      const ranked = [...totals.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5);
      languagesEl.innerHTML = ranked.length
        ? ranked.map(([language]) => `<span class="inline-flex items-center gap-1.5"><span class="h-2 w-2 rounded-full" style="background-color:${REPO_LANGUAGE_COLORS[language] || "#8a8a8a"}"></span>${escapeHtml(language)}</span>`).join("")
        : `<span>No language data yet.</span>`;
    }
    window.lucide?.createIcons();
  }

  function applyPublicProfileChrome(profile) {
    const name = profile.nodeName;
    // Tabs point at the public URLs, not the session dashboard pages.
    $$("[data-profile-tabs] a[href='/dashboard/profile']").forEach((a) => {
      a.href = publicProfileUrl(name);
    });
    $$("[data-profile-tabs] a[href='/dashboard/profile/repositories']").forEach((a) => {
      a.href = publicProfileUrl(name, "/repositories");
    });
    if (profile.kind === "organization") {
      $$("[data-profile-tabs] a[href='/dashboard/network']").forEach((a) => a.remove());
    }
    // Owner-only affordances become a Follow button (or disappear).
    $$("[data-profile-about-edit]").forEach((el) => el.classList.add("hidden"));
    $$("[data-profile-about-owner]").forEach((el) => { el.textContent = userDisplayName(name); });
    $$("[data-profile-sidebar-slot] a[href='/dashboard/settings']").forEach((edit) => {
      const wrap = edit.parentElement;
      edit.remove();
      if (!wrap || !state.session?.nodeName || profile.kind === "organization" ||
          state.session.nodeName.toLowerCase() === name) return;
      const follow = document.createElement("button");
      follow.type = "button";
      follow.setAttribute("data-profile-follow", name);
      follow.className = "flex w-full items-center justify-center rounded-md " +
        "border border-border bg-secondary px-3 py-1.5 text-sm font-semibold " +
        "text-foreground hover:bg-background";
      follow.textContent = profile.isFollowing ? "Following" : "Follow";
      follow.addEventListener("click", async () => {
        const following = follow.textContent === "Following";
        follow.disabled = true;
        try {
          const response = await fetch(
            "/api/accounts/" + encodeURIComponent(name) + "/follow", {
              method: following ? "DELETE" : "POST",
              headers: {
                "Content-Type": "application/json",
                Authorization: "Bearer " + (state.session?.sessionToken || ""),
              },
              body: JSON.stringify({
                sessionToken: state.session?.sessionToken || "",
              }),
            });
          if (response.ok) {
            follow.textContent = following ? "Follow" : "Following";
            const count = $("[data-profile-followers-count]");
            if (count) {
              const current = parseInt(count.textContent, 10) || 0;
              count.textContent = String(Math.max(0, current + (following ? -1 : 1)));
            }
          }
        } catch (_) {}
        follow.disabled = false;
      });
      wrap.append(follow);
      const official = new Set([
        "app.forkmesh.com", "forkmesh.com", "world.forkmesh.com",
      ]).has(location.hostname.toLowerCase());
      const message = document.createElement("a");
      message.setAttribute("data-profile-message", name);
      message.href = (official ? "https://app.forkmesh.com" : "") +
        "/chat?dm=" + encodeURIComponent(name);
      message.className = follow.className + " mt-2";
      message.textContent = "Message";
      message.title = "Open a private conversation with @" + name;
      wrap.append(message);
    });
  }

  function nodeNeedsReconnect(session) {
    // A guest has nothing to reconnect; a node-kind session IS the node.
    const signedIn = Boolean(session && (session.nodeName || session.email));
    if (!signedIn || session.kind === "node") return false;
    if (dashboardOnInstance()) return offlineLinkedNodes(session).length > 0;
    // Only flag when the account affirmatively has zero linked nodes. An absent
    // list means "unknown" (older payload), not "none" — stay quiet then.
    return Array.isArray(session.nodes) && session.nodes.length === 0;
  }

  function linkedNodeNames(session) {
    const nodes = Array.isArray(session?.nodes) ? session.nodes : [];
    return [...new Set(nodes.map((node) => String(node || "").trim().toLowerCase()).filter(Boolean))];
  }

  function offlineLinkedNodes(session) {
    const presence = state.linkedNodePresence || {};
    return linkedNodeNames(session).filter((node) => presence[node] === false);
  }

  let linkedNodePresenceKey = "";

  async function refreshLinkedNodePresence(session) {
    if (!dashboardOnInstance()) return;
    const nodes = linkedNodeNames(session).slice(0, 8);
    const key = nodes.join(",");
    if (key === linkedNodePresenceKey) return;
    linkedNodePresenceKey = key;
    const presence = {};
    await Promise.all(nodes.map(async (node) => {
      const body = await fetchJson("/api/accounts/" + encodeURIComponent(node), { fresh: true }).catch(() => null);
      if (body && body.exists !== false && body.kind === "node") presence[node] = body.online === true;
    }));
    if (linkedNodePresenceKey !== key) return;
    state.linkedNodePresence = presence;
    renderNodeReconnect(state.session);
  }

  function renderNodeReconnect(session) {
    const reconnect = $("[data-node-reconnect]");
    if (!reconnect) return;
    const show = nodeNeedsReconnect(session);
    reconnect.classList.toggle("hidden", !show);
    if (!show || !dashboardOnInstance()) return;
    const offline = offlineLinkedNodes(session);
    const names = offline.join(", ");
    const label = reconnect.querySelector("[data-node-reconnect-label]");
    if (label) label.textContent = offline.length > 1 ? "Desktops offline" : "Desktop offline";
    const message = (offline.length > 1 ? "Your desktop nodes " + names + " are" : "Your desktop node " + names + " is") +
      ` offline. Open the ${desktopBrand()}desktop app on that machine to reconnect it.`;
    reconnect.title = message;
    reconnect.setAttribute("aria-label", message);
  }

  function setEmailVerificationHint(message, kind = "") {
    const hint = $("[data-email-verification-hint]");
    if (!hint) return;
    hint.textContent = message ? " " + message : "";
    // Only utilities already present in the built dashboard/tailwind.css.
    hint.className = kind === "bad" ? "text-destructive"
      : kind === "good" ? "text-muted-foreground"
        : "text-attention";
  }

  // An unverified address blocks node renames and every account email, and the
  // resend control used to be buried in the profile modal behind a password
  // prompt. Surface it on every dashboard page until the address is confirmed.
  function renderEmailVerificationBanner(session) {
    const banner = $("[data-email-verification-banner]");
    if (!banner) return;
    const email = session?.email || "";
    const signedIn = Boolean(session && (session.nodeName || email));
    const show = signedIn && Boolean(email) && !session?.emailVerified;
    banner.classList.toggle("hidden", !show);
    banner.classList.toggle("flex", show);
    if (!show) {
      setEmailVerificationHint("");
      return;
    }
    const message = $("[data-email-verification-message]");
    if (message) {
      message.textContent =
        `${email} is not verified yet. Confirm it to rename your node and receive account email.`;
    }
    window.lucide?.createIcons();
  }

  // Away flag + custom status (user-status.js): the emoji sits on the header
  // avatar's corner, an amber dot marks away, and the account menu's two
  // entries say what a press will do.
  function renderDashboardUserStatus() {
    const userStatus = window.ForkMeshUserStatus;
    const statusItem = $("[data-account-menu-status]");
    const awayItem = $("[data-account-menu-away]");
    if (!userStatus) {
      statusItem?.remove();
      awayItem?.remove();
      return;
    }
    const own = userStatus.mine();
    const label = userStatus.describe({ ...own, away: false });
    const badge = $("[data-dashboard-user-status]");
    if (badge) {
      badge.textContent = userStatus.hasCustom(own) ? (own.emoji || "💬") : "";
      badge.hidden = !badge.textContent;
    }
    const awayDot = $("[data-dashboard-away-dot]");
    if (awayDot) awayDot.hidden = !own.away;
    const settingsButton = $("[data-profile-settings-button]");
    if (settingsButton) {
      settingsButton.title = ["Settings", own.away ? "Away" : "", label]
        .filter(Boolean).join(" · ");
    }
    if (statusItem) {
      statusItem.textContent = label ? "Edit status: " + label : "Set a status…";
    }
    if (awayItem) {
      awayItem.textContent = own.away ? "Set yourself active" : "Set yourself away";
    }
  }

  function watchDashboardUserStatus() {
    const userStatus = window.ForkMeshUserStatus;
    if (userStatus && state.session?.nodeName) {
      userStatus.subscribe(renderDashboardUserStatus);
      userStatus.loadMine();
    }
    renderDashboardUserStatus();
  }

  let pluginNavigationAccount = null;

  async function renderPluginNavigation(session) {
    const account = String(session?.nodeName || "");
    if (account === pluginNavigationAccount) return;
    pluginNavigationAccount = account;
    let installed = [];
    if (account) {
      try {
        installed = (await pluginRequest("/api/plugins/")).plugins || [];
        window.ForkMeshAPI?.rememberPlugins?.(account, installed);
        window.ForkMeshAPI?.rememberStatusPage?.(
          account, installed.includes("status-page"));
      } catch {
        pluginNavigationAccount = null;
      }
      if (pluginNavigationAccount !== account) return;
    }
    const visible = new Set(installed);
    let shown = 0;
    for (const link of $$("[data-plugin-nav]")) {
      const show = visible.has(link.dataset.pluginNav);
      link.classList.toggle("hidden", !show);
      if (show) shown += 1;
    }
    for (const group of $$("[data-plugin-navigation]")) {
      group.classList.toggle("hidden", !shown);
    }
  }

  window.addEventListener("forkmesh:plugins-changed", () => {
    pluginNavigationAccount = null;
    void renderPluginNavigation(state.session);
  });

  function renderProfile(session) {
    const name = session?.nodeName ? userDisplayName(session.nodeName) : (session?.email || "My Profile");
    const nameEl = $("[data-dashboard-profile-name]");
    const statusEl = $("[data-dashboard-profile-status]");
    const avatar = $("[data-dashboard-profile-avatar]");
    const adminButton = $("[data-admin-button]");
    const sidebarName = $("[data-sidebar-user-name]");

    if (nameEl) nameEl.textContent = name;
    if (sidebarName) sidebarName.textContent = name;
    if (statusEl) {
      statusEl.textContent = session?.emailVerified
        ? "Email verified"
        : "Verify email in profile";
    }
    applyAvatar(avatar, session);
    const publicProfileLink = $("[data-account-menu-public-profile]");
    if (publicProfileLink && session?.nodeName) {
      publicProfileLink.href = publicProfileUrl(session.nodeName);
    }
    renderAdminOnlyNavigation(session);
    void renderPluginNavigation(session);
    if (adminButton) {
      let adminUrl = session?.isAdmin ? (session?.adminUrl || "") : "";
      if (adminUrl && session?.nodeName && !/[?&]admin=/.test(adminUrl)) {
        adminUrl += (adminUrl.includes("?") ? "&" : "?") +
          "admin=" + encodeURIComponent(session.nodeName);
      }
      // Only show the button once we actually have somewhere to send it -
      // an admin session without adminUrl (ADMIN_PATH not picked up from the
      // Worker env yet) would otherwise show a button that links to "#".
      adminButton.classList.toggle("hidden", !adminUrl);
      adminButton.href = adminUrl || "#";
    }
    const adminMenuLink = $("[data-account-menu-admin]");
    if (adminMenuLink) {
      const consoleUrl = session?.isAdmin ? (session?.adminUrl || "") : "";
      adminMenuLink.classList.toggle("hidden", !consoleUrl);
      adminMenuLink.href = consoleUrl || "#";
    }
    // Reconnect affordance next to the avatar: a signed-in user account with no
    // node linked has nothing authenticated to drain its issues/chats/etc. to a
    // desktop, so surface the re-link flow (the Settings > Nodes claim/link
    // panel) instead of leaving the data stuck online. Shown only when we can
    // affirmatively tell there are zero linked nodes (session.nodes present and
    // empty) for a user-like account — never for a node session or when the
    // link state is simply unknown, to avoid a false alarm.
    renderNodeReconnect(session);
    void refreshLinkedNodePresence(session);
    renderEmailVerificationBanner(session);
    renderProfileModal(session);
    renderProfilePage(session);
    renderProfileAbout(session);
    // Canonical hydration can add linked-node aliases after the repository
    // catalog has already rendered. Recompute both profile repository views
    // from the newly stored identity so the tab count and list stay together.
    renderProfileRepositories();
    renderProfileRepositoryCount();
    renderHeaderContext();
  }

